const KEI=[{"id": "karasu", "no": "第一景", "name": "鴉", "yomi": "からす", "en": "Crow", "rep": "kyosai.jpg", "lead": "二千年、人のすぐ横にいた黒。害鳥と神の使いのあいだを、行ったり来たりしてきた鳥。", "nature": [["まちの二羽", "日本の街でよく会うのは、おもにハシブトガラスとハシボソガラス。太いくちばしと出っぱった額なら前者、細めのくちばしで濁った声なら後者、が手がかりとされる。"], ["かしこさ", "カラス科は鳥のなかでも大きな脳をもち、顔をおぼえる行動の研究が多い。ニューカレドニアガラスは小枝を加工して道具をつくることで知られる。"], ["二千年の同居", "漢の竈、聖書の荒野、江戸の松枝、パリの詩集——カラスは人の暮らしのすぐ横に二千年以上いた。揺れつづける読みの歴史ごと、この鳥の風景。"]], "invite": "帰り道で、カラスを一羽、見えなくなるまで見送ってみる。何をしていたか、一行だけ書きとめる。", "works": [{"f": "han.jpg", "date": "前100〜前1年ごろ", "place": "中国（前漢）", "title": "竈の模型のパネル：蛇をまとう人物にはさまれた烏", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1925.139", "note": "灰色の画像は拓本のように写る型物のパネルで、中央の鳥を、蛇をまとう二体の像がはさむ。二千年前の台所の道具に、太陽の鳥が住んでいる。"}, {"f": "luo.jpg", "date": "14世紀はじめ", "place": "中国（元）", "title": "古木寒鴉図（Crows in Old Trees）", "artist": "羅稚川", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/41193", "note": "冬枯れの大木に、点のような鴉が群れて止まる掛軸。にぎやかさではなく、さびしさを描くために鳥が選ばれた——東アジアの画題「寒鴉」の型。"}, {"f": "yogetsu.jpg", "date": "15世紀末（室町）", "place": "日本", "title": "木上の鴉（Crow on a Tree）", "artist": "楊月（画僧）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/35513", "note": "余白の多い紙に、墨の濃淡だけで一羽。羽のつやも重さも、線ではなく「にじみ」が担っている。"}, {"f": "pome.jpg", "date": "16世紀（室町）", "place": "日本", "title": "柘榴に鴉（Crow on a Pomegranate）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1974.30", "note": "実った柘榴の枝に黒い鳥。豊穣のしるしの実と、吉凶両方を背負わされてきた鳥のとりあわせ。朱い印がひとつ効いている。"}, {"f": "elijah.jpg", "date": "1604年", "place": "オランダ", "title": "荒野で烏に養われるエリヤ", "artist": "ヤン・サーンレダム（ブルーマールト原画）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/268396", "note": "木陰にひざまずく預言者エリヤへ、烏がパンを運んでくる銅版画。旧約聖書のこの場面のおかげで、ヨーロッパの烏は「神の使い」の顔も持ちつづけた。"}, {"f": "gillray.jpg", "date": "1794年", "place": "イギリス", "title": "「あなたにはプラック（文句）したいカラスが一羽いましてね！！」", "artist": "ジェームズ・ギルレイ", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/90155", "note": "部屋でカードに興じる二人の婦人のあいだに、黒い烏。英語の古い言い回し have a crow to pluck（＝文句がある）をそのまま絵にした風刺画。ことばの中に棲む烏。"}, {"f": "augury.jpg", "date": "1800年ごろ", "place": "インド（パハーリー派）", "title": "鴉の占い（Augury of the Crow — Vasakasajja Nayika）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1989.337", "note": "宮殿の庭で恋人を待つ女性の場面を描いた細密画。インドには鴉の声を「知らせ」として聴く伝統があるとされ、この画題の名がそのまま「鴉の占い」。"}, {"f": "daub.jpg", "date": "1867年", "place": "フランス", "title": "木の中の鴉たち（Crows in a Tree）", "artist": "シャルル＝フランソワ・ドービニー", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/43405", "note": "バルビゾンの野の木に、飛び交う鴉の群れを描いた版画。畑を荒らす害鳥か、虫を食う益鳥か——農村の論争ごと風景に入っている。"}, {"f": "homer.jpg", "date": "1868年", "place": "アメリカ", "title": "鴉を見張る（Watching the Crows）", "artist": "ウィンズロー・ホーマー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1942.1424", "note": "畑の見張りをする子どもを描いた木口木版。かかし（scarecrow＝鴉おどし）という語が示すとおり、農と鴉のつきあいは数千年になる。"}, {"f": "manet.jpg", "date": "1875年", "place": "フランス", "title": "パラスの胸像の上の大鴉（ポー『大鴉』挿絵）", "artist": "エドゥアール・マネ", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/111365", "note": "ポーの詩『大鴉』の挿絵として、マネが荒々しい墨のタッチで刷った石版画。烏はただ Nevermore と繰り返すだけなのに、人が勝手に意味を聴いてしまう——その構図ごと描かれている。"}, {"f": "kyosai.jpg", "date": "1868〜1889年ごろ（明治）", "place": "日本", "title": "松枝に鴉（Crow on Pine Branch）", "artist": "河鍋暁斎", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/28223", "note": "松の枝に一羽、こちらを向く鴉の掛物。暁斎は鴉の絵の名手として知られ、内国絵画共進会でも鴉図で名を上げたと伝わる。"}, {"f": "kyosai2.jpg", "date": "1880年代（明治）", "place": "日本", "title": "月に梅、鴉（Full Moon with Crow on Plum Branch）", "artist": "河鍋暁斎", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1930.203", "note": "月と梅と鴉。花鳥画の型の中で、黒い一羽が画面全体を締める。賛の文字と黒い枝ぶりが、書と絵の境目を曖昧にする。"}, {"f": "tlingit.jpg", "date": "19世紀末〜20世紀初", "place": "北米北西海岸（トリンギットほか）", "title": "ワタリガラスのガラガラ（Raven Rattle）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1921.1577", "note": "鳥の形に彫られ、赤と青緑で彩られた儀礼のガラガラ。北西海岸の神話では、ワタリガラスは世界に光をもたらしたトリックスターとされる。楽器が宇宙観を運ぶ。"}, {"f": "rackham.jpg", "date": "1913年", "place": "イギリス", "title": "リスと鴉（A Squirrel and a Crow）", "artist": "アーサー・ラッカム", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1954.653", "note": "20世紀の挿絵本から、木の枝のリスと鴉。物語の脇役として、鴉は子どもの本の中にも棲みつづけている。"}]}, {"id": "tsubame", "no": "第二景", "name": "燕", "yomi": "つばめ", "en": "Swallow", "rep": "tsubame03.jpg", "lead": "春を運んでくる同居人。天敵のカラスを避けて、わざわざ人の軒先に巣をかける。", "nature": [["人のそばで子育て", "ツバメは春に渡来し、民家や商店の軒先に巣をつくる。天敵を避けて、あえて人の近くで子育てするとされる。"], ["飛ぶかたち", "マネは燕を「形」ではなく黒い軌道で描いた。実際、燕は飛びながら虫を捕る鳥で、その速さこそが姿である。"], ["物差しとしての燕", "巣が今年もかかるかどうかは、その町の虫と水辺の量の便り。燕は、身近な環境の物差しでもある。"]], "invite": "今年、いちばん近くのツバメの巣がどこにあったか、思い出してみる。来年、同じ場所を見る。", "works": [{"f": "tsubame01.jpg", "date": "13世紀なかば（南宋）", "place": "中国", "title": "燕に蓮（Swallow and Lotus）", "artist": "牧谿", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1981.34", "note": "破れかけた蓮の葉の上に、うずくまる一羽。禅画の巨匠・牧谿の、湿った墨の空気ごと残る一枚。夏の終わりの気配まで描かれている。"}, {"f": "tsubame02.jpg", "date": "15世紀（室町）", "place": "日本", "title": "柳燕画賛（Calligraphy with Willow and Swallows）", "artist": "一休宗純", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2015.463", "note": "とんちの一休さんとして知られる禅僧・一休の書。柳と燕という春の取り合わせを、絵ではなく崩した墨の文字が運ぶ。"}, {"f": "tsubame03.jpg", "date": "1833〜34年ごろ（江戸）", "place": "日本", "title": "紫陽花に燕", "artist": "葛飾北斎", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/25117", "note": "黄色い空を切って、紫陽花の上を一羽が急降下する。燕の飛び方の「速さ」を、止まった絵で見せる北斎の腕。"}, {"f": "tsubame04.jpg", "date": "1830年代（江戸）", "place": "日本", "title": "桜に燕", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/25873", "note": "満開の枝に二羽。春の到来を告げる鳥として、燕は花鳥画の定番だった。"}, {"f": "tsubame05.jpg", "date": "1874年", "place": "フランス", "title": "燕たち（詩集『Le Fleuve』挿絵）", "artist": "エドゥアール・マネ", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/191528", "note": "野の上を矢のように交差する黒い影だけで燕を描いたエッチング。形ではなく「軌道」を描くという発明。"}, {"f": "tsubame06.jpg", "date": "1874年", "place": "アメリカ", "title": "砂燕のコロニー襲撃 ──「卵はいくつ？」", "artist": "ウィンスロー・ホーマー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1942.1320", "note": "崖の巣穴によじ登る少年たちと、舞い立つ燕の群れの木口木版。人と燕の距離の近さが、いたずらの形で記録されている。"}, {"f": "tsubame07.jpg", "date": "江戸時代", "place": "日本", "title": "松に燕の鍔", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1919.309", "note": "刀の鍔（つば）に透かし彫りされた燕。武具にまで春の鳥を住まわせる——工芸の中の自然。"}]}, {"id": "kaeru", "no": "第三景", "name": "蛙", "yomi": "かえる", "en": "Frog", "rep": "kaeru03.jpg", "lead": "五千年前の女神から、アール・ヌーヴォーのガラスまで。水際の声の主は、乾きに弱いからだで生きている。", "nature": [["皮膚で呼吸を補う", "カエルは両生類で、肺のほかに湿った皮膚でも呼吸を補う。だから乾燥に弱く、水辺の湿った環境に依存する。環境の変化に敏感な生きものとされる。"], ["再生のしるし", "ナイルの氾濫後に無数に現れる蛙は、エジプトで多産と再生の女神になった。増えることが、そのまま神性だった。"], ["日本の蛙", "京都・高山寺の鳥獣人物戯画（国宝）では、蛙が擬人化されて相撲をとる。日本の蛙は、九百年前から主役級である。"]], "invite": "夜、水辺のそばを通ったら、立ち止まって声の数をかぞえてみる。何種類に聞こえるか。", "works": [{"f": "kaeru01.jpg", "date": "前2950年ごろ", "place": "エジプト", "title": "蛙の女神ヘケトの像", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1976.5", "note": "約5000年前の、どっしりした石の蛙。ナイルの氾濫のあと無数に現れる蛙は、多産と再生の女神ヘケトになった。この帖でいちばん古い一点。"}, {"f": "kaeru02.jpg", "date": "前1540〜1296年ごろ", "place": "エジプト", "title": "蛙の護符", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1914.570", "note": "赤い石を磨いた、指先ほどの小さな蛙。身につけて持ち歩ける再生のしるし。"}, {"f": "kaeru03.jpg", "date": "前100〜後500年ごろ", "place": "ペルー（モチェ）", "title": "斑点のある蛙の壺", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/6312", "note": "アンデスのモチェ文化の鐙型注口土器。背の斑点まで写した観察の確かさで、二千年前の蛙の種類を考えたくなる。"}, {"f": "kaeru04.jpg", "date": "1000〜1500年ごろ", "place": "パナマ（ベラグアス）", "title": "蛙の金製ペンダント", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/8088", "note": "金をたたいて作られた蛙の飾り。中米では蛙は雨や豊穣と結びつく重要なモチーフだった。"}, {"f": "kaeru05.jpg", "date": "1560年ごろ", "place": "ムガル朝インド", "title": "蛇と蛙の言い争い（『トゥーティー・ナーマ』より）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1962.279.183.b", "note": "物語集の挿絵。岩場で蛇と蛙が「議論」している。生きものに言い分を持たせる語りは、擬人化の長い歴史の一頁。"}, {"f": "kaeru06.jpg", "date": "1909〜12年", "place": "フランス", "title": "蛙と睡蓮の花器", "artist": "ルネ・ラリック", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2007.180", "note": "ガラスの肩に、黒い蛙がはりついた花器。アール・ヌーヴォーは水辺の生きものを室内へ連れてきた。"}]}, {"id": "chou", "no": "第四景", "name": "蝶", "yomi": "ちょう", "en": "Butterfly", "rep": "chou02.jpg", "lead": "卵から幼虫、蛹、成虫へ——別の生きものに生まれ変わるからだ。魂や長寿のしるしを背負わされてきた。", "nature": [["完全変態", "チョウは卵→幼虫→蛹→成虫の完全変態をする。幼虫と成虫は食べるものも住む場所も違う——一生のなかで二度、別の生きものを生きる。"], ["翅の色のしくみ", "翅の色や模様は、表面をおおう鱗粉によるもの。色素の色に加えて、鱗粉の微細な構造が光を干渉させる構造色もある。"], ["意味を運ぶ翅", "エジプトの象嵌、唐の鏡、清の吉祥図、画家の署名——蝶ほど多くの「意味」を載せられてきた虫はいない。"]], "invite": "次に蝶を見かけたら、とまるまで目で追ってみる。翅を閉じたときの裏の模様まで見えたら上出来。", "works": [{"f": "chou01.jpg", "date": "前1350〜1296年ごろ", "place": "エジプト", "title": "蝶の象嵌", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1914.789", "note": "翅を開いた形に作られた3000年前の象嵌細工。縞の模様まで作りこまれている。蝶を「かたち」として愛でた最古級の証拠のひとつ。"}, {"f": "chou02.jpg", "date": "700年代（唐）", "place": "中国", "title": "鳳凰と鳥と蝶と花枝の鏡", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1973.74", "note": "青銅鏡の背面に、螺鈿と金銀で鳥と蝶が円く舞う。鏡＝月を思わせる円の中の、小さな宇宙。"}, {"f": "chou03.jpg", "date": "1300年代（元）", "place": "中国", "title": "百合と蝶", "artist": "劉善守", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1971.132", "note": "淡い墨の百合に、小さな蝶が寄る。派手さのない、息をひそめたような花鳥画。"}, {"f": "chou04.jpg", "date": "1495年ごろ", "place": "ドイツ", "title": "蝶のいる聖家族", "artist": "アルブレヒト・デューラー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1925.73", "note": "聖母子の足元の草むらに、一頭の蝶がひそむ銅版画。ヨーロッパでは蝶は魂や復活のしるしとも読まれた——隅にいるのに、意味の重い一頭。"}, {"f": "chou05.jpg", "date": "1600年代（江戸）", "place": "日本", "title": "『源氏物語』画帖より「胡蝶」", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1961.202.k", "note": "源氏物語五十四帖の「胡蝶」の帖を描いた画帖の一葉。庭に人が集う春の場面。物語の章の名になるほど、蝶は日本の美意識の中心にいた。"}, {"f": "chou06.jpg", "date": "1788年（清）", "place": "中国", "title": "猫と蝶", "artist": "閔貞", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1985.71.5", "note": "丸まって眠る猫の上に、蝶がひらり。猫（マオ）と蝶（ディエ）の発音が長寿を意味する「耄耋（もうてつ）」に通じることから、これは長寿を願う吉祥図。だじゃれが絵になり、贈り物になる。"}, {"f": "chou07.jpg", "date": "1890年ごろ", "place": "アメリカ", "title": "蝶（ホイッスラーのモノグラム）", "artist": "ジェームズ・マクニール・ホイッスラー", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/14488", "note": "ほとんど白い紙に、小さな蝶がひとつ。ホイッスラーは自分のイニシャルを図案化した蝶を署名として使った。画家自身が、蝶に「なった」例。"}]}, {"id": "matsu", "no": "第五景", "name": "松", "yomi": "まつ", "en": "Pine", "rep": "matsu02.jpg", "lead": "常緑の時間。雪の中でも変わらない緑は、長寿の背骨として描かれつづけた。根は、土の中で菌と組んでいる。", "nature": [["二本ずつの葉", "アカマツ・クロマツは常緑針葉樹で、葉が二本ずつ束になる二葉松。冬も落ちない葉が「常磐（ときわ）」の象徴になった。"], ["土の中の同盟", "マツタケは、生きたアカマツなどの根と共生する菌根菌とされる。松の絵の下には、いつも描かれない地下の同盟がある——土の聴診器が聴こうとしている世界と同じ場所。"], ["額縁としての松", "窪俊満の富士も、王蒙の書斎も、松越しに見える。東アジアの風景は長らく、松を通して見るものだった。"]], "invite": "松の木の下で、落ちた葉をひろって数えてみる。ほんとうに二本ずつ束になっているか。", "works": [{"f": "matsu01.jpg", "date": "14世紀（元）", "place": "中国", "title": "松下著書図（Writing Books under the Pine Trees）", "artist": "王蒙", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1997.94", "note": "うねる山肌の中腹、松の下に書き物をする人の小屋。文人にとって松の下は、書き、考えるための場所だった。"}, {"f": "matsu02.jpg", "date": "1530年代（明）", "place": "中国", "title": "古松図", "artist": "文徴明", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1964.43", "note": "横に長い紙を、一本の老松の枝がのたうちながら渡ってゆく。年月で曲がった幹こそが主役——長寿の象徴としての松。"}, {"f": "matsu03.jpg", "date": "1834年ごろ（江戸）", "place": "日本", "title": "雪松に鶴", "artist": "葛飾北斎", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/21720", "note": "藍の濃淡の雪松に鶴。松に鶴という縁起物の型を、北斎は色数を絞って引き締めた。"}, {"f": "matsu04.jpg", "date": "1830年代なかば（江戸）", "place": "日本", "title": "雪中松に雉", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/26283", "note": "雪をかぶった松に、色鮮やかな雉がとまる。常緑の松は、雪の中でこそ「変わらないもの」として描かれる。"}, {"f": "matsu05.jpg", "date": "18世紀末〜19世紀初（江戸）", "place": "日本", "title": "松間富士", "artist": "窪俊満", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1995.18", "note": "松の幹のあいだから、薄く富士がのぞく。手前の松が「額縁」になる構図——景色は、木を通して見るものだった。"}, {"f": "matsu06.jpg", "date": "1897年ごろ", "place": "イタリア", "title": "松の木", "artist": "ジョヴァンニ・セガンティーニ", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1982.124", "note": "アルプスの画家セガンティーニが、太い幹を画面いっぱいに描いた油彩。東洋の松の記号性と違い、こちらは「個体」としての一本。"}, {"f": "matsu07.jpg", "date": "1801年（江戸）", "place": "日本", "title": "長寿のしるし ── 桃と松の下の鹿", "artist": "戸田忠翰", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2015.86", "note": "桃・松・鹿と、長寿の象徴を重ねた二幅。めでたさの記号を束ねる文化の中で、松はいつも背骨の位置にいる。"}]}, {"id": "tsuru", "no": "第六景", "name": "鶴", "yomi": "つる", "en": "Crane", "rep": "tsuru06.jpg", "lead": "めでたさの記号として、絵の中を二千年飛びつづけてきた鳥。現実の鶴は一度、日本でもアメリカでも数十羽まで減り、人の手で戻ってきた。", "nature": [["よみがえったタンチョウ", "日本のタンチョウは北海道東部にすむ留鳥で、国の特別天然記念物。一時は絶滅したと考えられ、1924年に釧路湿原で十数羽が再発見された。1952年の一斉調査では33羽——それが保護と給餌で約1900羽まで回復し、2026年には環境省のレッドリストで絶滅危惧種から外れ、一段下の「準絶滅危惧」になった——1991年の指定から35年ぶりのことだった。"], ["万羽鶴の町・出水", "ナベヅルとマナヅルは冬、大陸から九州へ渡ってくる。鹿児島県出水市の平野には毎年1万羽を超える鶴が集まり、世界有数の越冬地として国の特別天然記念物に指定されている。2021年にはラムサール条約の湿地にも登録された。"], ["鳴き交わしと踊り", "タンチョウのつがいは、声をそろえて鳴き交わす。管楽器のように長い気管をもち、その声は1〜2km先まで届くとされる。冬には跳ね、翼を広げて向かい合う「ダンス」が見られ、つがいの絆を深める行動と考えられている。"]], "invite": "折り鶴をひとつ折って、首・翼・尾がどう省略されているか、この景の絵とくらべてみる。", "works": [{"f": "tsuru01.jpg", "date": "前475〜前221年", "place": "中国（戦国時代・楚）", "title": "鶴と蛇（Cranes and Serpents）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1938.9", "note": "朱と黒の漆で彩られた木彫。長い首の二羽が、とぐろを巻く蛇の台の上に立つ。楚の墓から出た太鼓の台とされ、くちばしに通した紐で太鼓を吊るしたと考えられている——二千数百年前の鶴は、楽器の一部だった。"}, {"f": "tsuru02.jpg", "date": "12世紀後半（高麗）", "place": "朝鮮半島", "title": "雲鶴と童子文の梅瓶（Plum Vase with Clouds, Cranes, and Children Motifs）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/73216", "note": "青緑の肌に、白い鶴が雲間を飛ぶ。彫った文様に白土や赤土を埋めて焼く象嵌の技法で、雲と鶴は長寿の願いを込めた高麗青磁の定番の取り合わせとされる。"}, {"f": "tsuru03.jpg", "date": "14〜15世紀初（明時代初期）", "place": "中国", "title": "竹林の鶴（Crane in a Bamboo Grove）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/39993", "note": "頭頂の赤、黒い首、風切の黒——タンチョウの特徴をそなえた一羽が、竹と岩のあいだに立つ。画面の高さは約166cm、ほぼ等身大の掛軸。中国で鶴は仙人の乗り物、長寿のしるしとされてきた。"}, {"f": "tsuru04.jpg", "date": "1766〜67年ごろ（江戸）", "place": "日本", "title": "鶴に乗る娘（費長房の見立）", "artist": "鈴木春信", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/44213", "note": "白い鶴の背に、手紙を読みながら乗る娘。鶴に乗って飛ぶ中国の仙人・費長房の図像を、当世の美人に置き換えた見立絵とされる。仙界の乗り物が、江戸の遊び心の素材になっている。"}, {"f": "tsuru05.jpg", "date": "1700年代後半", "place": "インド（ティルパティ）", "title": "鶴の魔神バカースラを退治するクリシュナ（Krishna Vanquishing the Crane-Demon Bakasura）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1966.29", "note": "青いクリシュナが、巨大な鳥のくちばしをつかんで引き裂く。インド神話で鶴は「魔神」の役も演じる——長寿のしるしとしての東アジアの鶴とは、まるで違う顔。右下には、正体を現して転げ落ちる魔神が小さく描かれている。"}, {"f": "tsuru06.jpg", "date": "1830年代（江戸）", "place": "日本", "title": "波に鶴と旭日（Crane, waves, and rising sun）", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/77320", "note": "砕ける波の上に丹頂、画面の隅に初日の出。「鶴は千年」——漢代の書物『淮南子』の「鶴の寿命は千歳」に由来するとされることわざを、そのまま摺りにしたような縁起物の一枚。頭頂の赤まで色を分けて摺られている。"}, {"f": "tsuru07.jpg", "date": "1850年（江戸）", "place": "日本", "title": "『応挙画譜』より 鶴（Crane from Ōkyo Picture Book）", "artist": "円山応挙", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1985.376.p", "note": "見開きをまるごと使って、舞い降りる一羽。写生を重んじた応挙の下絵にもとづき、没後の1850年に摺られた木版の画譜。本のとじ目が翼を横切るのも、頁という形式ならではの風景。"}, {"f": "tsuru08.jpg", "date": "1800年代（朝鮮王朝）", "place": "朝鮮半島", "title": "単鶴文の胸背（Rank Badge with Single Crane Motif）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2019.78.1", "note": "官服の胸と背に付ける刺繍の徽章。描かれる鳥獣の種類が位階を示し、一羽の鶴は上位の文官の印とされる。雲と波のあいだの白鶴には金糸が伏せ縫いでとめられ、役人は鶴を身にまとって出仕した。"}, {"f": "tsuru09.jpg", "date": "1888〜90年", "place": "アメリカ", "title": "アメリカシロヅル（煙草のおまけカード「猟鳥」シリーズより）", "artist": "アレン・アンド・ギンター社", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/421793", "note": "煙草の箱に封入された、手のひらより小さい「猟鳥」カードの一枚。北米のアメリカシロヅルは狩猟と湿地の開発で減りつづけ、1941年には野生で15羽ほどになったとされる。保護で500羽を超えるまで戻った——絵の小ささと、背負った物語の大きさが釣り合わない。"}]}, {"id": "neko", "no": "第七景", "name": "猫", "yomi": "ねこ", "en": "Cat", "rep": "neko07.jpg", "lead": "穀物を狙う鼠を追って、人の暮らしに自分から入ってきた狩人。神さまから同居人まで、一万年ぶんの顔をもつ。", "nature": [["ヤマネコから来た", "イエネコの祖先はリビアヤマネコで、農耕が始まったおよそ1万年前の西アジアで人のそばに現れたとされる。キプロス島には約9500年前に人と共に埋葬された猫の骨があり、人と猫のつきあいを示す最古級の証拠とされる。穀物が鼠を呼び、鼠が猫を呼んだ——という筋書きが有力である。"], ["夜のための目", "縦に細くなる瞳孔は開き幅が大きく、入る光の量を大きく調節できる。網膜の奥にはタペタム（輝板）という反射層があり、通り抜けた光を送り返してもう一度使う。夜に猫の目が光って見えるのは、この反射である。"], ["守り猫", "エジプトの穀倉でも日本の蔵でも、猫は鼠を捕る守りとして働いてきた。江戸時代の養蚕地帯では蚕や繭を食う鼠を防ぐために猫が重宝され、猫を飼えない農家は「猫絵」を蚕室に貼ったとされる。新田岩松家の当主が代々描いた新田猫絵は、その代表格。"]], "invite": "猫とすれ違ったら、瞳孔の形を見てみる。昼は縦の線、暗がりではまん丸——同じ目とは思えない変わりようが見える。", "works": [{"f": "neko01.jpg", "date": "前664〜前30年ごろ", "place": "エジプト（末期王朝〜プトレマイオス朝）", "title": "胸にバステト女神の像がある猫（Cat with image of Bastet on breast）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/570719", "note": "すっと背すじを伸ばして座る、高さ20センチほどの青銅の猫。胸に猫の女神バステトの姿が刻まれていることが名の由来で、こうした像は女神への奉納物として数多く作られたとされる。猫が神格を帯びていた時代の、澄ました横顔。"}, {"f": "neko02.jpg", "date": "1657年", "place": "オランダ", "title": "大きな猫（The Large Cat）", "artist": "コルネリス・フィッセル", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/9372", "note": "丸くなってまどろむ縞猫を、毛なみの流れまで彫り込んだ銅版画。左奥の格子のそばには、小さな鼠がしのび寄っている。当時のオランダで猫はまず鼠捕りの実務家だったが、この一枚は肖像画の風格をもつ。"}, {"f": "neko03.jpg", "date": "1662〜1735年（清・康熙〜雍正）", "place": "中国（蘇州）", "title": "海棠綬帯富貴図（Picture of a Cat, a Bird, and a Crabapple）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2025.60", "note": "海棠の枝にとまる綬帯鳥（じゅたいちょう）を、斑の猫が下から見上げる蘇州の多色摺版画。原題「海棠綬帯富貴図」のとおり、鳥と花に富貴の願いを掛けた壁掛けの縁起物とされる。狙う目つきまで含めて、めでたい。"}, {"f": "neko04.jpg", "date": "1715年ごろ（江戸）", "place": "日本", "title": "猫と遊ぶ遊女（Courtesan Playing with a Cat）", "artist": "懐月堂度繁", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/158921", "note": "菓子箱に腰かけて布をあらためる遊女の足元で、子猫が紐にじゃれて立ち上がる。墨の太い輪郭と丹の色で美人を大きく描く、懐月堂派の丹絵。猫は隅の小さな一匹なのに、画面の時間はこの子が動かしている。"}, {"f": "neko05.jpg", "date": "1770年代はじめ（江戸）", "place": "日本", "title": "金魚をねらう猫（Cat Pawing at Goldfish）", "artist": "磯田湖龍斎", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/21177", "note": "耳もとに花飾りをつけた猫が、鉢の金魚めがけて前肢を水に浸す。着飾らせてもらえるほど大事にされて、それでも狩りはやめない。江戸の飼い猫の二面性が、一枚に収まっている。"}, {"f": "neko06.jpg", "date": "1800年代前半〜なかば（江戸）", "place": "日本", "title": "眠り猫置物（Sleeping Cat）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1964.255", "note": "鈴つきの首輪と赤い布をつけ、丸まって眠る肥前磁器の置物。毛なみは細い線で彫り、橙の上絵でなぞってある。同じ型には香炉や手あぶりを兼ねたものもあったとされるが、これは眺めるための一匹。"}, {"f": "neko07.jpg", "date": "1857年（江戸）", "place": "日本", "title": "名所江戸百景 浅草田甫酉の町詣", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/13192", "note": "格子窓の桟に白い猫が座り、田んぼの向こうを行く酉の市の参詣の列と、夕空の富士を眺めている。部屋の主は画面の外で、留守番は猫だけ。人のそばから風景を見る猫を、風景の側から描いた一枚。"}, {"f": "neko08.jpg", "date": "1868年", "place": "フランス", "title": "猫の集い（Le Rendez-vous des chats）", "artist": "エドゥアール・マネ", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/68825", "note": "屋根の上で、黒猫と白猫が尾を立てて向き合う石版画。友人シャンフルーリの著書『猫』の広告ポスターとして作られたとされ、白黒二匹だけの大胆な画面は後のポスター芸術を先取りした。"}, {"f": "neko09.jpg", "date": "1909年", "place": "フランス", "title": "夏：手すりの上の猫（Summer: Cat on a Balustrade）", "artist": "テオフィル＝アレクサンドル・スタンラン", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/51724", "note": "木の手すりに長々と寝そべる縞猫を、夏の光の色で刷った多色石版画。モンマルトルのキャバレー「黒猫」のポスターで知られるスタンランは、生涯にわたって猫を描きつづけた。目を細めたこの顔は、たしかに夏の午後のもの。"}]}, {"id": "koi", "no": "第八景", "name": "鯉", "yomi": "こい", "en": "Carp", "rep": "koi08.jpg", "lead": "滝を登りきれば龍になる。ひとつの故事を背負って、中国の鏡から江戸の空の鯉幟まで泳ぎついた魚。この帖で最初の魚。", "nature": [["口ひげと、のどの歯", "コイの口の両側には大小2対のひげがあり、味を感じる器官があるとされる。口の中に歯はなく、のどの奥に並ぶ咽頭歯でかみ砕く——タニシなどの貝殻ごと食べられるのはこのため。似たフナにはひげがないので、口もとが見分けの手がかりになる。"], ["滝登りの故事", "黄河の急流・龍門を登りきった魚は龍になる——『後漢書』に由来する故事「登龍門」が、鯉の滝登りの画題のもとになったとされる。難関の入り口を登竜門と呼ぶ言い方も、端午の節句に揚げる鯉幟も、この一つの伝説から流れ出ている。"], ["泳ぐ宝石のふるさと", "錦鯉は、江戸時代後期に新潟の二十村郷（いまの長岡市山古志や小千谷市のあたり）で、食用に飼われていた鯉に現れた色変わりを選んで育てたのが始まりとされる。雪深い山あいの棚池で生まれた変わりものが、いまでは世界中の池を泳いでいる。"]], "invite": "近くの川や池で大きな魚を見つけたら、口もとを見てみる。ひげが見えたら、それがコイ。", "works": [{"f": "koi01.jpg", "date": "1200〜1225年ごろ（金）", "place": "中国（金）", "title": "双鯉文鏡（Mirror with Twin Carp）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1995.379", "note": "青銅の鏡の背に、波間をめぐる二匹の鯉が鋳出されている。中央のつまみをはさんで追いかけあう双魚の意匠は、金の時代の中国北方で好まれた型とされる。手のひらの中で、水がまわり続けている。"}, {"f": "koi02.jpg", "date": "15世紀末（室町）", "place": "日本", "title": "鯉と水草（Carp and Waterweeds）", "artist": "楊月（画僧）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/671055", "note": "上から頭を下げて一匹、水草のあいだに一匹。絹に淡い墨で、口もとのひげまで描き込まれている。鴉の景に登場した画僧・楊月の筆で、画面の上には賛が添えられている。"}, {"f": "koi03.jpg", "date": "明時代（1368〜1644）", "place": "中国（明）", "title": "跳ねる鯉（Leaping Carp）", "artist": "劉節", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1977.55", "note": "大魚が身をひるがえして浮かび、小さな魚たちが藻の下を泳ぐ。明の宮廷で魚の絵の名手とされた劉節の筆。跳ねる鯉は、龍門を登って龍になる立身出世の画題に重ねられたとされる。"}, {"f": "koi04.jpg", "date": "朝鮮王朝時代（1392〜1910）", "place": "朝鮮", "title": "双鯉図（A Pair of Carp）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/185001", "note": "くだる一匹と、のぼる一匹。長いひげの二匹が紙の上で対になる。朝鮮王朝の絵画で、鯉は登龍門の故事を介して、科挙の合格や立身出世を願うモチーフだったとされる。"}, {"f": "koi05.jpg", "date": "1760〜1829年ごろ（江戸）", "place": "日本", "title": "滝と橋に鯉の鍔（Sword Guard (Tsuba) with Carp in Waterfall and Bridge）", "artist": "赤城軒泰山元孚", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1919.349", "note": "鉄の鍔に落ちる水の束を彫り、金をきかせた一匹がその中を登ってゆく。上には橋、下には渦。腰に差す刀の金具にまで、滝登りの願いが住んでいた。"}, {"f": "koi06.jpg", "date": "1831年（江戸）", "place": "日本", "title": "藻に鯉（Carp Swimming by Water Weeds）", "artist": "葛飾北斎", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1943.3", "note": "藍の水の中、水草のあいだを二匹がすれちがう。団扇の形に切られた一枚で、うろこの網目が一枚ずつ摺り分けられている。波の上ではなく「水の中」を正面から描いている。"}, {"f": "koi07.jpg", "date": "1830年代前半〜なかば（江戸）", "place": "日本", "title": "滝を登る鯉（Carp Ascending a Waterfall）", "artist": "渓斎英泉", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1940.1049", "note": "縦長の画面いっぱい、落ちてくる水の直線を裂いて一匹が登る。二枚の紙を縦に継いだ判型が、そのまま滝の高さになっている。うろこの網目と水の線が競い合う。"}, {"f": "koi08.jpg", "date": "1857年（江戸）", "place": "日本", "title": "名所江戸百景 水道橋駿河台（Suido Bridge and Surugadai）", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/34252", "note": "画面の手前いっぱいに黒い鯉幟、遠くに富士と、武家地に立ち並ぶ端午の幟。鯉の目の高さから江戸の五月の空を見る。滝登りの故事は、男児の成長を願う風習になって空へ揚がった。"}, {"f": "koi09.jpg", "date": "1893〜1914年（明治）", "place": "日本", "title": "波に鯉の皿（Dish with Carp in Waves）", "artist": "三代 清風与平", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2022.240", "note": "白い皿の見込みに、波と鯉が線刻で沈めてある。白の中の白だから、光の加減でだけ浮かび上がる。ふちの朱色が、その静かな水面を締める明治の京焼。"}]}, {"id": "sakura", "no": "第九景", "name": "桜", "yomi": "さくら", "en": "Cherry Blossom", "rep": "sakura05.jpg", "lead": "散るのが早いからこそ、毎年見上げてきた花。平安の昔に梅から花見の主役を継ぎ、いまの並木の多くは一本の木の分身が咲かせている。", "nature": [["一本の木の分身", "街の桜並木の多くを占めるソメイヨシノは、エドヒガンとオオシマザクラの雑種に由来する一本の木から、接ぎ木などで殖やされてきたクローンとされる。みな同じ遺伝子を持つため、条件がそろえば一斉に咲き、一斉に散る。"], ["桜前線", "気象庁は1953年から、各地のソメイヨシノの標本木で開花を観測している。花芽は前の年の夏につくられ、冬の低温でいったん目を覚まし（休眠打破）、春の気温の積み上がりで開くとされる。開花日を結んだ線は、南から北へゆっくり上がってゆく。"], ["十の野生種", "日本の野生のサクラはヤマザクラやエドヒガンなど10種ほどで、2018年には約100年ぶりの新種クマノザクラが加わった。そこから生まれた栽培品種は数百あるとされる。なお食べるサクランボは食用のセイヨウミザクラなどの実で、花見の桜とは別の種。"]], "invite": "通り道の桜を一本決めて、花のない今日の姿を見ておく。幹を横に走る縞（皮目）が、桜のしるしである。", "works": [{"f": "sakura01.jpg", "date": "17世紀前半（江戸）", "place": "日本", "title": "厳島・吉野花見図屏風（Cherry Blossom Viewing at Itsukushima and Yoshino）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/53429", "note": "金雲のあいだ、山肌を白く埋めるのは満開の桜で、麓の道には幕を張って浮かれる人の列が続く。安芸の厳島と大和の吉野、桜の名所二つを収めた六曲一双の片方。花より人の多いくらいの画面に、行事としての花見の古さが写っている。"}, {"f": "sakura02.jpg", "date": "18世紀後半（江戸）", "place": "日本", "title": "桜図（Cherry Blossoms）", "artist": "松村呉春", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/49049", "note": "岩肌からしだれ落ちる枝々を、淡い墨の濃淡で描いた掛軸。四条派の祖とされる呉春は、花を色で塗り立てず、紙の白のなかに咲かせている。満開を描いて、これほど静かな桜もある。"}, {"f": "sakura03.jpg", "date": "1790年代末（江戸）", "place": "日本", "title": "風の中の桜（Cherry Blossoms in the Wind）", "artist": "歌川豊国", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1975.97", "note": "花吹雪の下、突風に着物や手紙をあおられる女たちの三枚続。散る花と風のいたずらを、ひとつの画面に重ねた。桜は満開よりも散りぎわが絵になる——浮世絵はそのことをよく知っている。"}, {"f": "sakura04.jpg", "date": "1805年（1812年出版）", "place": "イギリス", "title": "『ポモナ・ブリタニカ』第10図 サクランボ（Pomona Britannica: No. 10 - Cherries）", "artist": "ジョージ・ブルックショー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2020.168", "note": "黒と紅、色の違うサクランボの枝を並べた果樹図譜の一葉。ヨーロッパはこの木を、花ではなくまず果実で見てきた。同じサクラ属でも、食べるサクランボはセイヨウミザクラなど食用の種の実で、花見の桜とは別ものとされる。"}, {"f": "sakura05.jpg", "date": "1832〜38年ごろ（江戸）", "place": "日本", "title": "東都名所 吉原仲之町夜桜（Cherry Blossoms at Night on Nakanocho in the Yoshiwara）", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/25445", "note": "満月の下、通りの中央の桜並木が白く光る。吉原の仲之町には花の時期だけ桜を運びこんで植え、終われば片づけたと伝わる——ひと春の花のための、街ぐるみの仕掛け。夜桜という楽しみ方が、ここではもう完成している。"}, {"f": "sakura06.jpg", "date": "1862年", "place": "フランス", "title": "ブローの桜の木（Cherry Tree at Blau）", "artist": "テオドール・ルソー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1925.581", "note": "バルビゾンの画家ルソーが、岩場に立つ一本の桜を写した版画。ガラス板に描いた線を印画紙に焼き付ける、クリシェ・ヴェルという技法とされる。花は一輪もない、葉の茂った季節の姿——名所の花ではなく、一本の木として桜を見た眼である。"}, {"f": "sakura07.jpg", "date": "1800年代後半", "place": "日本", "title": "枝垂桜図皿（Dish with Weeping Cherry Tree）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1963.97", "note": "藍の枝から、糸のように花房の垂れる磁器の皿。染付の上に赤絵で花びらを縁取っている。枝垂桜はエドヒガンから出た枝の下がる性質の桜とされ、器の丸い面が、その滝のような枝ぶりをよく受け止めている。"}, {"f": "sakura08.jpg", "date": "1905年", "place": "アメリカ", "title": "桜の雨（Cherry Blossom Rain）", "artist": "ヘレン・ハイド", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/77601", "note": "花と雨がいちどに降るなか、赤い傘を寄せ合って歩く女性たち。作者ハイドはアメリカ生まれで、1899年から東京に住み、日本の彫師・摺師と組んで木版画をつくったとされる。ジャポニスムが、輸入ではなく同居になった一枚。"}, {"f": "sakura09.jpg", "date": "1935年以降（昭和）", "place": "日本", "title": "桜八題 嵐山（Eight Scenes of Cherry Blossom: Arashiyama）", "artist": "吉田博", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2016.86", "note": "山裾の川岸に舟が並び、その上へ桜が枝を差しかける嵐山の春。連作「桜八題」の一枚で、吉田博は油彩から木版に転じた画家である。山の緑に淡い紅がにじむ色は、版木を何度も摺り重ねる仕事から生まれる。"}]}, {"id": "ine", "no": "第十景", "name": "稲", "yomi": "いね", "en": "Rice plant", "rep": "ine06.jpg", "lead": "水を張った土に、一年で枯れる草を植える。それだけのことを三千年ほど繰り返して、この国の風景の骨格ができた。", "nature": [["一年で終わる草", "イネ（Oryza sativa）はイネ科の一年草で、もとは暖かい地方の草とされる。夏に出る花は花びらを持たない小さな頴花（えいか）で、風で花粉が運ばれる仲間でありながら、実際には開いたその場で自分の花粉がつく自家受粉がふつうとされる。だから隣とすぐには混ざらず、うるちともちを並べて作ることができる。"], ["水を張るということ", "田に水を張るのは、稲が水を好むからだけではないとされる。水の下では土が酸素の乏しい状態になり、畑の作物を傷める糸状菌（カビの仲間）の多くが生きにくくなる。深めの水は雑草の芽生えも抑える。同じ土地で毎年同じ作物を作りつづけられる田の力は、この一手にかなりを負っているとされる。"], ["三千年の付き合い", "日本に水田の稲作が伝わったのは縄文時代の終わりごろとされ、佐賀の菜畑遺跡や福岡の板付遺跡に、その時期の水田の跡が見つかっている。北九州から広がり、弥生時代には北海道と沖縄を除くほぼ全域へ届いたとされる。品種は今も増えつづけていて、農林水産省によれば、2025年産の農産物検査で産地品種銘柄とされたものだけで、水稲うるち玄米940、もち玄米137、醸造用玄米236にのぼる。"]], "invite": "田のわきを通ったら、株もとを一度のぞいてみる。水があるか、土が干してひび割れているか。稲の一年は、そこの水加減で進んでいる。", "works": [{"f": "ine01.jpg", "date": "1600年代はじめ（明）", "place": "中国", "title": "春の夕、田から帰る人びと（Returning Peasants in a Spring Evening）", "artist": "陶泓", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1999.223", "note": "稲のいない田から、この景は始まる。葉を落とした木立のあいだを、道具を肩にした人が家畜にまたがって帰り、空の高みには帰る鳥の列。画面の左の、まだ水を張らない平らな地を、美術館は眠っている田と読んでいる——農の季節がこれから始まるしるしとして。"}, {"f": "ine02.jpg", "date": "1700年代（江戸）", "place": "日本", "title": "春秋の耕作図（秋）（Spring and Autumn Farming: Autumn）", "artist": "高嵩谷", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2012.72.2", "note": "六曲の屏風いっぱいに、秋の村の一日が広がる。萱葺きの小屋のまわりで作業し、荷をかついで橋を渡り、右手では川舟に積んで運び出す。人はみな小さく描かれ、代わりに田と家と川の関係のほうが主役になっている。"}, {"f": "ine03.jpg", "date": "1730年代ごろ（江戸）", "place": "日本", "title": "四季の百姓 三 秋・稲苅之図（Autumn: Harvesting Rice）", "artist": "鳥居清倍（二代）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/31635", "note": "刈り取りにかがむ人、束にして担ぐ人、下では地面に広げた稲をあつかう人。牛が一頭、刈り跡のわきに立っている。紅葉の雲を添えて一枚に収めてあるが、描かれているのは秋のいちばん忙しい数日である。"}, {"f": "ine04.jpg", "date": "18世紀末〜19世紀はじめ（江戸）", "place": "日本", "title": "田植えに食事を運ぶ（Taking Food to Rice Planters）", "artist": "窪俊満", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/22476", "note": "奥のあぜに、笠を並べた早乙女の列。手前を歩く女は重ねの器を頭にのせ、片手にやかんを提げ、先を行く子があぜの細い道を選んでいる。田植えは一日仕事で、食べさせることも仕事のうちだった——絵の主役はそちらにある。"}, {"f": "ine05.jpg", "date": "江戸時代（1615〜1868年）", "place": "日本", "title": "鍔 稲に鼠（Sword Guard (Tsuba) with Mice and Rice）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1919.411", "note": "垂れた稲穂に、大小二匹の鼠が取りついている。粒の一つひとつが彫り分けられ、稲の葉は鍔の縁をなぞって弧を描く。実った田は昔から人以外のものにも狙われていた——それを刀の護りに彫ったところがおかしい。"}, {"f": "ine06.jpg", "date": "1835〜36年（江戸）", "place": "日本", "title": "百人一首うばがゑとき 天智天皇（Poem by Emperor Tenchi）", "artist": "葛飾北斎", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1916.1164", "note": "刈った稲を小さな山に積み、束にして担ぎ、板橋を渡って運んでゆく。左には稲を掛ける木組み、遠くには夕焼けの空。天智天皇の作とされる「秋の田のかりほの庵」の歌に、北斎は番小屋ではなく、働く人の背中でいっぱいの秋の田を当てた。"}, {"f": "ine07.jpg", "date": "制作年不詳（19世紀後半）", "place": "アメリカ", "title": "籾を搗く（Pestling the Paddy）", "artist": "ロバート・フレデリック・ブラム", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/42737", "note": "長い梃子の先の杵を上下させ、据えた臼の籾を搗いている。手前では、こぼれた籾を箒で掃き寄せる人がしゃがむ。ブラムは1890年に雑誌の挿絵の仕事でアメリカから日本へ渡り、数年を過ごしたとされる。稲が米になるまでの最後の手間に、外から来た目が留まっている。"}, {"f": "ine08.jpg", "date": "1909〜10年（明治）", "place": "日本", "title": "あぜ道を歩く ── 図案集『百々世草』より（A Walk Around the Paddy Fields）", "artist": "神坂雪佳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/127743", "note": "区切られた田が、緑と桃色と黄の面になって画面を占める。あぜは銀の線一本で引かれ、そこを小さな包みを提げた女がひとり歩いてゆく。田とは人が土に引いた線の集まりである、ということを、これほど短く言った絵はない。"}, {"f": "ine09.jpg", "date": "いま", "place": "青森県青森市入内", "title": "刈り取り前の稲穂（品種：つがるロマン）", "artist": "あおもりくま（写真）", "museum": "Wikimedia Commons", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Oryza_sativa_Ear_rice_Stugaru_roman_rice_IMG_3946_01.jpg", "note": "刈り取りを待つ穂を間近から見る。粒が重くなるほど穂は弓なりに垂れ、葉のあいだへ沈んでゆく。ここまでが稲の仕事で、ここから先が人の仕事になる。"}]}, {"id": "usagi", "no": "第十一景", "name": "兎", "yomi": "うさぎ", "en": "Hare / Rabbit", "rep": "usagi06.jpg", "lead": "月では臼に杵を下ろし、地上では巣穴も掘らず、草のくぼみで子を育てる。日本ではこの獣を、なぜか鳥と同じ「一羽、二羽」で数えてきた。", "nature": [["巣を掘らない", "飼いウサギのもとになったアナウサギは地中に穴を掘って群れで暮らすが、日本の野山にいるニホンノウサギは巣穴を作らないとされる。地面のくぼみで産み、生まれた子は毛が生えそろって目も開いており、一週間ほどで草を食べはじめる。母親はふだん離れて過ごし、授乳のときだけ短く戻る——隠れ場所を持たない獣の、これが子育ての形。"], ["背中のうしろまで見えている", "目が顔の真横についているため、片目でおよそ190度、両目を合わせると360度近くを見わたせるとされる。そのかわり左右の視野が重なる範囲——立体に見える帯——は前方のごく狭い角度だけで、口先は死角になる。追う側ではなく、追われる側の目の置き方である。"], ["糞をもう一度食べる", "ウサギは二種類の糞をする。ころころした硬い糞のほかに、盲腸でつくられる軟らかい糞（盲腸糞）があり、そこには腸内細菌が作ったタンパク質やビタミンが多く含まれるとされる。これを出たそばから食べ、栄養をもう一度体に入れる。草だけで生きるための、二度がけの消化。"]], "invite": "今夜の月を見上げて、暗い模様のどこが兎に見えるか探してみる。同じ影を、餅をつく兎と読む土地も、薬を搗く兎と読む土地もある。", "works": [{"f": "usagi01.jpg", "date": "8世紀（唐）", "place": "中国", "title": "「月宮」図の八稜鏡 ── 薬を搗く兎、蟾蜍、仙桃を持つ嫦娥（Lobed Mirror with Images of the “Moon Palace”: Hare Pounding Elixir, Toad, and Chang E Holding Peaches of Immortality）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/52949", "note": "花びらの形に縁どられた青銅の鏡。中央に桂の大木が立ち、その左で兎が後ろ足で立ち上がり、脚つきの臼に杵を下ろしている。足もとには蟾蜍（ひきがえる）、木の右には仙桃を掲げた嫦娥。搗いているのは餅ではなく不死の薬とされ、東アジアの月の兎はまずこの姿で現れる。"}, {"f": "usagi02.jpg", "date": "11世紀前半", "place": "エジプト（ファーティマ朝）", "title": "走る兎の鉢（Bowl Depicting a Running Hare）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/451769", "note": "白い釉薬の上に金色の顔料を焼きつける、ラスター彩の鉢。見込みの円のなかを、耳を長く伸ばした兎が一頭だけ走り、まわりを唐草の渦が囲む。器の底という狭い舞台に、跳ねる速さだけを収めている。"}, {"f": "usagi03.jpg", "date": "1496年ごろ", "place": "ドイツ", "title": "三羽の兎のいる聖家族（The Holy Family with Three Hares）", "artist": "アルブレヒト・デューラー", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/20447", "note": "聖母と幼子、傍らにヨセフ、上空では二人の天使が冠を運ぶ木版画。目が行くのは画面の下辺で、跳ねる一羽と、耳を立てて並ぶ二羽がいる。美術館の解説では、この三羽は聖母の奇跡的な多産を暗示するという。ヨーロッパで兎は、まず殖える獣だった。"}, {"f": "usagi04.jpg", "date": "江戸時代（1615〜1868年）", "place": "日本", "title": "波に兎の鍔（Sword Guard (Tsuba) with Rabbit and Waves）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1919.288", "note": "刀の鍔。ざらついた鉄地の右上に、耳を背へ倒して身を伏せた兎が高く彫り出され、両目に金が象嵌されている。右下は巻き上がる波としぶきの粒。波と兎を組み合わせる「波兎」は工芸で繰り返された吉祥の意匠で、謡曲『竹生島』の一節に由来するといわれる。"}, {"f": "usagi05.jpg", "date": "1830年代ごろ（江戸）", "place": "日本", "title": "満月の下の兎（Rabbits under full moon）", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/24415", "note": "細長い短冊判。青くぼかした空に輪郭を持たない大きな月が浮かび、細い草の生える土手に白い兎が二羽いる。手前の一羽は背を見せ、奥の一羽は身を起こして空を仰ぐ。右上には狂歌が添う。月にいる兎ではなく、月を見上げる兎——日本ではこの向きの絵が数多く摺られた。"}, {"f": "usagi06.jpg", "date": "1855年（江戸）", "place": "日本", "title": "餅をつく兎（Rice-Pounding Rabbit）", "artist": "Tanaka Shutei（1810〜1858・大坂／漢字表記は所蔵館も未記載）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/43384", "note": "屏風のかげから女がのぞく先で、白い兎が後ろ足で立ち、染付の臼に杵を下ろしている。美術館の解説では、のぞいているのは月の宮のかぐや姫で、作者は大坂で活動した絵師、卯年と新年の到来を告げる私家版の摺物（摺物＝非売の配りもの）だという。左半分は狂歌で埋まる。唐の鏡では薬だったものが、ここでは餅になっている——手つきはそのままに、搗くものだけが入れ替わった。"}, {"f": "usagi07.jpg", "date": "1858年", "place": "スイス／フランス", "title": "鷹に追われる野兎（Hare Pursued by a Goshawk）", "artist": "カール・ボードマー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2014.364", "note": "下生えの深い林のなかを野兎が耳を伏せて走り、右上からオオタカが翼をひろげて降りてくる。画面の下には「LIÈVRE POURSUIVI PAR UN AUTOUR」と刷り込まれている。ボードマーは北米ミズーリ川流域の探検に随行した記録画家で、のちフランスのバルビゾンに移り、森と獣を描き続けたとされる。狩る側と狩られる側を、一枚のなかに置いた石版画。"}, {"f": "usagi08.jpg", "date": "1893年", "place": "フランス", "title": "兎たち（The Rabbits）", "artist": "アンリ＝シャルル・ゲラール", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1992.243", "note": "黒い兎と白い兎が顔を寄せ、画面いっぱいに刷られた木版。耳の内側も頬の毛も、彫り残した細い線の束でできている。美術館の解説によれば、ゲラールは「パリの日本人」と呼ばれた版画家で、この一枚も北斎の動物木版を手本にしたとされる。神話でも狩りの獲物でもなく、飼われている兎の顔が、ここまで大きく前に出てくる。"}, {"f": "usagi09.jpg", "date": "いま", "place": "滋賀県・岐阜県 伊吹山", "title": "ニホンノウサギ（Lepus brachyurus）", "artist": "Alpsdake（写真）", "museum": "Wikimedia Commons", "lic": "CC BY-SA 3.0", "url": "https://commons.wikimedia.org/wiki/File:Lepus_brachyurus_in_Mount_Ibuki_2011-06-26.jpg", "note": "伊吹山の道の縁、草むらから出てきた一頭。長い耳の内側が陽に透けて赤い。目は顔の真横についていて、こちらに顔を向けていないのに、こちらが見えている。絵のなかの兎がいつも横顔で描かれてきた理由は、この頭の作りにある。"}]}, {"id": "hotaru", "no": "第十二景", "name": "蛍", "yomi": "ほたる", "en": "Firefly", "rep": "hotaru04.jpg", "lead": "夜にだけ現れて、手のひらの上で冷たく光る虫。日本では籠に入れて持ち歩き、マヤでは、星と同じく暗がりで瞬くものとして鉢に彫られた。", "nature": [["水の中で育つ", "ゲンジボタルは一生の大半を水中で過ごす。孵化した幼虫はすぐ川に入り、翌春に上陸するまで、おもにカワニナという巻貝を食べて育つとされる。水がきれいで、餌になる貝がいる川。その二つが欠ければ、夏の光もない。"], ["冷たい光", "光るのは腹の先の発光器で、ルシフェリンという物質が、ルシフェラーゼという酵素のはたらきで酸素と反応して起こるとされる。出てくるのはほとんどが可視光で、熱線（赤外線）をほとんど含まないことから「冷光」と呼ばれる。触れても熱くない光である。"], ["東と西で、拍が違う", "ゲンジボタルの明滅の間隔には地域差があり、東日本ではおよそ4秒、西日本ではおよそ2秒と言われる。境目はフォッサマグナの西縁あたりとされ、近年の調査では両者が混ざる場所も報告されている。同じ虫が、土地ごとに違う拍で光っている。"]], "invite": "日が暮れてから、近所の川か用水のそばに五分だけ立ってみる。蛍がいなくてもいい——その水辺に、まだどれくらい暗さが残っているかが分かる。", "works": [{"f": "hotaru01.jpg", "date": "600〜1000年ごろ", "place": "メキシコ（マヤ・カンペチェ州）", "title": "彫文の鉢（Carved Vessel）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1990.173", "note": "口縁の下にマヤ文字の帯がめぐり、胴には渦を巻く輪郭に囲まれて一匹の虫が彫り出されている。美術館はこれを蛍とし、マヤの美術にもっともよく現れる昆虫のひとつだと説明する。暗がりで瞬くもの——星や、夜の生きもののしるしである葉巻——と結びつけられていたとされる。"}, {"f": "hotaru02.jpg", "date": "1600年代（江戸）", "place": "日本", "title": "源氏絵画帖より「螢」（Fireflies from Album of Illustrations for the Tale of Genji）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1961.202.l", "note": "細い墨線だけで人と建物を描く白描（はくびょう）の画帖の一葉で、右上の題簽に「螢」とある。『源氏物語』第二十五帖の「螢」は、光源氏が几帳のなかに蛍を放ち、その光で玉鬘の姿を兵部卿宮に見せる場面で知られる。以後この宮は蛍宮と呼ばれた——虫の光が、人の名前になっている。"}, {"f": "hotaru03.jpg", "date": "1767年ごろ（江戸）", "place": "日本", "title": "蛍狩り（Catching Fireflies）", "artist": "鈴木春信", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/20977", "note": "川べりの草むらに二人。ひとりは細長い柄の網を差し出し、もうひとりは蛍を入れる小さな籠を提げている。空は一色の黒に塗られ、蛍は光っていない——多色摺りが始まって間もないころで、光そのものを刷る手はまだない。"}, {"f": "hotaru04.jpg", "date": "1790年代（江戸）", "place": "日本", "title": "蛍狩り（Catching Fireflies）", "artist": "栄松斎長喜", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/90193", "note": "アヤメの類が茂る水辺の夜。女と子どもが団扇を振り上げ、その頭上で蛍がにじんだ丸い光になっている。地の黒には雲母（きら）が摺り込まれており、もとは画面全体が鈍く輝いていたとされる。三十年ほど前の春信の黒地とくらべると、この間に浮世絵は「光を刷る」ことを覚えている。"}, {"f": "hotaru05.jpg", "date": "1796〜97年ごろ（江戸）", "place": "日本", "title": "蛍狩り（Catching Fireflies）", "artist": "喜多川歌麿", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1975.98", "note": "柳の下の川べりを三枚続の横長に描く。女たちは団扇を振り上げ、子どもは裾をからげて流れに入り、中央の娘は籠に入った蛍を覗きこんでいる。蛍狩りが、道具も人数もそろった夏の行事だったことが、この一枚でわかる。"}, {"f": "hotaru06.jpg", "date": "1800年代初め（江戸）", "place": "日本", "title": "蛍と美人（Beauty with Fireflies）", "artist": "窪俊満に倣う", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2015.85", "note": "老いた柳の下、石積みの護岸に沿って歩く女が、蛍の入った小さな籠を手にさげている。絹に描かれた掛軸で、美術館は窪俊満の作に倣った一幅とする。捕るところではなく、籠に移して持ち帰るところ——夏の夜の楽しみは、そこまでを含んでいた。"}, {"f": "hotaru07.jpg", "date": "江戸時代後期（制作年不詳）", "place": "日本", "title": "蛍狩り（Catching fireflies）", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/47700", "note": "団扇に貼るために刷られた団扇絵で、紙そのものが扇のかたちに裁たれている。水辺の草のあいだで女が団扇を振り上げ、足元には黒い籠が置かれ、薄明かりの空に蛍が点々と散る。捕る道具と、その絵を刷った紙が、どちらも同じ団扇である。"}, {"f": "hotaru08.jpg", "date": "1894年（明治）", "place": "日本", "title": "三十六佳撰 螢狩・天明頃婦人（Chasing Fireflies, A Lady of the Tenmei Era, from the series Thirty-six Elegant Selections）", "artist": "水野年方", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2017.73", "note": "明治の絵師が、百年ほど前の天明のころ（1781〜89年）の蛍狩りとして描いた一枚。奥の木立では影になった人が網と団扇を振り、手前では供の者が黒い漆の籠の蓋を開けて待っている。空に散る淡い黄の点はすべて蛍で、絵のなかの光はとうとう粒として摺られている。"}, {"f": "hotaru09.jpg", "date": "いま", "place": "高知県四万十市・金比羅川", "title": "金比羅川のホタル", "artist": "r18 INO (PACHIMO)（写真）", "museum": "Wikimedia Commons", "lic": "CC BY 3.0", "url": "https://commons.wikimedia.org/wiki/File:%E9%87%91%E6%AF%94%E7%BE%85%E5%B7%9D%E3%81%AE%E3%83%9B%E3%82%BF%E3%83%AB_-_panoramio.jpg", "note": "2016年5月、四万十市を流れる金比羅川の岸辺。長く露光すると、飛びながら明滅する蛍の光は一本の緑の線になる。写っているのは光の軌跡だけではない——草の茂る岸と、その足元の細い流れも、いっしょに写っている。"}]}, {"id": "shika", "no": "第十三景", "name": "鹿", "yomi": "しか", "en": "Deer", "rep": "shika03.jpg", "lead": "角は毎年落ちて生えかわり、秋の夜には雄が高い声で鳴く。神の使いとされ、和歌に詠まれ、いまは数が増えて森の下草が失われる地域も報告されている——どれも同じ一頭の獣の話である。", "nature": [["毎年、落として生やしなおす", "ニホンジカの角は雄だけに生えるとされ、毎年春に根元から落ちて、すぐ新しい角が伸びはじめる。伸びているあいだは表面がやわらかな皮膚に包まれ、短い毛が生えている状態で、袋角（ふくろづの）と呼ばれる。夏の終わりごろに皮がこすり落とされて硬い枝角になり、枝分かれの数は齢を重ねるほど増えていくとされる。骨に近い組織を、一年でまるごとつくり直している獣。"], ["秋、声で自分の場所を告げる", "秋の繁殖期になると、雄が高く長い声で鳴く。奈良では「フィーョー」と書き表され、遠くで鳴けば秋の深さのように、近くで鳴けばかなり大きな音として届く。古今和歌集の秋の巻には、山で紅葉を踏み分けて鳴く鹿の声を聞くときこそ秋は悲しい、とうたう一首があり（のちに百人一首へ猿丸大夫の作として採られた）、この声は千年以上、秋の合図として聞かれてきた。"], ["食べる口が、森のかたちを決める", "シカは草や木の葉、冬には樹皮まで食べる草食獣で、数が増えた森では、口の届く高さの葉が消え、林床の草やササが失われることが各地で報告されている。研究機関では「下層植生衰退度」という指標でその度合いを地図にする試みがあり、三重県の調査では、傾斜の急な林ほど衰退が進むと表土の侵食が増える傾向が示されたという。下草の量の変化は、鳥や土の中の節足動物にまで及ぶことも報告されている。"]], "invite": "秋の夕方、鹿の声が聞こえたらどこから来た声かを耳で追ってみて、角のある一頭に会えたら枝分かれの数を数えてみる。", "works": [{"f": "shika01.jpg", "date": "前400〜前300年ごろ", "place": "西アジア（スキタイ）", "title": "牡鹿の飾り板（Stag Plaque）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1985.77", "note": "手のひらに収まる、高さ四センチほどの金の小さな板。脚を体の下へ折りたたんだ牡鹿が首をまっすぐ前へ伸ばし、角は枝ではなく渦の連なりになって、背の上を後ろへ流れていく。速さも角の重さも、丸まった線のくり返しひとつに置きかえられている。"}, {"f": "shika02.jpg", "date": "13世紀後半（元）", "place": "中国", "title": "雲間の鶴と鹿の輪花皿（Foliate Dish with Crane and Deer Amid Clouds）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/12476", "note": "縁を花びらの形に切った青磁の皿（龍泉窯）。見込みの中央に、型で押し出された角のある鹿が一頭、雲のあいだを歩く。その上には首を長く伸ばした鶴、鹿の背のあたりには脚の高い器のようなかたちが重なる。鶴と鹿は東アジアで長寿を表す取り合わせで、食器の底が仙境になっている。"}, {"f": "shika03.jpg", "date": "14世紀後半〜15世紀（南北朝〜室町）", "place": "日本", "title": "春日鹿曼荼羅図（Kasuga Deer Mandala）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1988.19", "note": "金の雲に乗った白い鹿が、色鮮やかな鞍を背負って歩く。鞍から立つ榊の枝に藤がからみ、その上に大きな金の円——中に五体の仏が座っている。美術館の解説では、この五体は奈良・春日大社の五つの社の神々の仏としての姿で、鹿は第一殿の神・武甕槌命の乗りものだという。上には御蓋山とされる山なみと月。個人が拝むために描かれたと考えられている。"}, {"f": "shika04.jpg", "date": "1501年ごろ", "place": "ドイツ", "title": "聖エウスタキウス（Saint Eustace）", "artist": "アルブレヒト・デューラー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1958.109", "note": "森で鹿を追っていたローマの将軍が、角のあいだに十字架を見て馬を降り、ひざまずいている。手前には猟犬が五つの姿勢で寝そべり、美術館の解説によれば、これは一頭の犬を五つの角度から描き分けたものだという。デューラー最大の銅版画。肝心の鹿は右上の木立にひっそりと立ち、探さないと見つからない大きさで置かれている。"}, {"f": "shika05.jpg", "date": "18世紀〜19世紀なかば（江戸）", "place": "日本", "title": "秋草に鹿文蒔絵十種香箱（Ten-Round Incense Game）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1921.405", "note": "香を聞き分けて当てる遊びの道具一式を納める箱。黒い漆地に金粉で薄・菊・桔梗の秋草が蒔かれ、観音開きの扉の裾に、角を持つ鹿が一頭、草に体を伏せている。花に光る青緑は螺鈿。秋草に鹿という和歌の型が、手に取って遊ぶ道具の表面へそのまま移されている。"}, {"f": "shika06.jpg", "date": "1848年", "place": "アメリカ", "title": "オジロジカ（Cervus Virginianus）", "artist": "ジョン・ウッドハウス・オーデュボン", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/104328", "note": "手彩色の石版画。小川のふちで枝角を張った雄が立ち、角のない一頭が水面に口をつけている。下辺には「CERVUS VIRGINIANUS, PENNANT.／COMMON OR VIRGINIAN DEER.」、左端に写生者の名、右端に一八四八年フィラデルフィアで刷られたことが小さく入る。図鑑の一枚として、真横からの立ち姿と、水を飲む姿勢の二つが選ばれている。"}, {"f": "shika07.jpg", "date": "1890年代", "place": "フランス", "title": "牡鹿の声（The Call of the Stag）", "artist": "ローザ・ボヌール", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/257852", "note": "焼けた空の下、湿った草地に牡鹿が一頭。角を背へ倒して首を伸ばし、開いた口から白い息のようなものが横へ流れている。左上には細い月らしいかたちが薄く残る。動物を描きつづけた画家が、秋に雄が鳴くその一瞬を、パステルの粉で止めた。"}, {"f": "shika08.jpg", "date": "1892年（明治）", "place": "日本", "title": "満月の下、秋草の鹿（Deer in Autumn Grasses under the Full Moon）", "artist": "Baien（19世紀に活動した絵師・漢字表記は所蔵館も未記載）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/103330", "note": "横に長い摺物。右端に、斑のある鹿が細い草の中に立ち、首を伸ばして左上の白い月を仰ぐ。残りの面はほとんど文字で、細かな仮名の歌が何十行も並んでいる。絵より歌のほうがずっと広い——この配分に、鹿がまず「声」と「秋」の記号だったことがよく出ている。"}, {"f": "shika09.jpg", "date": "いま", "place": "滋賀県米原市・伊吹山", "title": "袋角のニホンジカ", "artist": "Alpsdake（写真）", "museum": "Wikimedia Commons", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Cervus_nippon_(antlers_in_velvet).jpg", "note": "伊吹山で七月の朝に撮られた雄。撮影者の説明では、角はまだ皮膚に包まれた袋角で、口には食べかけの草がある。金の飾り板の鹿も、曼荼羅の白い鹿も、もとはこの顔をしている。"}]}, {"id": "suzume", "no": "第十四景", "name": "雀", "yomi": "すずめ", "en": "Sparrow", "rep": "suzume04.jpg", "lead": "屋根の隙間に巣をつくり、こぼれた穀物をついばむ。人が住みつけば現れ、人が去れば消えていく——森ではなく、人のそばを選んだ小鳥。", "nature": [["人のいるところにだけいる", "スズメは都市・農村・集落など、人が住むところの近くで一年中見られる鳥とされる。巣は瓦の下、雨樋と屋根の隙間、換気口の中など、人がつくった建物のすきまに多い。人が離れて集落が無人になると、スズメも見られなくなる傾向があるという——人里から遠く離れた森は、この鳥の場所ではない。"], ["雛のあいだは、虫を食べる", "成鳥はイネ科を中心とした植物の種子をよく食べるが、繁殖期の雛には昆虫やクモなどの動物質が多く運ばれるとされる。英国で雛の糞を調べた研究では、すべての試料から無脊椎動物のかけらが見つかり、種子が含まれていたのは半数ほどだったという報告がある。穀物をついばむ鳥が、育つあいだだけは虫で生きている。"], ["減っている、らしい", "昭和の終わりごろから、日本のスズメは減少傾向にあるといわれる。全国鳥類繁殖分布調査の第2回（1997〜2002年）と第3回（2016〜2020年）を比べた研究では、この18年で個体数が6割ほどになったと推定されている。ただし推定には幅があり、調査地の偏りや地域差もあるため、どれだけ減ったかが確定しているわけではない。"]], "invite": "電線か屋根のふちを見上げて、雀が何羽いるか数えてみる。数えられたら、その数と日付と場所を書きとめておく。来年の同じ日に、もう一度数えるために。", "works": [{"f": "suzume01.jpg", "date": "7世紀後半〜8世紀はじめ（唐）", "place": "中国", "title": "花枝をめぐる雀の鏡（Mirror with Sparrows and Floral Sprays／雀繞花枝鏡）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1995.358", "note": "直径九センチほどの青銅鏡の、裏側。中央のつまみを花の枝がぐるりと取り巻き、その間を小さな鳥が飛び、枝先にとまっている。同じ組み合わせが外側の帯にもう一周続いていて、顔を映すための道具の裏に、庭先の景色がまるごと彫り込まれている。"}, {"f": "suzume02.jpg", "date": "1347年（元）", "place": "中国", "title": "秋景鶉雀図（Quails and Sparrows in an Autumn Scene）", "artist": "王淵", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1997.91", "note": "色をいっさい使わず、墨の線と淡い暈しだけで仕上げた掛軸。岩と竹と菊のまわりで、地面には鶉が二羽うずくまり、細い枝には雀がとまって、一羽が左上へ飛び立つ。美術館の解説では、宮廷風の精密な花鳥画を、あえて色を抜いた水墨へ置きかえた作だという。"}, {"f": "suzume03.jpg", "date": "16世紀なかば〜後半（室町）", "place": "日本", "title": "竹に雀（Sparrows and Bamboo）", "artist": "Shiken Saidō（1486〜1581・禅僧／漢字表記は所蔵館も未記載）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2015.457", "note": "しなった竹の細い枝に、雀が二羽。上の一羽は背を向けて首をすくめ、下の一羽は正面を向いて胸をふくらませ、右半分は僧・Ekkei Reikaku の賛で埋まっている。竹に雀という取り合わせは東アジアで繰り返し描かれ、日本では家紋の意匠にもなった。"}, {"f": "suzume04.jpg", "date": "1720〜25年ごろ（江戸）", "place": "日本", "title": "藁屋根に竹と雀（Sparrows, Thatched Roof, and Bamboo）", "artist": "奥村政信", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/88877", "note": "厚く葺いた藁屋根の棟に雀が二羽、羽をふくらませて並ぶ。上には竹が張り出し、そこにも二羽——一羽は逆さまに近い姿勢で枝から下をのぞいている。墨で摺ったあと筆で黄と紅を差した初期の版画で、下辺の枠に版元と絵師の名が入る。"}, {"f": "suzume05.jpg", "date": "1797年（江戸）", "place": "日本", "title": "萩に石臼と雀（Sparrows on Millstones with Hagi Bushes）", "artist": "葛飾北斎（北斎宗理）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/24503", "note": "石臼が二つ、ひとつは立てかけられ、ひとつは横に伏せて置かれている。萩の枝が上から垂れ、立てた臼の縁に一羽、伏せた臼の上に二羽の雀がいて、頬の黒い斑までていねいに描き分けられている。下半分は狂歌でびっしり埋まる摺物（非売の配りもの）で、穀物を挽く道具のまわりに鳥が来る、というだけの風景が画題になっている。"}, {"f": "suzume06.jpg", "date": "1797年ごろ", "place": "イギリス", "title": "『英国鳥類史』の「雀」のための版木（Woodblock for The Sparrow, from A History of British Birds）", "artist": "トマス・ビュイック", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/78567", "note": "刷り上がった絵ではなく、刷るための版木そのもの。硬いツゲの木口を彫って、一羽の雀と、その後ろに並ぶ民家の屋根・煙突・石塀が浮き上がり、右上には Tynmouth Oct.r 1794 と刻まれている（凸版の版木は、刷ると左右が反転する）。英語で sparrow といえば日本のスズメとは別種のイエスズメを指すことが多いが、人家の屋根と一緒に彫られているところは変わらない。"}, {"f": "suzume07.jpg", "date": "1830年代なかば（江戸）", "place": "日本", "title": "竹に雀（Sparrow and bamboo）", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/88798", "note": "細長い中短冊判。上端を藍でぼかした空に狂歌が流れ、黒と紅の竹が縦に走り、その間を雀が翼をいっぱいに広げて舞い降りてくる。風切羽の一枚一枚まで彫り分けられていて、とまった姿ではなく、降りる途中の一瞬だけが取り出されている。"}, {"f": "suzume08.jpg", "date": "1843年", "place": "フランス", "title": "雀の鳥小屋（The Sparrow Aviary／Volière des Passereaux）", "artist": "シャルル＝フランソワ・ドービニー", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/24354", "note": "蔦の茂る枠の内側に、網を張った大きな鳥小屋がひらける銅版画。細い枝と網に無数の小鳥がとまり、下では噴水のある水盤のまわりに数羽が降りている。人の庭のなかに、小鳥を囲って眺めるための場所がわざわざつくられていた、その光景。"}, {"f": "suzume09.jpg", "date": "いま", "place": "日本（愛知県春日井市）", "title": "電線に並ぶスズメの群れ", "artist": "KKPCW（写真）", "museum": "Wikimedia Commons", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Many_sparrows_on_electric_wire_-_1.jpg", "note": "冬の白い空に、電線が何本も斜めに走る。その一本一本に雀がびっしり並び、電柱の腕金にも群がっている。とまっている線も、巣をかける隙間も、この鳥が自分で用意したものではない。"}]}, {"id": "kame", "no": "第十五景", "name": "亀", "yomi": "かめ", "en": "Turtle / tortoise", "rep": "kame06.jpg", "lead": "甲羅は、着せられた殻ではない。肋骨と背骨が横へ広がって板になったもので、脱ぐことができない。その脱げない家を背負ったまま、この生きものは五千年ぶん、人の絵の中を歩いてきた。", "nature": [["甲羅は、肋骨だった", "カメの背中の甲羅（背甲）は、肋骨と椎骨が扇のように横へ広がり、板状に融合してできたものとされる。理化学研究所は2009年、カメの胚では、ふつうの脊椎動物なら肋骨の外側にあるはずの肩甲骨が、発生の後期に体壁が内側へ折れ込むことで肋骨の内側に入る、と報告した。だから甲羅は着脱できる殻ではなく、骨格そのもの——そこから抜け出すことはできない。表面をおおう六角の板は、その骨の上に重なったケラチンの角質層とされる。"], ["在来のイシガメと、外から来たカメ", "ニホンイシガメは日本の固有種とされ、2026年3月に公表された環境省の第5次レッドリストで、準絶滅危惧（NT）から絶滅危惧II類（VU）へ一段階引き上げられ、初めて絶滅危惧種と評価された。一方、北米原産のミシシッピアカミミガメ（アカミミガメ）は1950年代後半からペットとして輸入され、環境省は全国の野外の生息数を中央値790.9万匹（2015年時点の推定）としている。環境省は、アカミミガメが在来のカメ類と餌や日光浴の場所をめぐって競合しているとする。2023年6月から条件付特定外来生物に指定され、野外に放すことは法律で禁じられている。"], ["日なたに上がる", "カメは変温動物で、自分の熱で体温を保てない。水から上がって日を浴びる甲羅干しは、体を温めて消化や代謝を進めるためと説明される。あわせて、紫外線が体内でのビタミンDの生成を助け、甲羅や皮膚を乾かして藻や菌が付くのを抑えるはたらきもあるとされる。晴れた日の池で、石や流木の上に甲羅が並ぶのは、そのためである。"]], "invite": "晴れた日に池や川のふちを歩いて、日なたに上がっている亀を探してみる。甲羅の六角形をいくつか数えて、それが元は骨だったことを思い出す。", "works": [{"f": "kame01.jpg", "date": "前3500〜前3050年ごろ", "place": "エジプト（先王朝時代）", "title": "亀の形の化粧板（Palette in the Form of a Turtle）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1989.47", "note": "灰緑の石を、上から見た亀の形に削り出してある。丸い甲から短い脚が四本、左右にも張り出しがひとつずつ出て、右の張り出しに小さな穴がふたつ、左にひとつ、あけてある。全体で八センチに満たない。美術館の説明では、こうした石の板は目のまわりに塗る顔料を磨りつぶす道具で、その顔料は化粧のためだけでなく、日ざしのまぶしさや目の病を防ぐためにも使われたという。"}, {"f": "kame02.jpg", "date": "前1600〜前1046年ごろ（殷）", "place": "中国", "title": "甲骨（Oracle Bones・76点のうち）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/192727", "note": "暗い台の上に、骨のかけらが七点。細長いものには文字が縦に刻まれ、中央の平たい四角い一片には丸いくぼみがいくつも掘られている。所蔵館の記載では、これらは牛の骨と亀の腹甲（腹側の甲羅）の断片で、磨いて焼き、文字を刻んだもの——くぼみに火を当ててできたひび割れで占い、その結果を書きつけた。漢字のいちばん古い姿は、牛の骨と、この亀の甲の上に残っている。"}, {"f": "kame03.jpg", "date": "前404〜前350年", "place": "ギリシャ（アイギナ島）", "title": "リクガメのスタテル銀貨（Stater Depicting a Land Tortoise）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/9648", "note": "直径2センチほどの銀貨。表には上から見た亀が打ち出され、甲羅は粒を並べたように区切られている。裏は、いくつかの区画に割れた深い窪み。所蔵館の解説によれば、海の覇権を握っていたころのアイギナ島の貨幣にはウミガメが打たれ、前458年にアテナイに敗れたのちリクガメに替わったという——同じ島の同じ図柄のまま、海のものが陸のものになった。"}, {"f": "kame04.jpg", "date": "3〜5世紀ごろ", "place": "中国（漢〜六朝）", "title": "双頭の亀の形の「硯」（\"Inkstone\" in the Form of a Double-Headed Turtle）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/51825", "note": "土を焼いた亀が、太い四本の脚でしっかり立っている。甲羅にあたる平たい板は胴とは別の部品で、上に載っているだけなので縁に継ぎ目が見え、表面には六角の網目が細く線彫りされている。所蔵館の題は「双頭の亀の形の“硯”」で、首のあたりにもうひとつ頭のような造形がある。生きた亀の甲羅は外せないのに、道具に写されたとたん、甲羅はまず蓋になる。"}, {"f": "kame05.jpg", "date": "16世紀後半以降", "place": "ドイツ（ニュルンベルク）", "title": "ベーハイム家の紋章を描いた亀の甲羅（Tortoise Shell Painted with the Arms of the Behaim Family）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/112053", "note": "絵ではなく、本物の甲羅。所蔵館の記載ではアオウミガメの背甲で、縦は八十センチある。外側に布を貼って一族の紋章が描かれていたが、いまは赤と金の絵具がわずかに残るだけで図柄は読み取れない。ふちには切れ込みが規則正しく並び、中央に稜が一本走っている——生きものの背骨と肋骨だったものが、壁に掛ける板になっている。なお制作地について、所蔵館は作者欄をドイツ（ニュルンベルク）とする一方、別の欄ではイタリアとしており、館の記載のなかで揺れている——ここでは題と作者欄に従った。"}, {"f": "kame06.jpg", "date": "1700年代（江戸）", "place": "日本", "title": "亀（Tortoise）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1982.164", "note": "縦一メートル二十センチ近い紙いっぱいに、ウミガメが一頭、ほぼ真上から描かれている。甲羅の板は一枚ずつ形と色を変えて写され、四肢は鰭になり、首の白い斑点や鱗の粒まで数えられる。所蔵館は題と年代しか記していないが、朱の細かな書き入れと、この数え上げるような描き方は、江戸期の本草・博物の図に近い（読みはこちら側にある）。"}, {"f": "kame07.jpg", "date": "1825年ごろ（江戸）", "place": "日本", "title": "海亀と浦島太郎（Sea turtles and Urashima Taro）", "artist": "魚屋北渓", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/81135", "note": "大きな亀の背に、白い甲羅の子亀が乗り、尾のあたりからは長い毛のようなものが幾筋も垂れている——甲羅に藻を生やした蓑亀（みのがめ）の型で、日本では長寿のしるしとして描かれてきた。左上の額の中には、海の向こうの御殿と、岸辺に座る人物。添えられた狂歌には「浦嶋太郎」の名が読める。浦島の話に亀が出てくるのは古く、『丹後国風土記』逸文（『釈日本紀』所引）では、島子が釣り上げた五色の亀がたちまち女に変わる。"}, {"f": "kame08.jpg", "date": "1893〜1914年（明治）", "place": "日本", "title": "鶴と亀の徳利（Sake Pourers with Crane and Tortoises）", "artist": "三代 清風与平", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2022.159", "note": "白磁の徳利がふたつ、赤い絵具の線だけで、片方に片脚を上げた鶴、片方に亀。所蔵館の説明では亀の側は三匹（親と子）で、鶴と亀は東アジアで長寿のしるしとされ、亀は一万年、鶴は千年生きるといわれてきた。亀の徳利の裏には十七音の句があり、所蔵館はこれを kame iwaku kamiyo wa, ore no wakaki toki と読み、「亀が言うには、神々の世は自分が若かったころに始まった」と訳している。"}, {"f": "kame09.jpg", "date": "いま", "place": "日本（高知県）", "title": "岩に上がったニホンイシガメ", "artist": "heikindai_87（写真）", "museum": "Wikimedia Commons", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File:Mauremys_japonica_in_k%C5%8Dchi_prefecture_02.jpg", "note": "静かな池のふち、水面すれすれの苔むした岩に、ニホンイシガメが一匹上がっている。甲羅は乾きかけて白っぽく、六角の板の並びと、そこを走る筋がそのまま見える。首を伸ばして水のほうを向いたこの姿勢が、変温動物の一日にきちんと組み込まれている。"}]}, {"id": "tombo", "no": "第十六景", "name": "蜻蛉", "yomi": "とんぼ", "en": "Dragonfly", "rep": "tombo04.jpg", "lead": "水の底で何年も過ごしてから、はじめて空へ出る虫。『日本書紀』はこの国のかたちを蜻蛉に見立て、武士は退かない虫として鍔に彫り、西洋の職人は、あの翅の透明さを硝子と七宝でつくろうとした。", "nature": [["水の底で育つ", "幼虫はヤゴと呼ばれ、水の中で暮らす。折り畳んだ下唇を一瞬で伸ばして獲物を捕らえ、腹の先や腸の内側で水中の酸素を取り込むとされる。幼虫でいる期間は数か月のものから、オニヤンマのように数年に及ぶものまであるという。空を飛ぶ姿とはまるで違う暮らしが、水面の下にある。"], ["一万から三万の目", "複眼は個眼という小さな目の集まりで、その数はおよそ一万から三万とされる。上下左右をいちどきに見わたし、頭を動かせば背後まで届く視野をもつと言われる。ホラーの銅版画が二つの球として彫ったかたまりは、それぞれが数万の目の束である。"], ["前と後ろを、別々に打つ", "翅は四枚。多くの昆虫が二対をひとまとめに打つのに対し、トンボは前の翅と後ろの翅を打つ拍をずらせるとされる。空中に止まる（ホバリング）、後ろへ下がる、急に向きを変える——ほかの虫にはむずかしい飛び方が、この打ち分けから来ていると言われる。"]], "invite": "秋の晴れた日、棒や枯れ枝の先に止まっている赤とんぼを探してみる。見つけたら、頭がどちらを向いているか、風がどちらから来ているかも、一緒に確かめてみる。", "works": [{"f": "tombo01.jpg", "date": "1190年代ごろ（南宋）", "place": "中国（南宋・杭州）", "title": "竹虫図（Bamboo and Insects）", "artist": "呉炳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1964.154", "note": "円い団扇のかたちに張った絹に、竹の枝が右下から差し出される。美術館は、竹の上に浮かぶ蜻蛉、葉に取りついたキリギリスの類、飛ぶ蜂の三匹を数える。いちばん大きいはずの蜻蛉は絹に溶けかけていて、目を寄せてはじめて四枚の翅の輪郭が立ちあがってくる。描いたのは南宋の宮廷の画院にいた人だと伝わる。"}, {"f": "tombo02.jpg", "date": "1646年以降", "place": "ボヘミア（プラハ出身の版画家）", "title": "蜻蛉・てんとう虫・蝶（A Dragonfly, Ladybirds, and Butterflies）、『さまざまな昆虫の図』より", "artist": "ヴェンツェル・ホラー", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/18649", "note": "縦11センチ、横21センチしかない銅版に、蝶と蛾と甲虫を並べ、中央に一匹だけ蜻蛉を大きく据えた。翅は一枚ずつ細かい網目で埋め尽くされ、頭には球のような複眼が二つ彫ってある。標本を並べる図でありながら、この虫だけは翅の構造そのものが主題になっている。"}, {"f": "tombo03.jpg", "date": "江戸時代（1615〜1868年）", "place": "日本", "title": "蜻蛉図鍔（Sword Guard (Tsuba) with Dragonfly）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1919.422", "note": "中央の穴に刀身の根元を通して、柄と刃のあいだに挟む鉄の鍔。上の縁に蜻蛉が一匹、高く浮き彫りにされ、四枚の翅には筋が一本ずつ通り、翅の先と下方に金色の小さな輪が置かれる。蜻蛉は前へしか進まないとして「勝ち虫」と呼ばれ、鍔や兜の意匠に好まれたと伝えられる。美術館は「江戸時代のものか」とする。"}, {"f": "tombo04.jpg", "date": "1833〜34年ごろ（江戸）", "place": "日本", "title": "桔梗に蜻蛉（Bell-Flower and Dragonfly）", "artist": "葛飾北斎", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/25129", "note": "大判の花の連作の一枚。花のむこうの空に、赤い腹の蜻蛉が一匹だけ浮かんでいる。翅は輪郭の線だけで引かれ、内側は紙の色のまま——透けていることを、刷らないことで示している。塗られているのは頭だけで、そこが藍。二つの複眼のありかが、色一つで決まっている。"}, {"f": "tombo05.jpg", "date": "1830年代（江戸）", "place": "日本", "title": "秋海棠に蜻蛉（Dragonfly and Begonia）", "artist": "歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/47513", "note": "幅13センチ、丈37センチの細長い短冊判。細い茎の先で垂れる秋海棠の花に、青緑の腹をした蜻蛉が脚をかけている。翅は輪郭を持たず、薄墨の面だけで四枚が扇のように開く。北斎が線で示した透明を、広重は色の薄さで示している。"}, {"f": "tombo06.jpg", "date": "1800年代（朝鮮王朝）", "place": "朝鮮（現在の韓国）", "title": "蓮と虫と鳥（Lotuses, Insects, and Birds）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1985.18", "note": "絹に描いた掛軸。蓮の茂みに白鷺とカワセミがいて、その上、蕾のすぐ横に、細い朱の線だけでできた蜻蛉が浮かぶ。美術館は、鷺もカワセミも蜻蛉もそれぞれ番いで置かれていると読み、もとは対になる一幅があったのではないか、夏に掛けるための絵ではないかとする。"}, {"f": "tombo07.jpg", "date": "1900〜10年ごろ", "place": "フランス", "title": "蜻蛉のブローチ（Dragon Fly Brooch）", "artist": "ルネ・ラリック", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1964.448", "note": "金に、背板を持たない七宝（プリカジュール）と有線七宝を焼きつけたブローチ。二匹の蜻蛉が左右対称に組み合わされ、翅は金の枠の中に緑の透ける釉が張られて、窓のように光を通す。中央には淡い青の石、四隅には硝子の小さな鈴のような花。翅脈をそのまま金の線に置き換える——ホラーが網目で彫ったところを、素材のほうで解いている。"}, {"f": "tombo08.jpg", "date": "1906年までに", "place": "アメリカ（ニューヨーク州コロナ）", "title": "頭を下げた蜻蛉の笠のランプ（Lamp with Hanging Head Dragonfly Shade and Mosaic and Turtleback Base）", "artist": "ティファニー工房（意匠はクララ・ドリスコルとされる）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/185905", "note": "高さ86センチ。幾匹もの蜻蛉が笠の裾をぐるりと囲み、青い硝子の翅が鉛の筋で細かく区切られる。頭は縁に垂れ、胴は笠の頂へ向かって放射状にのび、そのあいだに緑の硝子の粒が嵌めこまれている。美術館は、この笠と台の意匠を、工房の硝子切り部門を率いたクララ・ドリスコルによるものらしいと記す。"}, {"f": "tombo09.jpg", "date": "いま", "place": "三重県いなべ市・藤原岳（鈴鹿山脈）", "title": "藤原岳のアキアカネ（雄）", "artist": "Alpsdake（写真）", "museum": "Wikimedia Commons", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Sympetrum_frequens_(Mount_Fujiwara).jpg", "note": "2016年9月11日、鈴鹿山脈の藤原岳。枯れ枝の先端に、腹の赤いアキアカネの雄が止まっている。翅の一枚ずつに走る細かい脈も、こちらを向いた複眼も、写真だと一度に見える。アキアカネは平地の水田などで羽化したあと夏を涼しい高地で過ごし、秋になって里へ下りて産卵するとされる。この一匹は、九月の山の上にいる。"}]}, {"id": "tora", "no": "第十七景", "name": "虎", "yomi": "とら", "en": "Tiger — the beast most of its painters never saw", "rep": "tora07.jpg", "lead": "日本に虎は棲んでいない。朝鮮半島にいた虎も、二十世紀のうちに姿を消した。それでも東アジアには虎の絵が山ほど残っていて、その多くは、生きた虎を見ないまま、渡ってきた絵と一枚の毛皮から描かれている。", "nature": [["ネコ科でいちばん大きい", "トラ（Panthera tigris）は現生のネコ科でもっとも大きく、大きなオスでは体重が二百キロを超えることもあるとされる。亜種の分け方は揺れていて、従来は八〜九亜種としてきたが、IUCN のネコ科分類作業部会は 2017 年に、大陸のもの（Panthera tigris tigris）とスンダ列島のもの（P. t. sondaica）の二つにまとめる案を示した。バリ島・ジャワ島・カスピ海沿岸にいた集団は、二十世紀のうちに絶滅したとされる。IUCN の 2022 年の評価では、野生に残る成熟個体はおよそ 3,700〜5,600 頭とされている。"], ["縞は、指紋のように", "縞の並びは一頭ごとに違い、写真から個体を見分ける手がかりに使われる。毛だけでなく皮膚にも同じ模様があるとされ、縦に走る縞は、草や竹の縦の影のなかで体の輪郭を断ち切る「分断色」としてはたらくと説明される。狩りは単独で、気づかれずに十数メートルまで忍び寄ってから一気に走る。走れる距離は短く、成功するのは十回に一度ほどとされる——見せ場の前に、届かなかった回数のほうがずっと多い。"], ["朝鮮半島から、いなくなった", "虎はかつてアジアの東から西まで広く分布し、朝鮮半島と中国東北部にも普通にいた。朝鮮王朝では虎による被害（虎患）が飢饉や疫病と並ぶ災いとされ、虎を捕らえる専門の武官（捉虎甲士）が置かれた記録が残る。日本統治期には「害獣駆除」の名で組織的な捕獲が行われ、半島南部では 1921 年に慶州（現在の慶尚北道）で捕られた個体を最後に、確実な記録が途絶えたとされる。いま北の系統（アムールトラ）が残っているのは、ロシア極東と中国東北部の森である。"]], "invite": "虎の絵を見かけたら、まず顔だけを見てみる。生きた虎を見ずに描かれた虎は、たいてい猫か、人の顔のほうへ寄っている（そう見えるのはこちら側だけれど）。", "works": [{"f": "tora01.jpg", "date": "前206〜後220年ごろ（漢）", "place": "中国（漢〜六朝）", "title": "歩く虎（Walking Tiger）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1964.233", "note": "首を長く伸ばし、口を開けて歯を見せ、四本の脚でしっかり歩いている銀の獣。目のまわりに渦が彫られ、胴には肋のような筋が刻まれ、尾は先で一度くるりと巻いている。所蔵館の説明では、頭と胴・四本の脚・尾の六つに分けて鋳造し、あとから溶接してつないだという。なお館の記載では制作年を「前206〜後220年」としながら、文化の欄は漢から六朝（265〜587年）までを含めており、時代の幅がそろっていない。"}, {"f": "tora02.jpg", "date": "1250〜79年ごろ（南宋）", "place": "中国（南宋）", "title": "虎図（Tiger）", "artist": "牧谿（法常）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1958.427.2", "note": "絹が茶色に沈んでいて、はじめは何が描かれているのか分からない。目が慣れてくると、首を曲げて前足を舐める虎が浮かび、画面の手前に縞の入った尾が長く伸びているのが見えてくる。所蔵館の説明では、これは龍と対になった二幅のうちの一幅で、もとは禅寺で観音などの中央の像をはさんで掛けられていたらしく、舌と鼻にわずかにあった赤みはいまはほとんど褪せている。館はまた、牧谿の水墨が日本でとりわけ好まれ、集められたと記す——日本の絵師が最初に見た「虎」は、生きた虎ではなく、こういう絵だった。"}, {"f": "tora03.jpg", "date": "1546〜56年ごろ（室町）", "place": "日本", "title": "龍虎図屏風（虎の隻）（Dragon and Tiger）", "artist": "雪村周継", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1959.136.2", "note": "六曲の屏風いっぱいに、竹と岩と滝。その左寄りに大きな獣が体をひねって顔を上げていて、毛皮には縞ではなく輪のような斑がまばらに散り、顔は目を丸くした猫にかなり近い。所蔵館は「中国では虎の咆哮が風を起こすとされ、雨雲を呼ぶ龍と対にされた」と記したうえで、雪村のこの虎はおそらく、当時日本に入ってきていた朝鮮王朝の虎の絵を下敷きにしている、と付け加えている。対になるもう一隻には、渦を巻く雲のなかの龍が描かれている。"}, {"f": "tora04.jpg", "date": "1700年代（朝鮮王朝）", "place": "朝鮮半島（朝鮮王朝）", "title": "虎豹図（Tigers and Leopard Frolicking）", "artist": "作者不詳（署名「湖南…山人」）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1998.292", "note": "墨だけの横長の画面に、松の下で三頭。左は正面を向いた虎で、目が二つとも真ん丸に開き、中央には輪の模様に埋まった豹、右にもう一頭の虎が身を低くしている。左上に「虎豹歡樂圖」と読める題と署名・印があり、所蔵館は署名を「湖南（半島南西部）の山中の隠者」と読んでいる。館の説明によれば、朝鮮王朝の絵師は豹を虎の子と見なすことがあり、そのために虎と豹が一家のように並ぶのだという——虎を見た者が少なければ、豹との区別もまた伝聞になる。"}, {"f": "tora05.jpg", "date": "1830〜40年ごろ", "place": "インド北西部（ラージャスターン・コーター）", "title": "ラーム・シング二世の虎狩り（Tiger Hunt of Ram Singh II）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1991.168", "note": "紫がかった岩山の下、黄色い体に黒い縞の虎が一頭、こちらへ顔を向けて立っている。左の崖には角笛と太鼓の男たち、右には棒で熊を押しとどめる男たち、下の川には楽人を乗せた舟と、王の乗る赤い舟。所蔵館の説明では、火を掲げた囃し手が虎を森から追い出し、王がいままさに撃ったところで、太鼓と角笛は「王が虎を仕留めた」と人々に告げているのだという。ここまで見てきた絵の虎が伝聞でできているのに対して、この虎だけは、描き手のいる土地に本当に棲んでいた。"}, {"f": "tora06.jpg", "date": "1860年（万延元年）", "place": "日本", "title": "寫生猛虎之図（Picture of a Ferocious Tiger Drawn from Life）", "artist": "初代 歌川国麿", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/103331", "note": "竹に見立てた枠の題は「寫生猛虎之圖」——見て描いた猛虎の図、と名乗っている。ところが座っている獣の毛皮は縞ではなく、輪のかたちの斑で一面に埋まり、白い喉から長い尾の先まで斑が続く（前足のそばには羽をひろげた鳥がいる）。書き入れは「萬延元年五月の末」に始まり、「加奈川」の地名と「阿蘭陀人の持渡る」の一句が読める——港が開いて間もない横浜のあたりで、外から来た人の連れていた獣を写した、ということらしい。見て描いたと題にありながら、その獣が虎だったのかどうかは、この一枚からは決められない。"}, {"f": "tora07.jpg", "date": "1800年代後半（朝鮮王朝）", "place": "朝鮮半島（朝鮮王朝）", "title": "虎家図（Tiger Family）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1997.148", "note": "縦一メートル七十センチの紙の中央に、灰褐色の地に黒い縞の大きな虎が座り、丸い黄色の目でこちらを見ている。肩のうしろに子虎が一頭よじ登り、足元にもう一頭、右下には輪の模様の豹が顔を出し、上に張り出した松の枝の間には赤い日。所蔵館は、松＝長寿、母虎と子＝繁栄、豹＝幸運の組み合わせと読み、朝鮮では大晦日に恐ろしい顔の虎の絵を戸口に貼って邪気を払ったと記す。館はさらに、この型の絵にはふつうカササギが描き添えられるが、ここでは代わりに松の奥へ朝日が置かれている、と付け加えている。"}, {"f": "tora08.jpg", "date": "1900年代はじめ（朝鮮王朝）", "place": "朝鮮半島（朝鮮王朝）", "title": "「虎」字の板絵（Painted Panel of Character \"Tiger\"）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1998.119.1", "note": "上から順に、蓮の花、青と赤の輪のなかに太い筆で書かれた一字「虎」、牡丹、雲のなかの龍、鳳凰、そして最下段に赤い帯のあいだで組み合う青緑の獣が二頭。縦二メートル三十六センチ、四幅ひと組のうちの一本にあたる。所蔵館の説明では、四幅にはそれぞれ「虎」「龍」と、英語で whistle・recite と記される二字が書かれ、屋外の仏教の儀礼に使われたものらしい。虎と龍は四方を守る獣のうち西と東を受け持つ、と館は付け加えている——ここで虎は、獣としてではなく、まず一つの字として立っている。"}, {"f": "tora09.jpg", "date": "いま", "place": "スイス（チューリッヒ動物園）", "title": "雪の上のアムールトラ", "artist": "albinfo（写真）", "museum": "Wikimedia Commons", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Siberian_Tiger_enjoying_snow_10.jpg", "note": "雪の積もった石垣の上に、アムールトラが一頭、腰を下ろしてこちらを見ている。うしろは雪をかぶった針葉樹で、その奥に石を詰めた擁壁と、木の間を横切る細い柵が写り込んでいる——チューリッヒ動物園、2017年1月の一枚。喉から腹にかけての白、脇腹を縦に走る黒、頬から横へ立つ長い毛。八枚の絵を見てきた目でこれを見ると、絵のほうの縞がどれも整いすぎていたことに気づく（そう思うのはこちら側だけれど）。"}]}, {"id": "rakuda", "no": "第十八景", "name": "駱駝", "yomi": "らくだ", "en": "Camel — dromedary and Bactrian", "rep": "rakuda07.jpg", "lead": "こぶに水は入っていない。詰まっているのは脂肪で、乾きに耐えているのは、冷える鼻の奥と、楕円形の赤血球と、日中に大きく上下する体温のほうである。その体を、人は三千年ほど借りつづけてきた——荷を載せ、王を乗せ、そして一頭も駱駝のいない土地に着いた日には、寸法を書き添えた紙に刷って、見世物にした。", "nature": [["こぶは一つか、二つか", "駱駝には二種類ある。ヒトコブラクダはアラビア半島から北アフリカ、南アジアにかけて、フタコブラクダは中央アジアから中国北部にかけて——こぶの数が、そのまま分布の違いになっている。家畜としてはどちらも広く飼われてきたが、野生となると話は別で、ヒトコブラクダに野生の個体群は残っていないとされる（オーストラリアなどには、持ち込まれて野生化した群れがいる）。フタコブラクダのほうは、家畜のもの（Camelus bactrianus）とは別種として、野生のフタコブラクダ（Camelus ferus）が中国とモンゴルのゴビ砂漠のごく一部に残っている。個体数はおよそ千頭を下回るとされ、IUCN のレッドリストに絶滅のおそれのある種として載る。だから絵を見るときは、まずこぶを数えるとよい。唐の俑と江戸の錦絵は二つ、パルミラの石もイランの写本もジェロームの油彩も一つである。"], ["こぶに水は入っていない", "よくある誤解の代表格だが、こぶの中身は脂肪で、水ではない。脂肪を分解すれば水（代謝水）は生じるものの、そのぶん余分に呼吸すれば、そこで失う水のほうが多くなるとされ、こぶを水筒に見立てる説明は成り立たないとされる。乾きに耐えるしくみは、もっと地味なところに分かれて置かれている。赤血球が楕円形をしていて、渇いたあとに一気に水を飲んでも、膨らんで壊れにくいと説明される（哺乳類でこの形は珍しい）。吐く息にふくまれる水は、冷えた鼻の奥で結露して回収されるとされる。体温は日中に大きめの幅で上下し、そのぶん汗を減らせるという。体重の四分の一ほどの水を失っても耐えられるとされ、渇いた個体は百リットル前後を短い時間で飲むといわれる——ただしこの手の数字は、出典によって幅がある。"], ["道具としての体", "駱駝は偶蹄目だが、蹄で立ってはいない。二本の指の下に広い肉の座があり、体重をかけると横へ広がって、砂に沈みにくい。睫毛は長く、上まぶたでは二重に並ぶとされ、鼻の穴は閉じることができる。砂の中を歩くための体が、そのまま人の道具になった。荷駄としては百五十から二百キロほどを負って一日に三十から四十キロ進むといわれ（品種と条件で幅がある）、乳と毛と肉を出し、糞は乾かして燃料になった。いつ家畜になったかについては見積もりに幅があるけれど、少なくとも三千年以上前には、荷を運ぶ動物として使われていた。パルミラの石灰岩と唐の三彩は、その隊商を写したものである。"]], "invite": "動物園で駱駝に会ったら、こぶの数を数えてから、足もとを見てみる。蹄ではなく、二本の指の下に広がった肉の座布団の上に、この大きな体は載っている。", "works": [{"f": "rakuda01.jpg", "date": "100〜150年", "place": "シリア（パルミラ）", "title": "貴人たちの行列（Procession of Nobles）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1970.15", "note": "横一メートル二十センチの石灰岩の帯。左のふたりが乗っているのは駱駝である——S字に曲がった首、小さな頭、鞍布の下でひとつ盛り上がるこぶ、そして細い脚。右のふたりの乗るのは、飾りをちりばめた馬具の馬で、乗り手はみなパルティア風の装束をつけている。パルミラはローマとパルティアのあいだの交易の要で、この駱駝は街を富ませた隊商を指すのだろう、と所蔵館は書く。ただし館はあわせて、この浮彫がパルミラのものだとされる根拠は様式の比較だけであり、遺跡のどこから出たのかは分かっていない、とも記している。産地の同定そのものが確定していない一点である。"}, {"f": "rakuda02.jpg", "date": "5世紀", "place": "東地中海（おそらくシリア）", "title": "草を食む駱駝のモザイク断片（Mosaic Fragment with Grazing Camel）", "artist": "作者不詳（ビザンティン）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/35355", "note": "縦一メートル四十センチ、横一メートル六十センチあまりの床。首を深く下げ、口を地面につけて草を食む一頭が、石の粒（テッセラ）で組まれている。輪郭は濃い石、体は茶と灰の石。背のこぶはひとつきりで、荷も鞍もない。所蔵館の説明では、首から鈴を下げていることがこの駱駝に飼い主がいたことを示しており、その飼い主の足が右下の隅に残っているという。隊商の絵ではなく、床の上を歩く人が見下ろす位置に置かれた、一頭の家畜である。"}, {"f": "rakuda03.jpg", "date": "8世紀前半（唐）", "place": "中国", "title": "駱駝と騎者（Camel and Rider）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/32532", "note": "高さ八十六センチ。褐・緑・白の鉛釉をかけた三彩の陶で、こぶは二つ——中央アジアのフタコブラクダである。首をのけぞらせ、口を開けて鳴いている。荷鞍の左右には獣の顔をかたどった袋と板がくくりつけられ、その上に、とがった帽子の男が片手を挙げて乗る。所蔵館の説明によれば、こうした俑をつくった職人はフタコブラクダの隊商をよく見て土に写しており、その隊商を率いていたのは、中国北西の縁、タクラマカン砂漠から来た駱駝引きだった。唐では駱駝は珍しく、西の品を運んでくることから縁起のよいものとされたという。これは墓に納めるための像である。"}, {"f": "rakuda04.jpg", "date": "16世紀（サファヴィー朝）", "place": "イラン（タブリーズまたはカズヴィーン）", "title": "バフラーム・グールとアーザーデ ── フィルドウスィー『シャー・ナーメ』より（Bahram Gur and Azada, from a Shahnama）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1915.597", "note": "未完成のまま残った一葉で、背景の草木は金の下絵の線のまま置かれている。右上、こぶがひとつの駱駝の背に横向きに座り、竪琴を弾いているのがアーザーデ。青い手綱、花文の鞍掛け。画面の下では、青い馬に乗った人物が弓を引き絞っている。所蔵館はこれを、イスラーム以前のペルシアの王バフラーム・グール（在位420〜438とされる）の狩りの場面とし、竪琴弾きのアーザーデが「一矢で鹿の足と耳を射よ」と難題を出したのに対し、王は石を鹿の耳に投げつけ、掻こうとしたところを射た、と説明する。『シャー・ナーメ』はフィルドウスィー（940〜1019または1025）の叙事詩。他館の同じ場面の解説では、ふたりは一頭の駱駝に相乗りして狩りに出る。この葉では、アーザーデが駱駝の上、王が馬の上に分かれている——なぜそうなったのかは、絵からは分からない。"}, {"f": "rakuda05.jpg", "date": "16世紀第3四半期", "place": "イラン（ホラーサーン）", "title": "寄せ絵の駱駝と付き添い（Composite Camel with Attendant）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/447804", "note": "縦二十センチの小さな画面。歩いている一頭の駱駝は、近づいて見ると全身が人と獣でできている。頭は獣の顔がふたつ重なったもの、首では白い被り物の人と髭の男が押し合い、こぶのあたりには丸々とした人がひとり座り、胴には青い棒を握る男と、横たわる大きな猟犬と、鼻の尖った狐がいる。尻尾はサル、四本の足の先はどれも人の顔である。背には青地に金の唐草の鞍。その上に立つ淡い青の布には、走る猟犬と横たわる兎が描かれている。左では赤い上着の付き添いが棒を振り上げている。生きものを寄せ集めて一頭の姿にする描き方は、イスラーム圏の細密画に型として知られるもの。誰がどの部分を貸しているのかを数えていくと、駱駝の輪郭のほうが先に消える。"}, {"f": "rakuda06.jpg", "date": "1590年ごろ", "place": "ムガル朝インド", "title": "コーヒク川でスルターン・アリー・ミールザーと会うバーブル ── 『バーブル・ナーマ』より（Babur meeting with Sultan Ali Mirza at the Kohik River）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1971.85", "note": "馬と人でびっしり埋まった画面の、左下の隅に近いところに駱駝が二頭いる。赤い荷を背に載せ、首には赤い房と金の鈴の列。一頭は前脚を折ったまま立ち上がろうとしていて、裸足の男が赤い上着で腕を上げ、追い立てている。所蔵館の説明では、これは1496年、十三歳のバーブルが、同じくサマルカンドを狙う相手と川辺で対峙した場面で、デリーを取ってムガル朝を開くのはその三十年後のこと。乾いた土地を長く旅してきた、と館は書く。絵の主役は上方の白馬の人物のほうで、駱駝は隅にいる。その旅の荷を負っていたのは隅の二頭だ、と数えなおすのは、こちら側の見方である。"}, {"f": "rakuda07.jpg", "date": "1863年（文久3）", "place": "日本（江戸）", "title": "新渡駱駝写真（しんとらくだしゃしん）", "artist": "歌川芳豊（一龍斎芳豊）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/32159", "note": "大判の錦絵いっぱいに、こぶを二つ持った駱駝が一頭。その腹の下に立つ黒羽織・黄の格子袴の男は、背丈が駱駝の腹にも届かない。画面には寸法が書き添えてある——「首の長サ五尺五寸」「總髙サ壱丈三尺」「背ノ瘤二ツあり」「髙サ壱尺八寸」、そして「浅草奥山ニおゐて興行仕候」。曲尺の一尺を約三〇センチとすると、総高一丈三尺はおよそ三・九メートルにあたる。フタコブラクダの背丈がこぶの頂までで二メートル余りとされるのに比べると、かなり大きい。見世物の口上の数として読めるが、そう読むのはこちら側である。日本に駱駝が来た記録じたいは古く、『日本書紀』巻第二十二・推古天皇七年（599）秋九月の条に「百濟貢駱駝一匹・驢一匹・羊二頭・白雉一隻」とある。一頭も駱駝のいない土地に駱駝が来た日は、この島で何度もあった。"}, {"f": "rakuda08.jpg", "date": "1880年代", "place": "フランス", "title": "オアシスを発つ（Leaving the Oasis）", "artist": "ジャン＝レオン・ジェローム", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1977.126", "note": "板に油彩、横八十一センチ。薄明の空に桃色の雲が残り、椰子と白い天幕を背にして、こぶがひとつの駱駝が何頭も、列になってこちらへ歩いてくる。二頭目は白い。左手前では犬が地面すれすれに駆けている。所蔵館の説明では、ジェロームは駱駝の隊商とオアシスと広い砂漠を繰り返し描いた画家で、写真のように滑らかに見えるこの絵も、実際にはアトリエで、記憶と写生をもとに組み立てられたという。ここで断っておきたいのは、これが駱駝の土地の人の描いた絵ではないことである。十九世紀のヨーロッパが「東方」を描いた絵——オリエンタリズムの絵で、見えているのは、そこへ出かけていった側の目である。同じ動物でも、パルミラの石やイランの写本とは、立っている場所が違う。"}, {"f": "rakuda09.jpg", "date": "いま", "place": "モンゴル（ゴビ）", "title": "ゴビの草を食むフタコブラクダ", "artist": "Bernard Gagnon（写真）", "museum": "Wikimedia Commons", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File:Camels_in_Gobi_Desert_01.jpg", "note": "ゴビ・グルヴァンサイハン国立公園。まばらな草の生えた乾いた地面に、六頭が散らばっている。こぶは二つ、毛は白っぽいものから赤茶までさまざまで、何頭かは首を下げて草を食んでいる。荷はない。鞍もない。奥に低い山が連なる。千年以上、絵の中で荷を運ばされてきた動物が、ここでは何も載せずに、ただ草を食べている。"}]}, {"id": "zou", "no": "第十九景", "name": "象", "yomi": "ぞう", "en": "Elephant", "rep": "zou05.jpg", "lead": "パーリ語の仏典『ウダーナ（自説経）』6・4に、サーヴァッティーの王が、生まれつき目の見えない人たちを集めて象に触らせる話がある。耳に触れた者は箕だと言い、脚に触れた者は柱だと言い、しまいに殴り合いになって、話は「一つの部分だけを見た人びと」という一句で閉じる。象はそれから、神の頭になり、王の乗り物になり、江戸の見世物になった——どの窓から覗いても、見えるのはやはり一つの部分である。", "nature": [["アフリカゾウとアジアゾウ", "ひとくちに象と言うが、いま生きているのは大きく二つの系統で、属からちがう。いちばん確かな見分けどころは鼻の先で、アフリカゾウには指のような突起が二つ、アジアゾウには一つある。耳はアフリカゾウのほうが大きく、肩にかかるほど広がる。牙は、アフリカゾウでは雌雄ともに持つのがふつうで、アジアゾウで外から見えるほどの牙を持つのは主に雄——雌はふつう目立つ牙を持たない。背中の線も、アジアゾウは丸く盛り上がり、アフリカゾウは中ほどがくぼんで見えるとされる。なおアフリカの側はさらに分かれ、国際自然保護連合（IUCN）は2021年、サバンナゾウとマルミミゾウをはじめて別々の種として評価し、いずれも絶滅のおそれがあるとした。"], ["鼻は、筋肉でできた手", "象の鼻は、鼻と上唇がひとつになったもので、骨も関節もない。全体が筋肉の束で、その数はおよそ四万とも言われる（何を一束と数えるかで数字は変わる）。この一本で、木を押し倒す力も、地面の一粒をつまむ細かさも出る。水は鼻で吸い上げてから口へ送るので、飲むときは鼻を水に沈め、口は水の上にある。サンスクリットで象を hastin（ハスティン）と呼ぶのは hasta＝手に由来し、「手を持つもの」という意味になる。鼻を手と見たのは、こちら側が最初ではない。"], ["群れと、低い声", "群れはふつう、年長の雌を頭にした母系の集まりで、雄は育つと群れを離れる。年長の雌ほど、聞き慣れない声を聞き分ける力が高いという研究がある。声のなかには、人の耳の下限とされるおよそ20ヘルツを下回る低い成分を含むものがあり、1980年代に報告されて以来、数キロ離れた個体どうしが低い声で通じ合っているとされる。足や鼻先で地面の震えを受け取っている可能性も研究されているが、まだ確かめられている途中である。この低さを録るには機材の低い側の特性がものを言う。手元の機材で録れるかどうかは、まだ試していないので分からない。"]], "invite": "次に象の写真や映像を見かけたら、顔ではなく鼻の先を見てみる。突起が二つならアフリカゾウ、一つならアジアゾウ。そのあとで耳の大きさと背中の線を見ると、同じ「象」が二通りに分かれていく。", "works": [{"f": "zou01.jpg", "date": "1070年ごろ", "place": "インド（南インド・チョーラ朝）", "title": "ガネーシャ（Ganesha）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1970.62", "note": "高さ五十センチほどの銅像。象の頭に人の胴がつき、腕は四本。円錐形の冠をかぶり、鼻はまっすぐ下りたあと横へ折れて、下の手のひらに載った丸いものへ届いている。館の説明では、シヴァに首を落とされた子を、母パールヴァティーの求めに応じて、最初に出会った生きもの——象——の頭で生き返らせた、という筋がいちばん広く知られる版だという。館はまた、四本の手のうち一本が自分の折れた牙を持つとし、その牙を筆にして『マハーバーラタ』を書きつけた、という伝えに結びつけている。象の頭がここにあるのは獣を写すためではなく、障りを取り除く力の顔として据えるためである。"}, {"f": "zou02.jpg", "date": "1590年ごろ", "place": "インド（デカン・ゴールコンダ）", "title": "合成の象に乗る君主（A prince riding a composite elephant）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2013.282", "note": "遠目には、輿を載せた象が一頭。近づくと象が崩れる。四本の脚は膝をついた人がそのまま脚のかたちに収まったもので、腹には人の顔と獣の頭がすき間なく詰まり、鼻は細長い生きものが伸びたもので、その先はまた別の獣の口になる。館は、頭のあたりで二頭の獅子が一つの頭を分けあっていると指摘する。いちばん下、脚と脚のあいだには兎が一匹うずくまっている。彩色されているのは輿と敷物と、そこに座る若い君主だけで、象の体は薄い線のまま——目を寄せるほど象がほどけるように作ってある。館の説明では、デカン地方の絵師たちがペルシアのやり方を広げてこうした「合成の生きもの」を作り、人が集まる席で見て楽しむ画帖に仕立てたという。"}, {"f": "zou03.jpg", "date": "1602〜03年ごろ（縁は1700年代に追加）", "place": "ムガル朝インド", "title": "1564年、マールワーでの野生象の捕獲を差配するアクバル帝（『アクバル・ナーマ』第90図）", "artist": "帰属未確定（館はファルフ・チェラ／ゴーヴァルダン／ダンラージのいずれかとする）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2013.309", "note": "下半分はほとんど線描のまま残されている。飼い慣らされた象が野生の象を追い、その足元で馬の一団がもつれ、投げ出された姿の男がいる。上半分には川と町と丘が薄い色で置かれ、館の説明では左上の馬上の人物がアクバル帝で、捕獲を差配している。館の記載によれば、ムガル朝は飼い慣らした象で野生の象を追い、綱でつないで、好物の餌を与えて馴らした。王の厩の象は、こうして森から来る。なお作者について館は三人の名を並べたままで、一人に定めていない。"}, {"f": "zou04.jpg", "date": "1700〜1730年", "place": "インド（ラージャスターン・コータ）", "title": "闘う二頭の象（Two Elephants in Combat）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2018.178", "note": "墨の線だけの下絵。二頭が額を突き合わせ、鼻を高く絡ませて押しあう。頭と鼻には細かい線が入るのに、胴から尻へ向かうほど線は素っ気なくなり、輪郭だけになる。そして両方の後ろ足に、輪と鎖がついている。左の一頭の鎖は画面の左下へ長く伸び、布を巻きつけたような塊に結ばれている——館は、逃げ出さないように後ろ足を繋いだのだと記す。象の闘いはラージプートの王が好んだ見もので、そのために仕込まれた象がいた、というのが館の説明。力比べの図であると同時に、鎖の図でもある。"}, {"f": "zou05.jpg", "date": "1761年ごろ", "place": "インド（ラージャスターン・メーワール、ウダイプル）", "title": "象使いを乗せた王の象ラムカリー（Royal Elephant Ramkali with a Mahout）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2005.202", "note": "水色の地に、灰色の象が一頭だけ。首から鈴の房を下げ、前後の足に金の環をつけて、速足で歩いている。背には黄色い覆いと座、緑の衣の象使い（マハウト）が腰かけ、鉤のついた突き棒（アンクシャ）を立てて持つ。上の朱の縁にはデーヴァナーガリーで名が書き入れてあり、館はこれを「ラムカリー」と読む。ウダイプルの王の厩の象を一頭ずつ描いた連作の一枚で、余白の名は、この絵が種ではなく個体の肖像であることを示している。館はこの個体を雌とするが、口もとには短い白い牙が描かれている——アジアゾウの雌は外から見える牙をふつう持たないので、これが絵の約束事なのか、この一頭の特徴なのかは、ここでは決められない。"}, {"f": "zou06.jpg", "date": "1767〜68年ごろ（江戸）", "place": "日本", "title": "白象に乗る若い女（普賢菩薩の見立て）", "artist": "鈴木春信", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/20919", "note": "白い大きなかたまりの上に、若い女が横向きに座り、長い巻紙を広げて読んでいる。かたまりの下のほうに小さな黒い目がひとつあり、そこから細い紅の線が前へ伸びて、先が巻いている——これが鼻である。縁は毛のようにけば立ち、生きた象というより、白い毛皮の山に見える。普賢菩薩は白い象に乗り経を持つ姿で描かれてきた。その仏画の型を当世の女に移したのが、この一枚である。象そのものを写した絵ではなく、象という型を写した絵——という言い方は、こちら側の読み。"}, {"f": "zou07.jpg", "date": "1863年（江戸）", "place": "日本（江戸）", "title": "天竺の象、このたび両国広小路において見世物興行の図", "artist": "歌川芳豊", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/32478", "note": "黒い象が水を噴いている。鼻を高く上げ、その先から白い筋が何本も飛ぶ。左には水を張った黄色い桶。口を開けて短い白い牙をのぞかせ、頭から鼻にかけての皺が一本ずつ線で追ってある。象の向こうには、赤い上着に丸い帽子の男が立って、片手を象の頭に置いている。右上の額の文字は、館の記載で「天竺の象、このたび両国広小路において見世物興行の図」と読まれる。同じ年の同じ象を描いた錦絵は、シカゴ美術館だけでも別の絵師の手で何点も残っている。前の一枚の白いかたまりから百年、象は型ではなく、人の前で水を噴くものになった。"}, {"f": "zou08.jpg", "date": "1900年代はじめ", "place": "アフリカ（カメルーン・グラスフィールド）", "title": "象の面（mbap mteng）", "artist": "バミレケ様式の作り手", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1985.1082", "note": "布に細かなガラス玉を一粒ずつ縫いつけた面。上に目と鼻と口のある顔があり、その左右に円い大きな耳が張り出す。顔の下からは、長い帯が一枚まっすぐ垂れる。全体で一メートル四十センチ近い。この垂れを象の鼻と見る説明は広く行われているが、館の記載にはない。館によれば mbap mteng は「耳の大きな獣」の意で、カメルーン高地の王国では象は力と権威と指導のしるし。ガラス玉はヴェネツィアやボヘミアから運ばれてきたもので、富をあらわす。三角の文様は豹を思わせ、豹もまた王の獣とされる。クオシ（Kuosi）と呼ばれる男たちの結社が、儀礼の踊りや葬送でこれをつけた。外から象を写した像ではなく、象になるための道具である。"}, {"f": "zou09.jpg", "date": "いま", "place": "アフリカ（ナミビア・エトーシャ国立公園）", "title": "水場のアフリカゾウ（サバンナゾウ）", "artist": "Giles Laurent（写真）", "museum": "Wikimedia Commons", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:079_Herd_of_African_bush_elephants_drinking_in_Etosha_National_Park_Photo_by_Giles_Laurent.jpg", "note": "夕方の光の水場。アフリカゾウが身を寄せて水に入り、そろって鼻を水面に下ろしている。鼻の先は水の中、口は水の上——鼻で吸い上げてから口へ送るので、飲むときはこの姿勢になる。手前の大きな一頭の陰に、体の小さな一頭が半分隠れている。耳は肩にかかるほど大きく、どの個体にも短い牙が見える。撮影は2025年7月30日、ナミビアのエトーシャ国立公園。"}]}, {"id": "shishi", "no": "第二十景", "name": "獅子", "yomi": "しし", "en": "Lion — the animal never crossed; only the shape did", "rep": "shishi05.jpg", "lead": "西アジアの王は、獅子を狩る自分の姿を、宮殿の壁にも銀の皿にも彫らせつづけた。その形は東へ運ばれ、ライオンが一頭も棲まない中国や日本にまで届いて、寺の門前に座り、牡丹のあいだで転げ、しまいには人の手が持ち上げる赤い頭になった。動物は一度も渡っていない。渡ったのは形だけである。", "nature": [["群れをつくる、ただ一種のネコ", "ライオン（Panthera leo）は、現生のネコ科でほぼ唯一、群れ（プライド）をつくって暮らす種とされる。群れの芯は血のつながった雌たちとその子で、狩りの多くを担うのも雌である。たてがみを持つのは雄だけで、量も色も個体差・地域差が大きい。体重は雄でおよそ150〜250キロ、雌でおよそ110〜180キロとされる。分布はかつてアフリカから西アジア・インドまで広がり、バルカン半島など南東ヨーロッパにも及んでいたとされるが、いまはサハラ以南のアフリカが中心で、アジアにはインド西部・グジャラート州のギル林とその周辺に残るだけになった。2020年の調査ではおよそ670頭と報告された。亜種の分け方は揺れていて、IUCN のネコ科分類作業部会は2017年、北・西・中央アフリカとインドのもの（P. l. leo）と、東・南アフリカのもの（P. l. melanochaita）の二つにまとめる案を示した。"], ["吼える喉", "ネコ科のうち吼え声を出せるのはヒョウ属（Panthera）の一部で、ライオンの声はおよそ8キロ先まで届くという数字がよく挙げられる。なぜ吼えられるのかは、まだ一つの説明に落ち着いていない。古くは「舌骨が完全に骨化していないから」と説明されたが、それだけでは足りないことが分かってきた（舌骨が骨化していないユキヒョウは吼えない、とされる）。近ごろは、声帯のひだが四角く平たく、脂肪と弾性繊維に富んでいて、少ない息で低い音を安定して出せることのほうが注目されている。いずれにせよこれは「遠くの仲間に届かせる」ための声で、群れで暮らすことと切り離せない。門の獅子が口を開けているのはこの声のかたちだ、と読みたくなるが、そう読むのはこちら側である。"], ["門に立たされた獣", "西アジアでは、獅子は早くから王のしるしだった。王が獅子を狩る図は、アッシリアの宮殿の壁からササン朝の銀皿まで、千数百年にわたって作られつづけている。もう一つの役目は門で、都の門や大路の壁、寺の入口に置かれ、外から来るものを止める獣とされた。ライオンのいない土地へ渡ったのは、この形と役目だけである。サンスクリットの siṃha（シンハ）が中国で「師子／獅子」と写され、日本語の「しし」になったとされる——日本語の「しし」にはもともと食用の獣という意味があり（猪、鹿）、そこへ外から来た獅子が重なった。日本の社寺の門前の一対は、古い記録では片方を獅子、角のある片方を狛犬として書き分けており、のちに両方まとめて狛犬と呼ぶことが多くなった。区別の仕方は時代と土地で揺れるので、目の前の一対がどちらなのかは、見ただけでは決められないことが多い。"]], "invite": "近所の神社の門前で、左右の石の獣を見くらべてみる。角があるか、口が開いているか閉じているか——二頭が同じ顔でないなら、そこには獅子と狛犬という別々の名前の名残があるかもしれない。", "works": [{"f": "shishi01.jpg", "date": "前9〜前8世紀ごろ（新アッシリア）", "place": "メソポタミア（ニムルド・新アッシリア）", "title": "吼える獅子の頭の家具部材（Furniture element carved in the round with the head of a roaring lion）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/325562", "note": "高さ十センチに満たない象牙の塊が、口を大きく開けた獅子の頭になっている。上あごの歯が一列に並び、鼻のまわりには波打つ筋が刻まれ、頭のうしろには三角を並べた縁がまわる。象牙は全体が黒く沈んでいるが、館の公開データにあるのは材質（象牙）と年代と出土地——ニムルド（古代のカルフ）——だけで、この色については何も記されていない。館の分類はあくまで「家具部材」で、つまりこの獅子は、椅子か寝台かの角に取りつけられて、部屋の中で口を開けていたことになる。"}, {"f": "shishi02.jpg", "date": "前604〜前562年ごろ（新バビロニア）", "place": "メソポタミア（バビロン・新バビロニア）", "title": "歩く獅子のパネル（Panel with striding lion）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/322585", "note": "青緑の釉をかけた煉瓦を積み上げて、白い体の獅子が横向きに歩いている。たてがみと肩の毛だけが黄土色の房で表され、口は開き、尾は背より高く跳ね上がる。幅は二メートル二十七センチ、高さは九十七センチ——壁の一部として作られた大きさである。館が場所として挙げるのはバビロン（現在のヒッラ）で、年代の幅（前604〜前562年）はネブカドネザル2世の治世とほぼ重なる。同じ姿勢の獅子が列をなしてイシュタル門から続く大路の壁を埋めていたことが知られており、これは一頭ではなく、行列の一頭である。"}, {"f": "shishi03.jpg", "date": "前500〜前450年ごろ（アケメネス朝）", "place": "イラン（アケメネス朝ペルシア）", "title": "獅子を締める男（Median Lion Strangler）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1960.175", "note": "濃い青の斑が散る石——ラピスラズリ——を彫った、高さ十九センチほどの胸像。縁に粒を並べた丸い帽子、粒で表した顎ひげ、胸の前で交差した両腕。向かって左の腕の下には小さな獅子が押しつけられていて、口を開けた顔と、筋で刻んだたてがみだけがのぞく。館は題で男を「メディア人」と呼びながら、文化の欄には「イラン、アケメネス朝（前550〜前330年）」と書く。メディアはアケメネス朝に先立ち、のちにその帝国に含まれた地方の名で、題と欄が食い違っているのか、装いのことを指しているのかは、館の記録からは決められない。説明文も出土地の記載もなく、確かなのは石と寸法と年代の幅だけである。"}, {"f": "shishi04.jpg", "date": "400〜600年ごろ（ササン朝）", "place": "イラン（ササン朝ペルシア）", "title": "獅子を狩る王ホルミズド2世または3世の皿（Dish with King Hormizd II or Hormizd III Hunting Lions）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1962.150", "note": "直径二十一センチほどの銀の皿。金を差した王が、球を載せた冠をかぶって馬を走らせ、弓を引き絞る。右では獅子が一頭、後ろ足で立って馬の尻へ跳びかかり、下ではもう一頭が伸びて倒れている。館の説明では、獅子狩りは古代西アジアの王の慣わしで、アッシリアの宮殿浮彫（前912〜前612年ごろ）をはじめ繰り返し作られてきたという。冠から王はホルミズド2世（在位303〜309年）と見られるが、馬具や装いの様式は彼の死後ずっとあとのものらしく、後の王ホルミズド3世（在位457〜459年）による記念の品ではないか、と館は書く——題に「2世または3世」と並んでいるのは、そのためである。"}, {"f": "shishi05.jpg", "date": "600年ごろ（唐）", "place": "中国（唐）", "title": "護りの獅子（Guardian Lion）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1965.473", "note": "白い大理石の獅子が、四角い台の上に座っている。高さは八十センチ足らず。たてがみは巻き毛の房を段に重ねたもので、口を開けて歯を見せ、腰のあたりで尾が渦を巻く。中国にライオンは分布しない。館の説明では、こうした獅子は中国の仏教寺院の入口によく置かれ、寺を守っているように見えるが、獅子は仏教の始まりから教えと結びついていて、教え（法）はその吼え声によって広まるとされる、という。なお館は年代を「600年ごろ」としながら、文化の欄には唐（618〜907年）と書いており、王朝の始まりより前の年が入っている。"}, {"f": "shishi06.jpg", "date": "1150〜1220年ごろ（ザンギー朝またはアイユーブ朝）", "place": "北イラクまたはシリア（ザンギー朝・アイユーブ朝）", "title": "獅子頭の台（Lion-headed Stand）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1931.453", "note": "高さ十四センチの真鍮の台。四方へ張り出した腕の先がそれぞれ獅子の頭になり、四本の脚は肉球のついた前足で終わる。胴にあたる面には、銀を象嵌した組紐の文様と細い蔓草が走っている。館は「獅子の頭の角ばった造りが、繊細な銀象嵌と対照をなす」と書く。産地は「北イラクまたはシリア」、時代は「ザンギー朝またはアイユーブ朝」——館の記録そのものが二つのあいだで決めかねている。ここでの獅子は守る獣ですらなく、何かを載せるための脚である。"}, {"f": "shishi07.jpg", "date": "1769〜70年ごろ（江戸時代・明和）", "place": "日本（江戸）", "title": "獅子舞（The Lion Dance）", "artist": "鈴木春信", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/21059", "note": "牡丹と蝶を散らした衣を重ねた人が、片手を高く上げて、赤い獅子の頭を掲げている。赤い顔に白い歯を並べた口、てっぺんに小さな玉と髪の房、うしろには水玉の布が長く垂れる。足元の左にも同じ赤い頭がもう一つ、水玉の布ごと置かれていて、まわりは満開の牡丹。西アジアで王が馬上から射た獣が、ここでは手で持ち上げられる道具になっている。なお館の寸法表記は「36.6 × 22.4 cm（4 3/8 × 8 3/4 in.）」で、センチとインチが合っていない。"}, {"f": "shishi08.jpg", "date": "1772年ごろ（江戸時代・明和）", "place": "日本（江戸）", "title": "唐獅子と牡丹（Chinese Lions and Peonies）", "artist": "礒田湖龍斎", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/21211", "note": "縦二十六センチの小さな紙。下半分に獅子が一頭いて、体じゅうが渦と星のかたちの毛で埋まり、たてがみと尾は桃色の渦の房になり、爪は開き、目は飛び出し、歯がむき出しになっている。毛でも筋肉でもなく、はじめから文様である。上半分を占める大きな白い塊は、輪郭と、紙を押しただけの空摺の渦だけでできていて、色がほとんど載っていない——題が「Lions」と複数であることを思えば、これも一頭の白い獅子と見るのが自然だが、そう読むのはこちら側である。その右下に、線だけで描かれた小さな顔が一つ、岩のきわからのぞく。署名は「湖龍画」。"}, {"f": "shishi09.jpg", "date": "いま", "place": "インド（グジャラート州・ギル国立公園）", "title": "ギルを歩くアジアライオン", "artist": "Rohit Sharma（写真）", "museum": "Wikimedia Commons", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Asiatic_Lion_Royal_Walk_at_Gir_National_Park,_Gujrat,_India.jpg", "note": "乾いた土の道を、雄のライオンが一頭、こちらへまっすぐ歩いてくる。2023年4月、インド西部グジャラート州のギル国立公園——野生のライオンがアジアに残る、ただ一つの場所である。たてがみは薄くて、耳が毛に隠れずに立っている（アジアライオンではよく見られるとされる特徴）。鼻筋には古い傷が何本も走り、口のまわりの毛は乱れ、前足の指のあいだの毛だけが白い。八点の獅子を見てきた目でこれを見ると、あの巻き毛も、渦も、房も、どこにも無いことに気づく。"}]}, {"id": "uma", "no": "第二十一景", "name": "馬", "yomi": "うま", "en": "Horse — it stands on a single toe, and it made the world smaller", "rep": "uma04.jpg", "lead": "『荘子』外篇の「馬蹄」は、馬の本性を蹄と毛から書きおこす——蹄で霜や雪を踏み、毛で風や寒さを防ぐ、と。そこへ伯楽が現れて「我、馬を治むるに善し」と言い、焼き、剃り、削り、印をつけ、おもがいと足枷でつなぎ、厩の桟に並べたところ、死ぬ馬が十に二、三になった、と続く。ここに並ぶ九点も、ほとんどが「治めたあと」から見た馬で、轡があり、鞍があり、鈴が下がっている——人の手が触れていない馬が写るのは、いちばん最後の一枚だけである。", "nature": [["指一本で立っている", "ウマはウマ目（奇蹄目）で、体重を前後それぞれ一本の指で支える。人でいえば中指にあたる第三指で、蹄はその爪が分厚くなったもの。両隣の第二指と第四指は退化して、脚の内側に沿う細い骨（副管骨）としてわずかに残っている。前脚のいちばん目立つ関節は膝ではなく手首（手根）にあたり、そこから下は人の手のひらと中指一本にあたる。胴と前脚をつなぐ鎖骨がなく、肩は筋肉と腱で吊られている。膝から下にはほとんど筋肉がなく、長い腱がばねのようにはたらいて、着地の力をためては返す。短い距離では時速六十〜七十キロに達するとされる。"], ["草を食べる体、うしろに広い目", "ウマは反芻しない。胃は体の大きさのわりに小さく、草の繊維は胃より後ろ——盲腸と結腸にすむ微生物が分解する（後腸発酵）。だから、まとめて食べて休むのではなく、少しずつ長く食べ続ける体で、草地では一日のうち十数時間を食むのに使うとされる。臼歯は丈が高く、砂まじりの草ですり減る分を、生涯かけて少しずつ歯ぐきの外へ送り出していく。目は頭の側面にあって、視野はおよそ三百五十度に及ぶとされ、見えないのは真後ろと、鼻づらのすぐ前だけ。耳は左右べつべつに回り、片方につき十個以上の筋肉が動かしているとされる。うしろを見るために顔を向ける必要がない体で、それでも背に人を乗せた。"], ["家畜化の年代は、まだ動いている", "馬の家畜化は、およそ五千五百年前（前3500年ごろ）の中央ユーラシア——いまのカザフスタン北部のボタイ遺跡——で始まったとされてきた。ただし2018年に報告された古代ゲノムの研究で、ボタイの馬はいまの家畜馬の直接の祖先ではなく、モウコノウマにつながる系統だとされた。さらに2021年の研究では、世界じゅうの家畜馬のもとになった系統はおよそ四千二百年前（前2200年ごろ）の西ユーラシア草原——ドン川とヴォルガ川の下流域——にさかのぼり、そこから前2000年ごろに数百年でユーラシア中へ広がったとされる。乗る技術も一度に揃ったわけではない。轡は早くからあり、鐙が確かなかたちで現れるのは四世紀ごろの東アジアで、のちに草原の道を通って西へ伝わったとされる。年代はどれも研究の進み方しだいで動く。"]], "invite": "次に馬を見かけたら（写真でもいい）、前脚のいちばん目立つ関節に目をやってみる。あれは膝ではなく手首で、そこから下は人でいえば中指一本にあたる。爪の先だけで、あの重さが立っている。", "works": [{"f": "uma01.jpg", "date": "前800〜前600年", "place": "イラン西部（ルリスタン）", "title": "翼あるアイベックスの鏡板をもつ轡（Horse Bit with Winged Ibex Cheekpieces）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1980.102", "note": "馬はいない。あるのは、馬の口に入れる金具だけである。翼のある野生ヤギ（アイベックス）が二頭、顔をうしろへねじって立ち、その胴を貫く輪に、まっすぐな銜（はみ）の棒が通してある。館の説明では、巻いた角と羽根には線が刻まれ、中空で仕上げのない裏側にある小さな輪には、この轡を馬の顔に留める革紐が通っていたらしい。館は「ルリスタン産と言われる」と書いて出所には留保をつけ、鉄器時代の西イランで青銅の武器・馬具・儀仗が多く作られたことのほうを確かなこととして記す。全長は二十四センチほど——人が馬に触れる最初の場所は、たいてい口だった。"}, {"f": "uma02.jpg", "date": "前202〜後220年（漢代）", "place": "内モンゴル・オルドス地域（草原地帯）", "title": "馬（Horse）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1958.79", "note": "手のひらに載る八センチほどの馬。首が太く、頭が大きく、脚は短く、たてがみは首の上に立ったまま刻まれている。地は黒く沈み、そこに金の膜が斑に残る——館の記載は鍍金の青銅。オルドスは黄河が大きく曲がるその内側、内モンゴル南部の草原で、館はこれを漢代のこの地域のものとする。顔には細い線が幾筋も刻まれていて、轡のようにも、毛の流れの表現のようにも見えるが、館の記載になく、この一体からは決められない。あとに出てくる唐の馬と並べると胴の詰まりぐあいがまるで違って見えるけれど、手のひらの鋳物と等身大の副葬品を体つきの資料として比べてよいかは別の話で、違うと見ているのはこちら側である。"}, {"f": "uma03.jpg", "date": "5〜6世紀（古墳時代）", "place": "日本（茨城県で出土）", "title": "馬形埴輪（Horse）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/86366", "note": "高さ八十センチ近い素焼きの馬。耳は二つとも立ち、鼻づらから頬へ革の帯が回り、頬には渦を巻いた金具が貼りついている（古墳時代の馬具には「f字形鏡板」と呼ばれる轡の頬当てがあって形がよく似ているが、館はそう名指してはいない）。胸の帯には山形の刻みが入り、そこから丸い玉が下がる。背には鞍、その脇に紐で吊られた輪が一つ、尻には丸い飾りが並ぶ。館は「鞍・鐙・前後の鈴の飾りをそなえた、装いを尽くした馬」と記し、茨城県の出土であること、こうした埴輪は古墳の前方に据えられていたと考えられることを添え、さらに「大陸から来た馬は軍事に有効で、たちまち富と力のしるしになった」と書く。四本の脚はどれも太い円筒で、そこだけは走るかたちをしていない——装いのほうが、体よりずっと細かく作ってある。"}, {"f": "uma04.jpg", "date": "700年代前半（唐）", "place": "中国（唐）", "title": "馬（Horse）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/111140", "note": "高さ七十センチを超える焼きものの馬が、長方形の台の上に立ち、首をわずかに左へ曲げている。たてがみは首すじの上で一本の稜に整えられ、額には房が一つ。頬と胸と尻を回る帯には、花のかたちの飾りが等間隔に並ぶ。背には黒くごつごつした鞍敷きが載る。館は「唐では馬は軍事の価値と貴族の競技のために重んじられ、最良の馬は中央アジアと、中国の北西の隣国から輸入された」と記し、この馬具の飾りは実際に使われたものによく似ている、とも書く。館の記載は「三彩（さんさい）の鉛釉」だが、写真で目に入る色はたてがみと蹄の飴色と、鞍敷きの黒くらいで、名前ほど派手ではない（釉のかかり方は実物を見ないと分からないので、これはこちら側の見え方）。"}, {"f": "uma05.jpg", "date": "800年代", "place": "中央アジア（ソグド）または東イラン", "title": "騎馬の狩人を織り出した綾（Samite fragment with hunters）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1974.98", "note": "縦二十二センチ、横四十二センチの絹の切れ端。黄色い馬が二頭ずつ向かいあい、前脚を高く跳ね上げ、その背に緑の衣の騎手が乗っている。左半分には同じように対をなす緑の四つ足がいて、館の説明では、これは騎馬の狩人が野生山羊（アイベックス）を追う場面、上下に残る帯は大きな花文の輪の一部だという。館はさらに、意匠はエジプトやシリアの絹の影響を受けているが、この抽象のしかたは中央アジアのソグドらしいもので、この種の絹は多くヨーロッパへ運ばれ、教会の宝物として残された、と記す。草原の狩りの図が、絹の上に載って、教会の櫃の中まで届いた。"}, {"f": "uma06.jpg", "date": "1505年", "place": "ドイツ", "title": "大きな馬（The Large Horse）", "artist": "アルブレヒト・デューラー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1958.113", "note": "画面のほとんどを、馬の尻が占めている。うしろ斜めから見上げる角度で胴が手前に迫り出し、後ろ脚の飛節から下は太く、蹄のまわりに長い毛が垂れる。尾は根元でひとつに束ねてある。頭は左奥にあり、轡から手綱が垂れて柱のほうへ回りこむ。その向こうに、羽根飾りの兜と鎧の男が槍を立てて立っている。上に「1505」、右下にデューラーの組み文字。館は、これが《小さな馬》と対をなす一枚で、小さいほうが彫像のように整った姿を、大きいほうが筋肉と力を見せる役だと記し、この寸法の紙（半裁）は安価でヨーロッパじゅうの絵師の手に渡ったと付け加える。馬を大きく見せる角度をとった結果、人はその後ろに小さく置かれている。"}, {"f": "uma07.jpg", "date": "1596年ごろ", "place": "ムガル朝インド（アクバル帝の工房）", "title": "フラグ・ハンの時代のアルビル攻め（ラシード・アッディーン『集史』のうち「チンギス・ナーマ」より）", "artist": "バサーワン／スール・ダース・グジャラーティー", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1947.502", "note": "城壁の門から黒い馬が一頭、矢筒を背負った騎手を乗せて出てくる。斜面の下は人と馬でびっしり埋まり、金の兜が並び、らくだの背では太鼓が打たれ、長い喇叭が二本、空へ向いている。中ほどの白い馬は青と金の馬衣をつけ、館の説明では、そこに乗るモンゴルの征服者が、負けた西アジアの相手を冷ややかに見下ろしているのだという。描かれているのは十三世紀のフラグ・ハンの時代の攻城で、絵が作られたのはその三百年あまりあと、ムガル朝アクバル帝の工房。館は作者としてバサーワンとスール・ダース・グジャラーティーの二人を挙げる。草原の騎馬の話は、ペルシア語の年代記を経て、インドで絵になった。"}, {"f": "uma08.jpg", "date": "1822年（江戸）", "place": "日本（江戸）", "title": "絵馬（『馬づくし』より）", "artist": "葛飾北斎", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/81627", "note": "屋根形の黒い枠のついた絵馬が二枚、立てかけてある。左の一枚には白い馬がいる——ふさふさした白いたてがみ、黒い目、鼻づらにかかる赤い端綱、背には赤と緑の派手な覆い。右の一枚は緑の小さな丸がびっしり並ぶだけで、馬はいない。上に「奉」「納」、下に「大願成就」と大きく入る。館はこれを北斎の連作『馬づくし』（1822年）のうちの「絵馬」と記録し、摺物（すりもの）の色紙判とする。絵馬は、生きた馬を社に奉じる代わりに掛けられるようになったものだとされる——ここでは、その代わりの馬すら丸の連なりに置き換わっているように見えるが、右の板が何を数えたのかは、この一枚からは分からない。"}, {"f": "uma09.jpg", "date": "いま", "place": "モンゴル（フスタイ国立公園）", "title": "尾根のモウコノウマ（タヒ）", "artist": "Chinneeb（写真）", "museum": "Wikimedia Commons", "lic": "CC BY 4.0", "url": "https://commons.wikimedia.org/wiki/File:Group_of_Takhi_at_Hustai.jpg", "note": "草の尾根に四頭。黄褐色の体、白っぽい鼻づら、黒い脚と尾、そして首の上に立ったままのたてがみ——前髪が額に垂れない。撮影は2011年6月、モンゴルのフスタイ（フスタイン・ヌルー）国立公園。モウコノウマは野生では二十世紀のうちにいちど姿を消し、飼育下に残っていた個体から繁殖させて、1990年代のはじめからこの一帯へ戻す試みが続いている。種として立てるか、ウマの亜種として扱うかは、いまも書き方が分かれている。八点の像を見てきた目でこれを見ると、轡も鞍も鈴も何ひとつ付いていないことのほうが、めずらしく見えてくる（そう思うのはこちら側だけれど）。"}]}, {"id": "kamoshika", "no": "第二十二景", "name": "羚羊", "yomi": "かもしか", "en": "Serow — one word for beasts on different branches", "rep": "kamoshika07.jpg", "lead": "羚羊。この二字は、日本ではカモシカと読み、英語の antelope の訳語にもなってきた。マリのバマナの人びとが「人に耕すことを教えた」と語る獣も、日本の山でひとり縄張りを守るニホンカモシカも、同じ二字で呼ばれる。並べてみると、獣より字のほうが、ずっと広く旅をしている。", "nature": [["「羚羊」は、ひとつの枝ではない", "アンテロープ（antelope）は、ウシ科の獣のうち、ウシ・ヒツジ・ヤギとは呼ばれないものをひとまとめにした呼び名で、系統のうえでひとまとまりの群ではない。たとえばアフリカのオリックスとインドのブラックバックは、同じ「アンテロープ」でありながら、ウシ科のなかの別々の亜科に置かれる。日本語の「羚羊」はその antelope の訳語であると同時に、日本のカモシカ（氈鹿とも書く）にあてられた字でもある。ところがニホンカモシカ（Capricornis crispus）はウシ科ヤギ亜科で、ヤギ・ヒツジ・シャモア、そしてアジアのゴーラルに近い枝にいる。つまりこの二字は、ウシ科のなかで別々に分かれていった枝を、まとめて指している。"], ["落とさない角、前が厚い体", "ウシ科の角は洞角（どうかく）と呼ばれ、頭骨から伸びた骨の芯を、爪と同じケラチンの鞘がおおう。いちど生えたら生涯落ちず、根元から少しずつ伸び足されていく——毎年落ちて生えかわり、枝分かれしていくシカ科の枝角とは、できかたがまるで違う。ニホンカモシカの角は雌雄ともにあり、後ろへ弓なりに曲がって、長さはおよそ10〜15センチ。肩の高さはおよそ70センチ、体重は30〜45キロほどとされ、脚は短く、体は前が厚い。日本の固有種で、国の特別天然記念物（1955年指定）。基本は単独で、目の下の腺（眼下腺）の分泌物を枝や岩にこすりつけて、自分の場所を告げる。"], ["耕すことを教えた獣（と、館は記す）", "マリのバマナの人びとに伝わるチワラ（chi wara）について、クリーブランド美術館は「農耕の獣」であり、人に耕すことを教えたと語られてきた、と説明する。冠のかたちは人とアンテロープとアリクイ（館の記載は anteater）の要素を合わせたもので、地上の獣ではなく農耕の精霊であることを示す、とも書かれている。男女ひと組の冠を、男性の踊り手が籠の帽子に留めてかぶり、女性たちの歌に合わせて、農作業の競い合いや婚礼で踊った——ここまでが館の記載である。チワラが何を意味してきたかは、研究と土地の語りのあいだで幅があり、こちらで一つに決めて書くことはできない。"]], "invite": "動物園でも図鑑でもいい、角のある獣に会ったら、角が枝分かれしているかどうかだけを見てみる。分かれていなければ、それは落とさない角——生まれてから一度も抜けていない、その一頭ぶんの時間である。", "works": [{"f": "kamoshika01.jpg", "date": "前664〜前610年ごろ（末期王朝）", "place": "エジプト（テーベ・デイル＝エル＝バハリ）", "title": "草を食む羚羊の下絵を描いた陶片（Ostracon with sketch of a grazing antelope）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/558427", "note": "縦十八センチ半、横九センチの石灰岩のかけらに、赤い線だけで一頭。頭を下げて地面の線に口をつけ、細い角が二本、背の上を後ろへ長く流れていく。所蔵館はこれを「草を食む羚羊の下絵」と題し、上エジプト・テーベのデイル＝エル＝バハリで、同館の1922〜23年の発掘によって出土したと記す。オストラコンは、割れた石や土器のかけらを紙のかわりに使ったもの——清書ではなく、手が動いたあとがそのまま残っている。"}, {"f": "kamoshika02.jpg", "date": "1115〜1234年（金）", "place": "中国（金）", "title": "月を仰ぐジェイランの錦（Brocade with Djeiran Gazing at the Moon）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1991.4", "note": "縦一メートル十センチの赤い絹に、金糸のドームのような文様がいくつも並ぶ。中はどれも同じで、獣が一頭伏せ、前脚を一本のばし、首をうしろへ返して上を見上げている。所蔵館の説明では、この獣はもともと中央アジアのアンテロープ〈ジェイラン〉で、600年代以降のソグドの銀器に現れ、交易路を通って中国北部へ渡り、金・元の時代にたいへん好まれたという。館はさらに、中国の書き手はこれを、月を見つめるという伝説の犀（犀牛）や「呉の牛、月を見て喘ぐ」の牛と重ねて記すことが多かった、と付け加えている——同じ一頭の姿が、渡った先では別の獣の名で呼ばれている。"}, {"f": "kamoshika03.jpg", "date": "1602〜04年ごろ", "place": "インド（ムガル朝・アラーハーバード）", "title": "羚羊と鹿の狩り（Antelope and deer hunt）", "artist": "ゴーヴァルダン", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1939.66", "note": "絵の部分は縦二十センチほど。緑の斜面いっぱいに獣が散り、まん中で、赤い首輪をしたチーターが、黒っぽい体にねじれた角をもつ一頭に食らいついている。所蔵館の説明では、ムガル朝では狩りに馴らしたチーターを使い、この獲物はブラックバックで、獲物をとらえる図は、父アクバルから帝位を奪おうとしたサリーム王子の望みに重なるという。まわりを走るのは、輪の刻みが並ぶ角の獣、角の小さな淡い一頭、青灰色の大きな獣、それに兎。いちばん下の一頭だけ、白い斑があり、角が枝分かれしている——枝角をもつ側、つまり鹿である。"}, {"f": "kamoshika04.jpg", "date": "1800年代", "place": "西アフリカ・ガーナ（アカン）", "title": "金の分銅（abrammuo）：羚羊（Gold Weight (abrammuo): Antelope）", "artist": "作者不詳（アカンの作り手）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1935.306", "note": "五センチほどの銅合金の獣。頭を下げ、四本の脚を踏んばり、体の長さほどもある角が、輪の刻みを並べたまま背の上へ跳ね上がっている。所蔵館の説明では、これは金の砂や粒を量るための分銅で、アサンテ王国では宮廷がもっとも凝った一式を持ち、庶民でも十いくつは持っていたという。館はまた、この長すぎる角は「知っていたなら」ということわざを指しているのかもしれない——角の長さと、あとから振り返れば何でも見えるという皮肉をかけた駄洒落だ——と書いている（「かもしれない」と留保しているのは館自身である）。"}, {"f": "kamoshika05.jpg", "date": "1800年代（19世紀）", "place": "西アフリカ・マリ南中部（バマナ）", "title": "チワラの冠（Ci wara headdress）", "artist": "バマナのヌム（鍛冶）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/711020", "note": "高さ七十六センチ。まっすぐな角が二本、天へ向かって伸び、そのつけ根で頭が深く下がり、細い耳が横へ立つ。首から下は三角の透かしの連なりで、脚のかたちだけが残り、肉はどこにも彫られていない。所蔵館は作り手を「バマナのヌム（鍛冶）」と記し、産地をマリ南中部、材は木と金属としている。角の直線と、うつむいた頭——この二つだけで走る獣の速さが立って見えるのはこちら側の読みだが、余計なものが一つも彫られていないのはたしかである。"}, {"f": "kamoshika06.jpg", "date": "1800年代後半〜1900年代はじめ", "place": "中部アフリカ・コンゴ民主共和国（スク）", "title": "兜のかたちの仮面（Mask (hemba)）", "artist": "作者不詳（スクの彫り手）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2010.450", "note": "高さ五十センチ、頭からすっぽりかぶる木の兜。白く塗った顔に細い目、口には歯が並び、後頭部には赤い帯と、三角を刻んだ帯。その天辺に、まっすぐな角を二本立て、長い耳を伏せた四つ足の獣が一頭、立っている。所蔵館の説明では、スクの兜形仮面は若者の成人の儀礼に使われ、亡くなった年長者の姿であり、狩りの成功や病の治癒、身を守るはたらきをもつとされる。館はその上の獣を「ガゼルかアンテロープのかたちの動物」と書き、種を一つに決めていない——決めないまま、ことわざや狩りの手柄と結びつけられる、と記している。"}, {"f": "kamoshika07.jpg", "date": "1900年代前半〜半ば", "place": "西アフリカ・マリ（バマナ）", "title": "チワラの冠（Headdress (chi wara)）", "artist": "作者不詳（バマナの鍛冶＝彫り手）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1965.325", "note": "幅六十六センチ、高さ四十四センチ半。細長い頭がまっすぐ前へ突き出し、そこから角が二本、大きく弧を描いて後ろへ流れ、胴は低くたわみ、尾の先がくるりと巻く。全面に細かな刻みが並び、口もとに白い子安貝と青い玉が下がっている——所蔵館は材に木・子安貝・ガラス玉・金属を挙げ、この作は輸入の金属とビーズによる耳飾りと鼻輪をつけている、彫ったのはバマコの南で広く行われた写実寄りの作風の鍛冶だ、と記す。館は、チワラは人に耕すことを教えたと語られた「農耕の獣」で、人とアンテロープとアリクイ（anteater）の要素を合わせた農耕の精霊だと説明する。ただし館は、形のまるで違うもう一点のチワラにも同じ解説文をあて、両方を「雌（female）」と記している——この記載は、幅をもって読むほうがよい。"}, {"f": "kamoshika08.jpg", "date": "1900年代前半〜半ば", "place": "西アフリカ・コートジボワール（セヌフォ）", "title": "兜のかたちの仮面（Helmet Mask）", "artist": "作者不詳（セヌフォの彫り手）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1972.336", "note": "長さ一メートル二十二センチ。開いた口に歯が並び、鼻先には短い角がいくつも突き出し、そのうしろから太い角が二本、水平に伸びて先が上へ反る。所蔵館の説明では、この一つの頭に、羊の角、イボイノシシの牙、ワニの口、ハイエナの鼻先が組み合わされ、長い羚羊の角のあいだには、小さなカメレオンと〈マンゲレ〉と呼ばれる翼のかたちが彫られているという。館は、この恐ろしい姿は妖術を退ける力にかかわる、と記す。ここでは羚羊の角は獣一頭ぶんではなく、別の獣たちと並ぶ一つの部品として使われている。"}, {"f": "kamoshika09.jpg", "date": "いま", "place": "日本（岩手県・金山棚田）", "title": "刈りあとの棚田に出たニホンカモシカ", "artist": "Indiana jo（写真）", "museum": "Wikimedia Commons", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File:Capricornis_crispus_in_Kanayama_rice_terraces.jpeg", "note": "稲を刈ったあとの株が並ぶ斜面に、灰白色の毛の獣が一頭立ち、まっすぐこちらを見ている。耳のあいだに、黒く短い角が二本。顔から胸は白っぽく、体は前が厚く、脚は短い——冠に彫られたあの細く長い脚と角とは、正反対の体つきである。撮影者の説明は「金山棚田に現れたカモシカ」の一行だけ、2023年11月3日、岩手県。八点の「羚羊」を見てきた目でこれを見ると、同じ二字が抱えこんできた幅が、そのまま出る。"}]}, {"id": "kujira", "no": "第二十三景", "name": "鯨", "yomi": "くじら", "en": "Whale — the animal almost nobody has seen whole", "rep": "kujira06.jpg", "lead": "鯨は、見えない大きさの獣である。丸ごとを一度に目にした人は、ほとんどいない。だから残された作品の多くは、浜に打ち上げられた死骸か、銛を打つ一瞬か、体の一部——歯・骨・鬚——でできている。", "nature": [["海へ戻った、肺で息をする獣", "鯨は魚ではなく、哺乳類である。祖先は陸にいて、そこから海へ戻ったとされる。だから肺で呼吸し、息のために水面へ上がってこなければならない。鼻の孔は頭の上へ移って噴気孔になり、潮吹きと呼ばれてきた——ヒゲクジラでは二つ、ハクジラでは一つ、というのが通例とされる。胸びれは前肢が変わったもので、外からは一枚の板に見えるが、中には指の骨が並んでいる。後肢は外へ出ず、骨盤のなごりの小さな骨が体の中に残るとされる。子は水中で産まれ、乳で育つ。この景の四点目に置いた一八二六年の日本の本が、胸びれに「手羽」、腹の一点に「乳」と名を振っているのは、そのままこの体の説明になっている。"], ["鬚でこす者と、歯でとらえる者", "鯨のなかまは、大きくヒゲクジラとハクジラの二つに分かれるとされる。ヒゲクジラは歯をもたず、上あごから鯨鬚（くじらひげ）と呼ばれる板が簾のように垂れ、海水ごと口に入れて小さな生きものをこしとる。この板は骨ではなく、爪や髪と同じケラチンでできている。ハクジラは歯をもち、獲物をとらえる。マッコウクジラも、イルカも、シャチもこちら側である（「クジラ」と「イルカ」の呼び分けは、おおむね大きさによる慣習で、分類の線ではないとされる）。並べた作品を見ると、この体の違いが、そのまま作られたものの違いになっている。装身具や像になったのは歯——つまりハクジラの体。太鼓の枠や道具になったのは骨。ヨーロッパでコルセットや傘の骨に使われたのはヒゲクジラの鬚で、英語では whalebone（鯨の骨）と呼ばれたが、骨ではない。"], ["声——ただし、まだ録っていない", "鯨のなかまは音をよく使う。ハクジラは高い音を出し、その反響で周りを探る（エコーロケーション）。ヒゲクジラの出す音には非常に低いものがあり、水の中を遠くまで届くとされる。ザトウクジラの雄がうたう、長い繰り返しをもつ「歌」もよく知られている。——ここまでは、本で読んだことである。この声を、いま手元にある機材で録れるかどうかは、試していないので分からない。水中マイクを持っていないし、低い音をどこまで落とさずに記録できるかも確かめていない。だからこの景は、鯨の声を聴かせない。持っていない耳のことを、持っているように書かないでおく。"]], "invite": "両腕をいっぱいに広げた長さを、一尋（ひろ）という。江戸の本は、鯨の大きさをこの一尋で数えた。自分の一尋を測って、それを十五回ぶん、地面に並べて歩いてみる。丸ごとを一度に見られない生きものの輪郭が、足の裏にだけ残る。", "works": [{"f": "kujira01.jpg", "date": "1598年", "place": "オランダ（カトウェイク近くの浜）", "title": "カトウェイク近くの浜に打ち上げられたマッコウクジラ（A Sperm Whale Beached near Katwijk）", "artist": "ヤコブ・マータム（ヘンドリク・ホルツィウス下絵）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/266995", "note": "紙は縦三十二センチ、横四十三センチほどの銅版画。浜に横たわる一頭を、人がぐるりと取り囲んでいる。背に乗って道具を振り上げる男、馬でやって来た一行、襞襟の女たち、樽を運ぶ子ども。頭では下顎に円錐形の歯が一列に並び、上顎にはそれを受ける窪みが点々と並ぶ——マッコウクジラは歯が下顎だけにあるとされ、彫られた線はその通りになっている。左端では胸びれと尾びれが砂の上に落ちている。所蔵館は右下の刻銘「Ao. 1598. I. Matham sculp.」と、下段に組まれたラテン語とオランダ語の詩を記録している。これほど細かく丸ごとが描けたのは、この鯨が死んでいたからである。"}, {"f": "kujira02.jpg", "date": "1700年代（18世紀）", "place": "南太平洋・タヒチ／オーストラル諸島（マオヒ）", "title": "タヒリ ── はえ払いの柄（Tahiri (handle for a fly whisk)）", "artist": "作者不詳（マオヒの作り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/311336", "note": "長さ二十九センチ八ミリ。頭のところに小さな像が向かい合わせに彫られ、そのあいだを弧が渡る。柄は透かし彫りで、丸い穴と、輪と柱を組んだような格子が下へ続き、先は細く尖る。数か所に茶色い紐が巻きついている——所蔵館は材を「鯨の歯（whale ivory）とココヤシの繊維」と記す。種は書かれていない。獣の姿はどこにもない。ここにあるのは、鯨の体のいちばん硬い一部を、手で持てる長さに切り分けたものである。"}, {"f": "kujira03.jpg", "date": "1800年代はじめ（19世紀初）", "place": "南太平洋・トンガ（ハアパイ諸島）", "title": "オトゥア・フェフィネ ── 神像（'Otua fefine (deity figure)）", "artist": "作者不詳（ハアパイ諸島の作り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/313658", "note": "高さ十三センチ三ミリ。手のひらに載る立像で、頭が体に対して大きく、腕は肘から先が下へ垂れ、指は彫られていない。足の指だけが細かく刻まれている。所蔵館は材を「鯨の歯」とだけ記し、題を「'Otua fefine（神像）」、産地をトンガのハアパイ諸島とする。歯の内側の年輪のような縞が、そのまま腿と腹の面に出ている——材が生きていた時間が、像の肌になっている。"}, {"f": "kujira04.jpg", "date": "1826年（文政9）", "place": "日本（江戸）", "title": "除蝗録（Whales and Whale Oil (Jokō roku)）", "artist": "長谷川雪旦", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/78696", "note": "縦二十二センチ八ミリの木版の本を、見開きで撮ったもの。上半分は海辺の遠景で、小さな舟が列をつくる。下半分は鯨の図で、体の各部に名が振ってある——「潮吹」「口」「手羽」「尾羽毛」、右の頁には「鯨鬚」「乳」。喉から腹へ何本もの縦の筋が引かれ、左の頁の一頭には「長須鯨（ながすくじら）十五尋之図」と読める文字が添う。尋は両腕を左右に広げた長さで、鯨の大きさをその十五倍として数えている。「除蝗」は虫の害を除くこと。江戸後期の農書には、水田の面に油を注いで稲につく虫を落とす方法が書かれ、その油に鯨の油が用いられたことが知られる。所蔵館はこの本に「鯨と鯨油」という英題をあて、絵師を長谷川雪旦、年を一八二六年（文政九）と記す（著者名は記していない）。海の獣が、田の水面まで来ている。"}, {"f": "kujira05.jpg", "date": "1830〜60年", "place": "北アメリカ・アラスカ（イヌイット）", "title": "鯨（Whale）", "artist": "作者不詳（イヌイットの彫り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/312731", "note": "長さ七センチ三ミリ、高さ二センチ二ミリ。手のひらに収まる鯨が一頭。丸い頭、小さな目、脇に短い胸びれ、尾は左右に開いた尾びれになる。そしてその脇腹に、線だけで帆船が刻まれている——舷側に沿って四人が立ち、帽子をかぶり、マストと索が斜めに走り、船縁の下には細かい斜線が並ぶ。所蔵館の記載は、題「Whale」、文化「イヌイット」、材「セイウチの牙」、年代一八三〇〜六〇年、国はアメリカ、それだけである。刻まれた船が何の船かも、誰が彫ったかも書かれていない。鯨の形をした牙の上に、船が一隻乗っている——そう見えるかどうかは、こちら側の読みである。"}, {"f": "kujira06.jpg", "date": "1859年（安政6）", "place": "日本・肥前（五島列島）", "title": "諸国名所百景 肥前五嶋鯨漁の図", "artist": "二代歌川広重", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/196846", "note": "縦長の錦絵。画面のまんなかで、黒い三角が水から立ち上がる——持ち上げられた尾びれである。その根もとで背が波を割り、白い泡が高く跳ねる。見えているのはそれだけで、頭も胴も水の下にある。まわりには舳先の反った舟が何艘も並び、旗を立て、櫓を漕ぐ人がぎっしり乗る。手前の一艘では、腰に布を巻いた男が舳先に立ち、銛を振りかぶっている。もう一本の銛は、画面の左で水に刺さったままである。題の枠には「肥前 五嶋 鯨漁の図」、上の帯には「諸國名所百景」。五島は近世の捕鯨の地として知られる。"}, {"f": "kujira07.jpg", "date": "1800年代（19世紀）", "place": "南太平洋・フィジー", "title": "チヴァヴォノヴォノ ── 胸飾り（Civavonovono (breastplate)）", "artist": "作者不詳（フィジーの作り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/311188", "note": "幅十九センチ四ミリほどの円い胸飾り。まん中に黒蝶貝の円盤を据え、そのまわりを、弧に切り出した象牙色の板が四枚、輪になって囲む。上の一枚だけが太く、山なりに立つ。外の縁には細かい三角が鋸の歯のように一周ぐるりと刻まれ、中央には十字の小さな部品が留めてある。所蔵館は材を「鯨の歯、黒蝶貝（civa）、繊維」と記し、作り手を「フィジーの作り手」とする。四枚の弧はどれも同じ向きに曲がっている——それはもともと、あごに生えていたときの曲がりである。"}, {"f": "kujira08.jpg", "date": "1800年代後半（19世紀後半）", "place": "北極圏・グリーンランド（イヌイット）", "title": "ケリャウト ── 枠太鼓（Kelyaut / Qilaut (frame drum)）", "artist": "作者不詳（イヌイットの作り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/501283", "note": "差し渡し二十二センチほどの楕円の枠太鼓を、表と裏から撮った一枚。表は張られた皮で、裏へ回ると、細い枠と、それを留めた紐が見える。柄は平たい一片で、丸い留め具が二つ並ぶ。所蔵館は材を「鯨の骨、皮」と記し、名を「Kelyaut あるいは Qilaut（枠太鼓）」、産地をグリーンランド・北極圏、一八八九年に同館へ入った楽器コレクションの一点とする。皮が何の皮かは書かれていない。ここでは骨は道具ではなく、音の枠になっている——鯨の体の一部が、人の側の音を出すための輪郭になった。"}, {"f": "kujira09.jpg", "date": "いま", "place": "北アメリカ・アメリカ合衆国カリフォルニア沖（チャネル諸島国立海洋保護区）", "title": "空から見たシロナガスクジラ二頭（写真）", "artist": "National Marine Sanctuaries（NOAA）", "museum": "Wikimedia Commons", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:CINMS_-_BlueWhales_(30550423643).jpg", "note": "濃い青緑の海に、二頭。手前の一頭は水面に背を出し、頭のあたりから白い噴気が斜めに流れる。頭の先から尾びれまで、体の輪郭がまるごと一枚に収まっている。奥の一頭は水の下にいて、緑がかった細長い帯としてしか見えない——同じ二頭が、深さのわずかな違いだけで、見える側と見えない側に分かれている。撮影は二〇一六年十月十二日、カリフォルニア沖のチャネル諸島国立海洋保護区。船の航路と鯨の採餌域が重なるために続けられている航空調査の一枚で、撮影元の説明はこの日の調査でシロナガスクジラ十一頭とザトウクジラ二頭を数えたと記す。シロナガスクジラは現生でもっとも大きな動物とされる。八点の「一部」を見てきたあとで、はじめて丸ごとが一枚に入る——ただしそれは、空へ上がってからのことである。"}]}, {"id": "same", "no": "第二十四景", "name": "鮫", "yomi": "さめ", "en": "Shark — the fish whose skin is made of teeth", "rep": "same01.jpg", "lead": "鮫は、骨のかわりに軟骨でできた魚である。歯は列をなして生えかわり、皮は歯と同じつくりの粒でおおわれる。――少なくともこの九点は、姿ではなく歯と皮の側から鮫に触れている。", "nature": [["軟骨の骨格、送り出される歯", "サメは軟骨魚のなかまで、骨格の大部分が骨ではなく軟骨でできているとされる。同じなかまにエイとギンザメが入る。硬骨魚のような鰓蓋（えらぶた）を持たず、鰓裂（さいれつ）が体の外へ直接ひらく――多くは五対、種によっては六対・七対のものもいるとされる。歯は骨の穴に植わっているのではなく、あごをおおう膜に何列も並び、外側の歯が抜けると内側の列が前へ送り出されて入れかわる、と説明される。だから残るのは、たいてい歯のほうである。軟骨は骨より残りにくい。現生のサメはおよそ五百種を超えるとされ、二十センチほどのものから、現生最大の魚とされるジンベエザメまで幅がある。"], ["鼻先の孔で、電気を感じる", "吻（ふん）のまわりに、小さな孔が点々と並ぶ種がある。孔の下にはゼリー状のもので満たされた管が伸び、奥の感覚細胞につながっている。ロレンチーニ器官（ロレンチーニ瓶）と呼ばれるこの仕組みは、ごく弱い電場を感じ取るとされる。名は、一六七八年にこの構造を記載したステファノ・ロレンチーニに由来する。生きものの筋肉や心臓は動くたびに微弱な電気を生むので、砂の下にひそむものも、目に頼らずに探れる――そう説明される。ただし mitsulab は、この器官の働きを自分で測ったことがない。ここに書いたのは、本で読んだことである。"], ["皮が、歯でできている ── そして名前は混ざる", "サメの体をおおう鱗は楯鱗（じゅんりん）、または皮歯（ひし）と呼ばれ、口の中の歯と同じつくり（象牙質の芯を硬い層がおおい、内に髄が通る）をしているとされる。だから逆なでするとざらつき、古くから研ぎ・磨きの道具になってきた。ここで名前の話になる。日本語の「鮫」は、生物学の分類とぴったりは重ならない。刀の柄や鞘に巻く「鮫皮」は、その多くがエイの皮である。この景の四点目に、メトロポリタン美術館は Decorated \"Shark\" Skin と、Shark に引用符を付けた題を与え、材は rayskin（same）と書いている。サメもエイも同じ軟骨魚で、どちらも皮歯を持つ。呼び名が先に混ざったのは手ざわりが似ているからだろう――と読むのは、こちら側である。"]], "invite": "ビロードか別珍、コーデュロイのような毛羽のある布を、指の腹で二方向になでてみる。片側は滑り、片側は毛が起きて引っかかる。向きのあるざらつきを、鮫は全身にまとっている。", "works": [{"f": "same01.jpg", "date": "1〜400年ごろ", "place": "南アメリカ・ペルー（ナスカ）", "title": "鮫の描かれた双口壺（Double-spout bottle with shark）", "artist": "ナスカの作り手", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/308571", "note": "高さも幅も奥行きも十七センチほどの丸い壺。上に短い注ぎ口が二本立ち、あいだを橋のような把手が渡す。胴には黒と橙で一頭の生きものが横向きに描かれる。大きく開いた口の中に稲妻形の歯が並び、白い丸に黒い瞳の目があり、体には黒い点を連ねた帯が走り、尾は二股に割れる。腹からは格子を刻んだ手のようなものが伸びる。館はこれを「鮫の描かれた」壺と題するが、同じ館の分類語には Whales（鯨）が入っている。館の記載そのものが揺れている。"}, {"f": "same02.jpg", "date": "16世紀後半", "place": "南アジア・南インド（ヴィジャヤナガル）", "title": "鞘つき短剣・カタール（Dagger (Katar) with Sheath）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/31541", "note": "鞘を含めた長さ七十七センチ五ミリ。握りに横棒を二本渡し、腕に沿って突き出す型の短剣である。鋼の面には金で小さな星が一面に散り、縁を唐草が回る。鞘は革で、上半分に透かし彫りの金具がかぶさる。その鞘の縁から、淡い色の三角形が外へ向いて張り出す――この一枚では左右と左下に、少なくとも三枚数えられる。左のものは乳白、右のものは飴色で、色はそろっていない。館は材を「鋼、銀、金、革、鮫の歯」と記す。歯がどこに付くかまでは書かれていないので、この三角をそれと見るのはこちら側の読みである。"}, {"f": "same03.jpg", "date": "18〜19世紀", "place": "中国", "title": "鞘つき小刀（Knife with Sheath）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/31565", "note": "鞘を含めて長さ二十九センチ二ミリ。柄は淡い緑の玉（ぎょく）、刃は片刃で先が尖る。見どころは鞘のほうで、上下を金色の透かし金具にはさまれた胴が、緑に染めた粒だらけの皮でおおわれている。粒は円く、大小が入りまじる。館は材を「鋼、玉、鮫皮、真鍮、金」と記す。この粒は、口の中の歯と同じつくりの皮歯だとされる――その一つ一つが、緑の地に白く抜けて読めるのがこの一枚である。"}, {"f": "same04.jpg", "date": "1800〜1850年ごろ", "place": "日本", "title": "飾鮫（Decorated \"Shark\" Skin (Kazari-zame)）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/32829", "note": "長さ五十二センチ、幅九センチ五ミリ、厚み七センチ五ミリ。木を芯に錦と金で包み、ところどころ窓を切って下の皮を見せている。窓は上から、しずく形・菱形・細長い長方形・扇形・楕円。中央の長い窓では粒の大きさが場所で変わり、上のほうに大粒がひとかたまり寄って、下へ行くほど細かくなる。館は題の Shark に引用符を付け、材を rayskin（same）と記す。鮫の名で呼ばれてきた、エイの皮である。"}, {"f": "same05.jpg", "date": "1800年代（拵）／刀身は1333年", "place": "日本", "title": "短刀の刀身と拵（Blade and Mounting for a Dagger (Tantō)）", "artist": "宇多国光（Uda Kunimitsu・刀身）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/26571", "note": "全長四十四センチ七ミリ、刃の長さ三十センチ四ミリ。上に鞘と柄、下に外した刀身を並べた一枚。鞘の表は、細かい粒が斜めの網目に並んだ肌で、等間隔の輪の区切りが入る。藍と白の組紐（下緒）は鞘の側の金具（栗形）に結ばれ、柄のほうは黒く巻かれている。館は年を「刀身は一三三三年十一月、拵は十九世紀」とし、材に「ray skin（samé）＝エイの皮」と「shark skin」を別々に並べる――どの部分がどちらかは書いていない。六百年へだてた二つの時代が、一本の中で組み合わさっている。"}, {"f": "same06.jpg", "date": "1800年代（19世紀）", "place": "オセアニア・ハワイ諸島", "title": "パフ・フラ ── 太鼓（Pahu Hula (drum)）", "artist": "作者不詳（ハワイの作り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/501417", "note": "高さ四十五センチ七ミリ、差し渡し二十七センチ九ミリ。ヤシの木をくりぬいた筒に皮を張り、細い縄を縦へ何本も掛けて胴に締めつけてある。胴の下は透かし彫りで、弧を描く脚が二段に並ぶ。館は材を「ヤシ材、鮫皮」と記す。ここでの鮫の皮は、ざらつきを使うためではなく、張って鳴らすために使われている。館の写真は古く暗いので、皮の粒までは見えない。"}, {"f": "same07.jpg", "date": "1800年代（19世紀）", "place": "アフリカ（東アフリカ）", "title": "竪琴（Lyre）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/502679", "note": "高さ百十三センチ、幅五十八センチ。丸い共鳴胴に獣の皮を張り、そこからレイヨウの角を二本、腕のように立てて、上に横木を渡し弦を張る。弦は九本ほど数えられる。胴の下寄り、弦が渡るあたりに、淡い三角が重なりあって横の帯をなす。館は材を「べっ甲、レイヨウの角、獣皮、鮫の歯、麻の弦」と記す。歯の位置までは書かれていないが、この帯をそれと見るのが素直だろう。筆頭に挙がるべっ甲がどこに使われているかは、この写真からは分からない。古い白黒写真なので、色は分からない。"}, {"f": "same08.jpg", "date": "1900年ごろ", "place": "南太平洋・ソロモン諸島", "title": "鮫の容れもの（Shark Reliquary）", "artist": "ソロモン諸島の作り手", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/762069", "note": "長さ百七十センチ二ミリ、高さ二十七センチ三ミリ。黒く塗った木彫の魚で、左端は深く割れた尾、右端は細く長く突き出した顎、その顎が上下に割れて口がひらく。背と腹には三角を連ねた鋸歯の稜が走り、体の横には半月形の貝が点々と入る。胴を二本の帯が巻き、山形の文様が刻まれる。背びれの縁には白い三角が並び、胸びれの縁は白木のまま淡く残る。館は題を Shark Reliquary、材を「木、貝、顔料」と記す。顎の細長さは実際の鮫の頭とは違うが、種の断定はしない。"}, {"f": "same09.jpg", "date": "いま", "place": "オセアニア・太平洋（ライン諸島の環礁）", "title": "ツマグロ（写真）", "artist": "Ryan Hagerty（アメリカ魚類野生生物局）", "museum": "Wikimedia Commons", "lic": "パブリックドメイン（米国魚類野生生物局の職務著作）", "url": "https://commons.wikimedia.org/wiki/File:Blacktip_reef_shark_at_Palmyra_Atoll_(52979104628).jpg", "note": "二〇二三年四月十二日、パルミラ環礁国立野生生物保護区（撮影元の説明では「ハワイの約千マイル南」）で撮られた一枚。珊瑚の海底の上を、一頭が横切っていく。背びれの先が黒く、尾びれの下の葉の先も黒い。頭のうしろには斜めの切れ込みが並ぶ――鰓裂で、この一枚では四、五本まで数えられる。撮影元はツマグロの体長を五〜六フィート（およそ一・五〜一・八メートル）と記す。八点の歯と皮を見てきたあとで、ようやく、それがまだ体についている姿が出てくる。"}]}, {"id": "kuma", "no": "第二十五景", "name": "熊", "yomi": "くま", "en": "Bear — the beast that stands upright, and the parts people made it play", "rep": "kuma02.jpg", "lead": "熊は四本足で歩くが、足の裏を踵まで地につける。ときには後ろ足で立ち上がる。人に似た形をもつこの獣を、人は神ともし、鎖にもつないだ。残された作品の多くは、熊そのものではなく、人が熊に負わせた役のほうを映している。", "nature": [["三つの熊 ── ヒグマ・ツキノワグマ・ホッキョクグマ", "クマ科の現生種は、世界におよそ八種とされる。日本にいるのは二種で、北海道のヒグマ（Ursus arctos）と、本州・四国のツキノワグマ（Ursus thibetanus）である。ヒグマは北半球に広く分布し、北アメリカでグリズリーと呼ばれるものも同じ種とされる。肩に筋肉の盛り上がりがあり、体は大きい。ツキノワグマは胸に三日月形の白い斑をもつものが多く、これが名の由来とされる。ホッキョクグマ（Ursus maritimus）はヒグマから分かれたと考えられており、毛は白く見えるが皮膚は黒いとされる。三種に共通するのは歩き方で、指先だけで立つ犬や猫とちがい、熊は踵まで地につけて歩く（蹠行）。人と同じ歩き方である。だから熊の足跡は、人の足跡に似る。"], ["冬ごもりを「冬眠」と呼ぶかどうか", "熊は冬のあいだ、穴にこもって過ごす。ただしこれを冬眠と呼ぶかどうかは、長く揺れてきた。ジリスやシマリス、ヤマネのような典型的な冬眠動物は、体温が外気の近くまで下がり、途中で何度も目を覚ます。熊はそこまで下がらない。アメリカクロクマを冬のあいだ連続して測った研究では、体温の低下は五、六度ほどにとどまり、いっぽうで代謝は平常のおよそ四分の一まで落ちた。体温の下がり方だけでは説明のつかない落ち方である。熊は数か月ものあいだ食べず、飲まず、ほとんど排泄しない。雌はそのさなかに子を産み、乳を与える。体温が下がらないのだから冬眠ではない、という言い方も、これほど完成した冬ごもりはない、という言い方も、どちらも使われてきた。呼び名が定まらないのは、熊がすでにある枠に収まらないからである。"], ["食肉目の、ほとんど草食の獣", "熊は分類のうえでは食肉目（ネコ目）に属する。牙も爪もある。それでもヒグマとツキノワグマが実際に食べているものの大半は、草・木の芽・果実・ドングリやブナの実、そして昆虫である。秋に木の実が不作だと、人里まで下りてくる。肉に大きく寄っているのはホッキョクグマで、海氷の上でアザラシを獲る。果実を丸ごと食べる熊は、種子を糞とともに離れた場所へ落とす。日本でも、ツキノワグマがヤマザクラの実を食べ、その糞から種子が運ばれることを追った研究がある。──ここまでは、本と論文で読んだことである。こちらは熊の糞を追ったことがないし、運ばれた種が芽を出すところも見ていない。見ていないことは、見たようには書かないでおく。"]], "invite": "秋の道でドングリを一つ拾い、掌に載せてみる。ヒグマもツキノワグマも、冬ごもりの前に食べているのは、たいていこういうものである。", "works": [{"f": "kuma01.jpg", "date": "前664〜前332年", "place": "エジプト", "title": "うずくまる熊のアミュレット（Amulet of a Crouching Bear）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1998.27", "note": "高さ三センチ八ミリ。濃い緑の石に白い斑が散る緑斑岩を彫った小さな像で、後ろ足を折って円い台に坐り、首を前へ垂れている。耳は小さく尖って立ち、鼻先は短く、首のうしろに皺が寄る。館はこれを「うずくまる熊」と呼び、熊はエジプトの在来の獣ではないと記す。紀元前二四〇〇年ごろから、墓や神殿の壁の「外から来た貢ぎ物」の列にときおり現れる獣であって、丸彫りの熊はきわめて珍しいという。手のひらに載る大きさの、遠くから来た獣である。"}, {"f": "kuma02.jpg", "date": "前202〜9年", "place": "中国", "title": "熊のかたちの鎮子（Mat Weight in the Form of a Bear）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1994.203", "note": "高さ十五センチ七ミリ、幅十四センチ六ミリ、奥行き十七センチ三ミリの金銅。後ろ足を折って坐り、前足を体の前に置く。耳は左右に丸く張り出し、口を大きく開け、足の指が丸く並ぶ。金の被膜が剥げたところから青緑の錆が出ている。館はこれを敷物を押さえる鎮子とみて、熊の像は漢代に好まれ、勇ましい力の比喩だったと記す。同じ格好の小さな熊は器の脚にもよく使われたという。重さで押さえる道具に、いちばん重そうな獣の形を与えている。"}, {"f": "kuma03.jpg", "date": "200年代（3世紀）", "place": "イタリア（ローマ）", "title": "踊る熊のかたちの油壺（Oil Ampulla in the Form of a Dancing Bear）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1972.102", "note": "高さ十四センチ六ミリの青銅。熊が後ろ足で坐り、前足を左右に上げ、口を大きく開けている。首には首輪がはまり、その左右に環が一つずつ付く。館は、鎖を通して吊るすための環で、頭は首輪のうしろで蝶番になって蓋のように開き、下あごが注ぎ口になると記す。目には空気抜きの孔が開けてあった。浴場へ油を運ぶ器だったろうという。前足を上げたこの姿を、館は「踊る」姿勢と呼び、古代には熊も見世物にされ、この姿勢がそれを示すと書く。首輪と環は、その踊りが誰のためのものかを黙って裏づけている。"}, {"f": "kuma04.jpg", "date": "1560年ごろ", "place": "インド（ムガル朝・アクバル帝の宮廷）", "title": "金細工師の裁き、大工に我が子のように仕込まれた熊の子 ── 『トゥーティー・ナーマ（鸚鵡の物語）』第三夜より", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1962.279.23.a", "note": "絵の部分は十センチ二ミリ角ほど、紙全体で縦二十センチ。下に五行のペルシア語が組まれる。画面のなかほど、紫の衣の男の足もとで、黒い毛の熊が二頭、頭を男の体へこすりつけている（館は「袖にすり寄る」と書く）。左上の東屋では男たちと女・子どもが食事をしている。館の解説によれば、金細工師に盗まれた大工が仕返しに相手の息子二人をさらい、代わりに熊の子を置いた。熊がすり寄るのを、裁きの場は「姿を変えられた子ども」の証しと受け取る。熊は、人の子の代わりに立たされている。"}, {"f": "kuma05.jpg", "date": "1650〜75年", "place": "オランダ", "title": "ライネケ狐 ── 狐、熊に蜜を約束する（Reynard the Fox: Reynard Promises Honey to the Bear）", "artist": "アラールト・ファン・エーフェルディンゲン", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1982.179.9", "note": "銅版画。画面の左半分を、毛の長い熊が占める。頭を深く下げ、鼻先を地面すれすれまで下ろしている。画面の左下には倒れた丸太が一本あるが、鼻先はそこには届いていない。足は四本とも地についていて、逃げる構えではない。右手の藪からは、尖った耳の頭が三つ並んで熊のほうを向く。中世からヨーロッパで語り継がれた狐の物語では、蜜を約束された熊が木の裂け目に鼻を突っ込み、支えの楔を抜かれて挟まれる、と語られる。この一枚は、まだ挟まれる前の姿と読める。館の記載は題と作者と技法のみで、寸法も場面の説明もない。"}, {"f": "kuma06.jpg", "date": "18世紀", "place": "日本", "title": "熊と戦う金太郎の幟（Banner Depicting Kintaro Battling Bears）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/207204", "note": "縦百六十四センチ、横七十六センチ。木版で刷って手で彩色した幟で、布の折り目が縦横に走っている。子どもが右手に鉞を振り上げ、赤い腹掛けには「金」の一字。足もとでは黒い熊が一頭、仰向けにされて、まるい目で上を見ている。もう一頭は右上から体をひねって覗きこむ。左上には松。館は題を「熊と戦う金太郎の幟」、十八世紀の日本の作とする。この幟がどこにどう立てられたかは、館の記載にはない。"}, {"f": "kuma07.jpg", "date": "1820〜1900年", "place": "中国", "title": "松の下の鷹と熊を彫った嗅ぎ煙草入れ（Snuff Bottle with a Hawk and a Bear beneath a Pine Tree）", "artist": "作者不詳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/18007", "note": "高さ五センチ二ミリ、幅四センチ五ミリ、厚み二センチ七ミリ。翡翠を彫った嗅ぎ煙草入れで、濃い緑と淡い緑がまだらに流れる。石の色の流れが、獣と鳥の位置に重なって見える（そう見えるのはこちら側）。栓は紅い石に見える。胴の下半分に四足の獣が一頭、口を開け、たてがみのような巻き毛をなびかせて左を向く。右上には翼をたたんだ鳥、左上には円くまとまった松の葉。館の記載は題と材と年代だけで、解説はない。館はこの獣を熊と呼ぶが、彫りだけを見て種を決められる形ではない。"}, {"f": "kuma08.jpg", "date": "1902年", "place": "イギリス", "title": "みそさざいと熊（The Wren and the Bear）", "artist": "アーサー・ラッカム", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1946.8", "note": "紙は縦三十六センチ七ミリ、横二十五センチ八ミリ。獣と鳥はすべて黒く塗り潰した影絵で、雲だけが細い線で描かれる。上半分は群れて飛ぶ鳥と、粒のような虫の帯。下半分は地の獣で、鼻を上げた象、毛の長い四足、走る亀、右下に尾の太い獣がいる。下端の手書きに題と、一九〇六年ミラノ万国博覧会で金牌を受けた旨が添う。館は、グリム童話「みそさざいと熊」──熊が鳥の王を侮り、空の軍と地の軍が戦う話──の一場面で、豪華版のための影絵挿絵だと記す。どの影が熊なのかは、輪郭だけからは決めきれない。"}, {"f": "kuma09.jpg", "date": "いま", "place": "北極圏・アラスカ（北極圏国立野生生物保護区）", "title": "ボーフォート海の浜のホッキョクグマ母子", "artist": "Susanne Miller／アメリカ魚類野生生物局（写真）", "museum": "Wikimedia Commons", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:Polar_bear_with_young_-_ANWR.jpg", "note": "砂利の浜に、ホッキョクグマが三頭。まん中の大きな一頭が正面を向き、左右に一回り小さな二頭が寄り添う。毛は白というより生成りで、鼻先と目と爪だけが黒い。撮影元の説明は、ボーフォート海の海岸沿い、北極圏国立野生生物保護区で、母熊が子のそばを離れずにいるところ、と記す。撮影は二〇〇七年三月六日。八点はどれも人の手が形を与えたものだった。最後の一枚だけ、形を与えたのは人ではない——と言いたくなるが、切り取ったのはやはり人である。ただし氷ではなく陸にいるこの一枚が何を意味するのかは、写真一枚からは決められない。"}]}, {"id": "washi", "no": "第二十六景", "name": "鷲", "yomi": "わし", "en": "Eagle — the raptor people learned to carry on the arm", "rep": "washi04.jpg", "lead": "鷲は、人が見上げる鳥であり、人を見下ろす鳥でもある。古い作品では、翼をひろげた姿がくりかえし金にうつされた。やがて人は、この鳥を腕に載せて放ち、戻らせることを覚えた。", "nature": [["ワシとタカのあいだに、線はない", "ワシもタカもトビもハゲワシも、その多くはタカ目という一つのまとまりに入るとされる。そのなかで「ワシ」と「タカ」を分けているのは、おおむね大きさによる呼び分けの慣習で、分類の線ではない。日本語の鷲と鷹、英語の eagle と hawk も、きれいには重ならない。さらに近年のゲノムの研究では、ハヤブサはタカ目とは別の系統で、むしろインコやスズメの仲間に近いとされるようになった。鉤形のくちばし、獲物を握る足、鋭い爪——猛禽らしい形のなかには、別々の枝で似たようになったものが混じっている。人が「猛禽」と呼んでひとまとめにしてきたものは、生きものの系図の上では一本にまとまっていない。この景に並べた九点も、種を名乗っているものは少ない。"], ["「よく見える」の中身", "猛禽の目は大きく、頭の前を向いている。網膜には、光を細かく受けとる細胞が密に集まった窪み（中心窩）があり、片方の目に二つ持つとされる。深いほうは頭の軸から四十五度ほど横を、浅いほうは十五度ほど前を向き、深いほうが解像は高いとされる。遠くを横目で見つけ、近づいてから前で捉える、という順になると考えられている。視力そのものは、測られた例では人のおよそ二倍とされる（オーストラリアのオナガイヌワシ Aquila audax での測定）。「人の八倍」という言い方が広まっているが、その数字のはっきりした根拠には行き当たらなかった。二倍でも、じゅうぶん遠い。そして、どれだけ見えているのかを、こちらの手元の機材で測ることはできない。"], ["巣は積み上がり、狩りは受け継がれる", "大型の猛禽は、切り立った岩棚や大木に巣をかけ、前の年の巣に材を足しながら使いつづけることがある。イヌワシの卵は一つから三つほどで、二つのことが多く、そのうち巣立つのは一羽であることが多いとされる（必ず一羽だけかどうかは、資料によって書きぶりに幅がある）。一度数が減ると、戻るのに時間がかかる理由のひとつがここにある。いっぽう人の側は、この鳥を捕らえ、餌で結び、放って戻らせる技を積み上げてきた。起源の場所と時期には諸説あるが、中央アジアから西アジアにかけての一帯で古くから行われてきたとされる。イヌワシを使う猟はいまもモンゴルやカザフスタンで続いており、鷹狩は二〇一〇年にユネスコの無形文化遺産に記載され、二〇二一年の拡張でその二国を含む二十四か国の共同のものになっている。この景の最後の一枚は、その現場で撮られた写真である。"]], "invite": "空に大きな鳥を見つけたら、羽ばたきの数を数えてみる。タカ目の鳥は翼を広げたまま長く滑ることがあり、十数えるあいだ一度も羽ばたかない、ということが起こる。羽ばたかない時間の長さは、その空に上へ向かう空気があることの、ひとつの手がかりになる。", "works": [{"f": "washi01.jpg", "date": "前2250〜前1750年ごろ", "place": "中央アジア（バクトリア＝マルギアナ、または東イラン）", "title": "猛禽（Bird of prey）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/327324", "note": "高さ三センチ二ミリ、幅三センチ八ミリ。手のひらに載る小ささである。正面を向いた鳥が、翼を左右へまっすぐ伸ばしている。眼は青と白の同心の輪で、館は材を「大理石、方解石、銅合金、ラピスラズリ」と記す。両肩には金属の細い軸と輪が立ち、何かを留めていたように見える。館の記載は題を「猛禽」、産地を「バクトリア＝マルギアナ、または東イラン」とするだけで、種は書かれていない。翼を広げた形だけが、四千年ぶんの時間をこえて残っている。"}, {"f": "washi02.jpg", "date": "前8〜前7世紀", "place": "イラン", "title": "猛禽と有翼獣の飾板（Plaque with a bird of prey and winged beasts）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/327233", "note": "縦十三センチ、横二十二センチ五ミリの金の板。両端が尖り、片側が深く切れ込んだ形で、縁には小さな孔が点々と並ぶ——何かに留めつけてあったらしい。中央に大きな鳥が一羽。長い翼を伸ばし、胸には鱗のような羽が並び、尾が扇に開く。その首もとに、脚をたたんだ小さな四足獣が重なる。くわえているのか爪でつかんでいるのかまでは、この画像では決められない。まわりは、人の顔をした有翼獣や角のある獣が列をなして囲む。"}, {"f": "washi03.jpg", "date": "1世紀はじめ（1〜25年ごろ）", "place": "イタリア・ローマ", "title": "インタリオ 帝国の鷲（Intaglio: Imperial Eagle）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1977.13", "note": "館の記載は「紅玉髄、径三センチ五ミリ」。径というからには円い部分の差し渡しで、その下に続く鎖と飾りまで入れると、丈はおよそ倍になる。赤い紅玉髄（カーネリアン）に鷲が彫られ、金の透かし細工の枠に嵌まっている。翼を半ば開き、羽の一枚ずつが細い線で刻まれる。館は「足に雷霆をつかむ」と記し、画面でも足もとに横長の彫りが見える。館の解説によれば、鷲はユピテルと、ローマの皇帝家と、軍のしるしだった。枠の下からは二本の細い鎖が垂れ、先に滴の形の飾りがつく。一羽の鳥が、神と国家の両方を名乗っている。"}, {"f": "washi04.jpg", "date": "1〜2世紀", "place": "イランまたは中央アジア（パルティアかクシャーンの文化）", "title": "鷲と獲物の帯飾り（Belt adornment with an eagle and its prey）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/322485", "note": "高さ六センチ三ミリ、幅八センチ七ミリ。金の輪のなかで、鷲が翼をひろげ、足の下の獣を押さえている。輪には四角い小室が一周ならび、館が「トルコ石の象嵌」と記す石は、残っているものが青みを失って白く濁り（淡い緑を残すものもある）、いくつかの小室は石が抜けて金の底が見えている。左右へ突き出た板は、帯に留めるためのものらしい。館は文化を「パルティアまたはクシャーン」、産地を「イランまたは中央アジア」とし、どちらとも決めていない。決まっているのは、鷲と獲物という主題のほうである。"}, {"f": "washi05.jpg", "date": "1200年代なかば", "place": "中央アジア", "title": "金襴 翼をひろげた鷹（Cloth of Gold: Displayed Falcons）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1996.297", "note": "縦五十七センチ五ミリ、横十八センチ四ミリの絹の裂。金糸で織り出した文様が縦にくり返す——小さな頭と、下へ大きく開く扇のような翼、あいだに円い花文。金糸が擦り切れて茶色の下地が出ている箇所が幾つもある。館の解説は、モンゴルの皇帝が宮廷の人々に贈った一色の金襴の礼服（ジスン）にこうした裂が使われたと記し、この意匠を東イランと中国の要素が合わさった中央アジア独自のものとする。"}, {"f": "washi06.jpg", "date": "1558〜60年ごろ", "place": "ムガル朝インド（アクバル帝の宮廷）", "title": "鷹狩の図（Hunting with falcons in a landscape）", "artist": "アブド・アッサマド（ペルシア・1510ごろ〜1600）に帰せられる", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2013.292.a", "note": "紙の大きさは縦三十五センチ七ミリ。岩ばかりの斜面を、四人が馬で行く。鳥は四羽——二羽は腕の上、一羽は差し上げた手袋の先で翼を広げて宙にあり、一羽は下の中ほどの地面で、赤い衣の男が両手で押さえている。走る男が二人。弓を持った男が一人、鞍を置いた白馬のかたわらに立つ。館の解説は、王族が馬で鷹狩をし、獲物を茂みから追い出し、頭巾を外された鷹がそれを追って落とした、と説明する。縁は一七〇〇年代に足されたものだという。"}, {"f": "washi07.jpg", "date": "江戸時代（1615〜1868年）", "place": "日本", "title": "鷹（Falcon）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1982.27", "note": "絵の部分は縦五十六センチ一ミリ、横二十二センチ一ミリの掛軸。鷹が一羽、赤い横木を黄色い足でつかんで止まる。くちばしは黒く鉤に曲がり、胸から翼へ鱗のような斑が並び、長い尾に黒い帯が入る。右手には、丸い蓋つきの器のようなものが線で描かれている。館はこれを大津絵とし、「狩に使う鷹を描いたもので、豊作を願う縁起物」と記す。神でも紋章でもなく、田の実りのための鷹である。"}, {"f": "washi08.jpg", "date": "1800年代", "place": "北アメリカ北西海岸・ブリティッシュコロンビア（Nuxalk ／ ベラクーラ）", "title": "鷲の面（Mask: Eagle）", "artist": "作者不詳（Nuxalk の彫り手）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1956.547", "note": "幅四十五センチ八ミリ、高さ三十五センチ六ミリの木の面。大きく鉤に曲がった嘴が前へ突き出し、上下に分かれて開く。眼のまわりは青く塗られ、丸い眼には嵌め込みがある（館は「復元された眼の象嵌」と記す）。頭の上には、赤・黄・黒で細かい線を描いた板が二枚、前後に重なって起き上がる（館の記載も head panels と複数形）。下の縁からは紐が垂れる。館は、この面は嘴が開き頭の板が動くので、北西海岸の冬の儀礼の季節に使われたのかもしれない、と記す。"}, {"f": "washi09.jpg", "date": "いま", "place": "モンゴル北部", "title": "イヌワシを確かめる男（写真）", "artist": "NuclearApples（写真）", "museum": "Wikimedia Commons", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Mongolian_Man_and_his_Eagle.jpg", "note": "乾いた草の地面に片ひざをつき、毛皮の外套と赤い帽子の男が、イヌワシを抱えている。鷲の頭には革の頭巾がかぶせてあり、下に嘴だけが出ている。細い紐が男の手から鷲へ渡り、鷲は男の靴の上に立つ。後ろは山なみと、地平まで続く枯れ草の原。撮影者の説明は「モンゴル北部で、鷲猟の競技に出る前に、自分のイヌワシ（Aquila chrysaetos）を確かめる男」。二〇一八年十月五日。頭巾は、鳥に何も見せないための道具である。"}]}, {"id": "hitsuji", "no": "第二十七景", "name": "羊", "yomi": "ひつじ", "en": "Sheep — the fleece that forgot how to fall off", "rep": "hitsuji03.jpg", "lead": "羊は、人がいちばん作り変えた獣かもしれない。野生の羊の毛は、暖かくなれば抜け落ちる。抜けずに伸びつづける毛は、人が選びつづけてつくったものだ。だからいまの多くの羊は、刈られなければ困る。", "nature": [["毛が、止まらなくなった", "羊（Ovis aries）の野生の祖先は、西アジアのアジアムフロン（Ovis gmelini）だとされる。家畜になったのはおよそ一万一千年前から九千年前、西アジアでのことだとされる。場所をメソポタミアと書く資料が多い。年代の見積もりには幅があり、資料によっては一万三千年前ごろまでさかのぼる。野生の羊をおおっていたのは、縮れた綿毛よりも、硬くまっすぐな上毛のほうだった。そして毛は、季節がくれば抜けた。鋏が現れる前は、手や櫛でむしって採ったという。毛の多い羊への選抜が始まったのは前六千年ごろか、とイラン出土の像から推されている。いまの羊の毛が抜けずに伸びつづけるのは、その選抜の果てである。だから毛刈りは、羊から何かを取り上げる行いであると同時に、人が背負ってしまった後始末でもある。優しさでも残酷さでもなく、始末である。草原のアルガリ（Ovis ammon）やウリアル（Ovis vignei）は同じ属の別種で、家畜の羊の祖先には数えられていない。"], ["上あごに、前歯がない", "羊は反芻する獣である。胃が四つの部屋に分かれ、最初の部屋（第一胃・ルーメン）に棲む微生物が、人にはほどけない草の繊維をほどく。いったん飲みこんだものを口へ戻し、噛みなおして、また飲む。上あごに前歯はなく、代わりに硬い歯板があって、下の前歯をそこへ押しあてて草を切る。この体のおかげで、羊は麦の育たない乾いた丘や、寒く高い草原でも生きていける。人が食べられない草が、乳と肉と毛に変わる。中央アジアの遊牧も、西アジアの山地の放牧も、この変換の上に立っている。羊を連れて動くというのは、草を食べられる形に変える装置を連れて動くことでもあった。"], ["羊のいない国から書いている", "この景には、日本の作品が一点もない。三館（クリーブランド・シカゴ・メトロポリタン）が公開しているCC0／パブリックドメインの範囲では、羊を描いた日本の作品が見つからなかった。暦の十二支の八番目に未（ひつじ）があり、名は古くからここにある。名はあるのに、この範囲では獣が出てこない。歌麿に《娘日時計 未刻》という一枚があり、題は未の刻を名乗るが、画面にいるのは女が二人で、羊は一頭もいない。日本に羊がどれだけ居たか居なかったかを、この一件から決めることはできない。決められるのは「探した範囲では見つからなかった」というところまでである。羊を見たことのない土地に、羊の字と羊の名前だけが先に届いていた──そう読みたくなるが、それはこちら側の読みである。"]], "invite": "セーターの洗濯表示を見て、「毛」か「ウール」と書いてあるものを一枚さがす。糸を一本つまみ出して、明るいところで縮れの波を数えてみる。その縮れが抜けなくなったところから、この獣と人の関係が始まっている。", "works": [{"f": "hitsuji01.jpg", "date": "前3500〜前3100年ごろ", "place": "西アジア・南メソポタミア（後期ウルク期）", "title": "雄羊の頭（Head of a ram）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/326655", "note": "館の記載は短い。館は文化の欄を空にしたまま、地域を「南メソポタミア」、時期を「後期ウルク」、材を焼き物とだけ記す。見えるのは黄土色のかたまりで、上の面に渦を一巻きした角がある。角の渦のほかに張り出しが二つあるが、耳と鼻づらのどちらがどちらかは、この一つからは決められない。ほかの面は割れて失われた。羊が人と暮らしはじめてからすでに数千年たったころの物だが、この一つを見るかぎり、獣の姿はほとんど残っていない。角の渦だけが、これは羊だと言っている。"}, {"f": "hitsuji02.jpg", "date": "前900〜前800年", "place": "イラク・ニムルド（フェニキア様式）", "title": "飾り板 ── 聖樹をはさむ雄羊頭のスフィンクス（Decorative Plaque: Ram-Headed Sphinxes Flanking a Sacred Tree）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1968.47", "note": "縦長の象牙の板。まん中に巻きひげと花をつけた樹が立ち、その左右に一頭ずつ、樹のほうを向いた獣がいる。右の一頭を拡大すると、角が耳の前へ回り込むように巻き、目のくぼみに嵌め込みの痕、鼻づらの先に鼻孔、あごの下に短い垂れがある。体には斜めの格子。上と下に丸い穴が一つずつ空くが、用途は館も書いていない。館はこれをフェニキア様式とし、ニムルドの武器庫の倉から数千点が出たこと、宮殿が略奪されたとき井戸へ投げ込まれ、一九五一年に見つかったことを記す。"}, {"f": "hitsuji03.jpg", "date": "前600年ごろ", "place": "イラン（メディア）", "title": "雄羊頭の杯（Ram-Head Drinking Vessel）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1963.479", "note": "銀の器。雄羊の頭が筒の先につながり、うしろは末広がりに開く。角は耳のうしろから前へ大きく一巻きし、渦の中心まで細かい筋が刻まれている。角のうしろから首にかけては点を打ちつめた面になっている。額・頬・鼻づらは磨いた無地のまま。打ち点を毛と読むのは、こちら側である。目のふち、鼻の孔、結んだ口まである。館はこれを角形の杯（リュトン）と呼び、アッシリアを倒したメディアの人々に好まれ、のちアケメネス朝に受け継がれたと記す。飲むための器が、飲まれる側の獣の頭をしている。"}, {"f": "hitsuji04.jpg", "date": "前650〜前600年", "place": "ギリシャ・クレタ島", "title": "クリオフォロス（羊を担ぐ者）像（Kriophoros (Ram-Bearer), Statuette）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1998.172", "note": "上半身だけが残る土の像。大きな目、左右に垂れた縦筋の髪、頭に兜らしいもの、腰に格子縞の帯。両手を胸の前へ上げて何かの脚を握り、その先をたどると、画面の左（像から見れば右）の肩に小さな獣が横たわり、頭は像の輪郭の外へ、左へ突き出している。獣の体には三角の彩色が残る。館は、羊を担ぐ像はふつう牧夫か、のちにはヘルメス神をあらわすが、この一体は戦士の姿で例がないかもしれない、この型としてはごく早い、と記す。捧げものとして差し出しているという読みにも「おそらく」がついている。"}, {"f": "hitsuji05.jpg", "date": "6世紀", "place": "中国（北魏）", "title": "十二支の俑・未（Mortuary Figure of the Zodiac Sign: Sheep (Scorpio)）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1972.76.8", "note": "獣の頭に人の体をつけた坐像。長い衣の袖のなかで両手を前に組み、首を伸ばしている。頭には小さな耳が左右に立ち、そのあいだに短い角が二本。灰色の焼き物で、白っぽい塗りがまだらに残る。館は題を「十二支の羊（Scorpio）」とするが、同じ館の解説文では八番目の獣を goat と書いている。中国語の「羊」は綿羊も山羊も指す語なので、英語に移すたびに揺れる。西洋の星座名がなぜ添えてあるのかは、館の記載からは分からない。"}, {"f": "hitsuji06.jpg", "date": "19世紀", "place": "中央アジア・トルクメニスタン（サリク族）", "title": "トルクメンの袋の表（Turkmen Bag Face）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2008.223", "note": "赤い地に、大きな八角形の飾り（グル）が縦四段・横三列で十二。どれも暗い斜めの十字で四つに割れ、あいだに角ばった小さなグルが互い違いに入る。館は材を羊毛・絹・木綿、結び目を一平方インチに二五二と記し、サリク族の織りとして知られるいちばん古い一枚だとする。これは袋の表側で、天幕のなかでは壁の格子から吊るされ、季節の移動のときは駄獣が運んだという。羊の毛が、荷物を入れる袋になっている。"}, {"f": "hitsuji07.jpg", "date": "1861年", "place": "フランス", "title": "羊（Sheep）", "artist": "ロザ・ボヌール", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1915.716", "note": "はっきり立っているのは手前の一頭だけ。濃い茶色で、角が耳のうしろで一巻きし、体はこちらを向き、顔だけ画面の左へ向けている。手前の枯れ草には白っぽい羊が何頭も伏せ、毛が体の輪郭を丸くしている。立っている一頭と伏せている羊たちとでは、まとっている毛の量がまるで違う。画面の右奥にも白い塊が二つあるが、輪郭だけで、立っているか伏せているかは決められない。左下に「Rosa Bonheur 1861」の署名。館は技法を、鉛白で明るくした褐色の淡彩と記し、その白の一部が酸化して桃色に変わっているとことわっている。"}, {"f": "hitsuji08.jpg", "date": "1900年ごろ", "place": "中央アジア・トルクメニスタン（ヨムート族）", "title": "戸口の敷物 エンシ（Door Rug (Ensi)）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2010.191", "note": "四角い敷物。内側が十字に区切られて四つの区画になり、どの区画にも小さな菱形が細かく散り、上の二区画の下端と、下の二区画の上端に、白い三角が向かい合って並ぶ。まわりは鉤の形をつないだ縁取りが二重に回り、いちばん外に矢羽根のような段がつく。館は題を「戸口の敷物（エンシ）」、材を羊毛、結びを非対称で一平方インチに約一一七と記すだけで、解説はつけていない。何の戸口なのかも書かれていない。敷くのでも掛けるのでもなく、出入り口に当てる布が、羊の毛でできている。"}, {"f": "hitsuji09.jpg", "date": "いま", "place": "モンゴル（フブスグル県）", "title": "モンゴルの羊（写真）", "artist": "Bernard Gagnon", "museum": "Wikimedia Commons", "lic": "CC0", "url": "https://commons.wikimedia.org/wiki/File:Sheep_in_Mongolia_01.jpg", "note": "皮を剥いだ丸太を横に渡し、結わえた柵。その囲いに羊がぎっしり詰まっている。毛はほとんどが生成りで、顔だけが黒いもの、茶色いものが混じる。耳は横へ垂れる。背に緑の印がついた個体がいて、飼い主の印だろうと読めるが、撮影者の説明にはそこまで書かれていない。撮影は二〇二三年六月二十九日、モンゴル北部のフブスグル県。ここまでの八点で、羊は角であり、頭であり、毛であり、暦の獣だった。最後にようやく、ただの羊が、数えきれないほどいる。"}]}, {"id": "hebi", "no": "第二十八景", "name": "蛇", "yomi": "へび", "en": "Snake — the tetrapod that put its legs away", "rep": "hebi02.jpg", "lead": "蛇は、脚を失った四肢動物である。腹を地面につけたまま、舌で匂いを拾い、古い皮を脱いで大きくなる。人はひろく、この一本の線に王の額を、よみがえりを重ねてきた。ここに並ぶ九点がそのどれを背負っているかは、一点ずつ違う。", "nature": [["脚をなくした、四本足の子孫", "脚は、いちどはあった。蛇はトカゲに近い系統から分かれ、その途中で四本の脚を手放した。ニシキヘビやボアのなかまには、後肢のなごりが体の左右に小さな爪（蹴爪）として残り、外から見えることが知られている。かわりに長くなったのは背骨で、種によって幅はあるが、およそ二百から四百の椎骨が連なり、尾をのぞく椎骨の、ほぼ一つ一つに肋骨がつく。腹の側には幅の広い鱗が一列に並ぶ。腹側の筋肉でこの鱗を順に前へ送る進み方もあれば、体をくねらせて進む進み方もある。腹を地面につけているので、蛇は地面の震えをよく拾う——外に開いた耳の穴はなく、下あごの骨を通って伝わる震えを聞いているとされる。"], ["舌が、匂いを運ぶ手になる", "蛇の舌は、味わうためではなく、匂いを運ぶために出入りする。二股に分かれた先で空気や地面の粒子をすくい、口の中へ戻して、上あごの前のほうにある鋤鼻器（ヤコブソン器官）へ渡す。鼻とは別の、もう一つの匂いの受け口である。先が二本あるぶん左右の濃さを比べられる、と説明されることが多い。だとすれば、蛇が舌を出すのは怒っているのではなく、あたりを嗅いでいることになる。目のほうには、まぶたがない。眼球は透明な一枚の鱗に覆われていて、蛇は瞬きをしない。眠っていても目が閉じないのは、閉じるための蓋がそもそも無いからである。"], ["脱いでも、同じ体が出てくる", "蛇は、体の外側をひとつづきに脱ぐ。古い表皮の下に新しい層ができ、その古い層と新しい層のあいだに液がたまるため、脱皮の前には目が白く濁り、そのあいだ見えにくくなるとされる。目を覆う透明な鱗も皮といっしょに剥がれ、脱ぎ終えると、鱗の一枚一枚まで写しとった薄い抜け殻が、裏返しの靴下のように残る。若い個体ほど回数が多い。──熱を感じる器官を持つ種もいる。マムシやガラガラヘビのなかまは目と鼻孔のあいだのくぼみで、ニシキヘビや一部のボアのなかまは唇に並ぶくぼみで、赤外線をとらえるとされる。こちらはその眼を、本と映像でしか知らない。手元の機材で蛇の見ている熱を撮ったことは、まだ一度もない。"]], "invite": "草むらや石垣の隙間に、白く薄い抜け殻が残っていることがある。見つけたら、頭のほうから尾へ、鱗の並びを目でたどってみる。目のあった場所にも、透明な鱗が一枚ぶん残っている。", "works": [{"f": "hebi01.jpg", "date": "前1307〜前1196年ごろ", "place": "エジプト", "title": "ウラエウス ── 鎌首をもたげたコブラ（Uraeus (Rearing Cobra)）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2023.102", "note": "銀と銅の合金でつくられた、鎌首をもたげたコブラ。頭巾が左右にひろがり、正面に縦の筋が並ぶ。目には象嵌が入り、頭巾の裾にも緑の石が残っている。館は、下の端が大きな像の頭のてっぺんに差し込まれていたらしいこと、体と尾が短く切られているのは背後に日輪を立てる場所を空けるためかもしれないこと、頭巾には象嵌用の窪みが六つ残ることを記す。ウラエウスは王や神の額のあたりに立てられる標だが、この一点がだれの像に載っていたのかは、館も書いていない。"}, {"f": "hebi02.jpg", "date": "前720〜前700年ごろ", "place": "ギリシャ（アテナイ）", "title": "幾何学様式の頸把手付アンフォラ ── 遺体を安置する場面・嘆く人びと・馬車（Geometric Neck-Handled Amphora (Storage Vessel): Prothesis (Laying out of Corpse), Mourners, Chariots）", "artist": "作者不詳（アテネ894の工房）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1927.6", "note": "粘土で別につくった蛇が、口縁の上をうねり、両の把手を這い上がり、肩のところで頭を突き合わせている。体には細かい刻みが入り、頭は平たく尖る。頸の枠には両手を頭にやった人が並び、胴には二頭立ての馬車が列をなす。館はこれを弔いの場面とし、貼り付けられた蛇は冥界を指すのかもしれない、と記す。蛇は絵ではなく、器の縁そのものになっている。"}, {"f": "hebi03.jpg", "date": "前400年代はじめ", "place": "中国（東周）", "title": "鎛鐘（Bell (Bo Zhong)）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1962.44", "note": "青銅の鐘。館は、吊り手の透かしを「二つの体をもつ蛇と二匹の虎が絡んだもの」とし、胴に並ぶ瘤を「とぐろを巻いた蛇」と説明する。数えると、見えている面だけで、中央の帯の左右に九つずつ、十八ある。断面が楕円なので、縁を打つか中央を打つかで二つの音が出るとも記される。ここでは蛇は主題ではなく、鳴らすための道具の骨組みと手ざわりのほうへ回っている。"}, {"f": "hebi04.jpg", "date": "400〜550年", "place": "メキシコ中央高原（テオティワカン）", "title": "羽毛の蛇の鉢（Basin with Feathered Serpent）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1965.20", "note": "脚のついた大きな鉢（写っているのは二本）。壁をぐるりとめぐる緑の帯が蛇の体で、左端に口をあけた頭がある。体の上には白い花形が三つ、下には縁を緑の羽で飾った形が四つ下がる。館はこの緑をケツァールという鳥の羽の色とし、四つの形を人の心臓とし、羽毛の蛇は豊かな自然と生命の像であり、統治の徴でもありうる、と記す。蛇に羽根が生えるのは、この土地の見方である。"}, {"f": "hebi05.jpg", "date": "800年代", "place": "インド中部", "title": "パールシュヴァ（Parshva）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1961.419", "note": "砂岩の板から立ち上がる裸形の像。頭のうしろに蛇の頭巾が扇のようにひらき、その上に傘が三段重なる。両脇には象と、花輪を持つ小さな神々が並ぶ。館は、これをジャイナ教の第二十三祖パールシュヴァとし、二十四人の祖のうち蛇を伴って表されるのは彼ひとりだと記す。頭巾を、うしろから差しかけられた屋根と見るのはこちら側の読みで、館は蛇の数にも由来にも触れていない。"}, {"f": "hebi06.jpg", "date": "1325〜1519年", "place": "メキシコ中央高原（アステカ）", "title": "蛇の口の中の頭（Head in Mouth of Snake）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1948.356", "note": "緑色の石を彫った小さな塊。人の顔があり、その上と下を太い弧が挟む——館の題「蛇の口の中の頭」に従うなら、この二本は開いた顎である。目も口も、深く彫り込まれて暗い穴になっている。貫通しているかどうかは、この一枚からは分からない。右上には丸い出っぱりが一つ。館は解説をつけておらず、題と材（緑色岩）と年代、寸法（五・四センチ）だけを記す。だれの顔なのか、呑まれているのか出てくるところなのかは、この一点からは決められない。"}, {"f": "hebi07.jpg", "date": "1840年ごろ", "place": "日本（江戸）", "title": "武勇見立十二支 巳 仁田四良（仁田四郎）（Snake (Mi): Nitan Shiro, from the series “Heroes for the Twelve Animals of the Zodiac (Buyu mitate junishi)”）", "artist": "歌川国芳", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/11229", "note": "浅い水の中に、鎧の武者がひとり立つ。斜めに構えた長い棒の先が燃えている（松明と見るのはこちら側の読み）。足もとの水には蛇が二匹——黄と黒の縞のものと、淡い桃色のもの——が身をくねらせる。上には鱗におおわれた巨きな体がうねり、そのうねりに包まれるように、髪飾りをつけた女の姿が薄墨で浮かぶ。枠には「武勇見立十二支」、赤い札には「巳」。館は題のほかに解説をつけていない。"}, {"f": "hebi08.jpg", "date": "1800年代後半〜1900年代はじめ", "place": "西アフリカ・ギニア", "title": "蛇の頭飾り（Serpent Headdress）", "artist": "作者不詳（おそらくバガ様式の彫り手）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1960.37", "note": "木を彫った蛇が、S字にうねって立ち上がる。白・赤・黒の三角が体を斜めに区切り、頭は平たい。こちらを向いた面には、丸い目が一つ描かれている。館は高さを五フィート近く（およそ一・五メートル）とし、椰子の枝で編んだ円錐で頭に留めて踊られたこと、顔が二つあって四方を見ていたこと、少年と少女の通過儀礼の要所に現れたこと、この蛇が虹に喩えられ、その移ろう色が少年から大人への変化に重ねられることを記す。"}, {"f": "hebi09.jpg", "date": "いま", "place": "中国・香港（ランタオ島）", "title": "翠青蛇（Cyclophiops major／現在は Ptyas major とも）── 舌を出す（写真）", "artist": "Thomas Brown（写真）", "museum": "Wikimedia Commons", "lic": "CC BY 2.0", "url": "https://commons.wikimedia.org/wiki/File%3AChinese_Green_Snake_%28Cyclophiops_major%29_%E7%BF%A0%E9%9D%92%E8%9B%877.jpg", "note": "暗がりに、緑の頭が一つ。口の先から二股の舌が弧を描いて上へ反る——根もとは赤く、分かれた先の二本は暗がりに白く光る。目は丸く、金色の縁のなかに黒い瞳。下では体が緩くとぐろを巻く。撮影者は、二〇一一年八月三十日に香港・ランタオ島の集水路の中で見つけたと記している。八点の彫刻と絵を見てきたあとで、舌が空気を掻いて戻るまでの、ほんの一瞬が写る。"}]}, {"id": "kai", "no": "第二十九景", "name": "貝", "yomi": "かい", "en": "Shell — the hard part an animal builds, and the part that outlives it", "rep": "kai02.jpg", "lead": "貝殻は、動物が自分の体でつくった硬い部分である。動物が死んだあとも殻だけは残り、拾われ、削られ、糸に通されて、海から遠い内陸まで運ばれた。ここに並ぶのは、その残ったほうである。", "nature": [["殻は、外套膜が積んだもの", "貝はやわらかい体をもつ動物で、軟体動物と呼ばれる仲間に入る。殻は骨ではなく、体の背中側を包む膜——外套膜（がいとうまく）——が炭酸カルシウムを分泌して積んだものである。積まれるのは殻の縁で、動物が育つにつれて口の縁に少しずつ足されていく。だから殻の表面を走る細い線は、育った跡の記録になる。殻はふつう何層かでできていて、いちばん外に有機質の薄い皮、その内側に結晶が柱のように並ぶ層、いちばん内側に真珠層がくることが多い（タカラガイやスポンディルスのように、真珠層をもたない仲間もある）。真珠層が見る角度で色を変えるのは、光の波長ほどの薄さの層が幾重にも重なっているためとされる。真珠も、この真珠層が体の内側で異物や外套膜のかけらを包みながら重なってできるとされる。螺鈿は、その真珠層を薄く剥いで貼ったものである。"], ["巻きの向きは、生まれるより前に決まる", "巻貝の殻はらせんである。とがったほうを上に、口をこちらへ向けて持ったとき、口が右にくるものを右巻き、左にくるものを左巻きという。多くの種は右巻きで、左巻きは種そのものの特徴である場合と、まれに一個体の変異として現れる場合がある。どちらに巻くかは卵が分かれていく早い段階で決まるとされ、あとから変えることはできない。二枚貝はこれとは別の作りで、向かい合う二枚の殻を蝶番でつなぎ、筋肉で閉じる。——この景の五点目に置いた版画には、この巻きの向きの話にもう一つの仕掛けが加わる。版画は刷ると必ず左右が反転するので、目の前の貝をそのまま版に写せば、紙の上の巻きは実物と逆になる。銅版に彫るのが通例だが、館の記載は「エッチング」とだけである。"], ["数えられる貝", "タカラガイの仲間（子安貝）は、暖かい浅い海にすむ巻貝で、殻は厚くつやがあり、大きさがよく揃う。割れにくく、数えやすく、似せてつくるのが難しい。この性質のために、殻は産地から遠くまで運ばれ、西アフリカにいたる各地で長く貨幣として使われたことが知られる。東アジアでも古くから価値あるものとして扱われ、値打ちや取引にかかわる漢字——財・貨・買・貯——が「貝」を部分にもつのは、その名残とされる。この景でタカラガイの類が見えるのは二か所である。ナイル川ぞいのヌビアの玉の緒の端に、それらしい形のものが一つ（館の記載は「貝」とだけ）。西アフリカのヨルバの杖には、十本あまりの紐に通されて垂れる（前から数えられるだけで、裏側は写っていない）。その貝がすむ海から遠い土地にある貝は、誰かが運んだ貝である。"]], "invite": "浜で拾った巻貝を、とがったほうを上、口をこちらへ向けて持ってみる。口が右にあれば右巻き。その口の縁こそ、この貝が最後に殻を足した場所である。", "works": [{"f": "kai01.jpg", "date": "前2200〜前1050年ごろ", "place": "ヨーロッパ・クレタ島（ミノア）", "title": "テラコッタの貝（Terracotta shell）", "artist": "作者不詳（ミノアの作り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/252336", "note": "焼いた土でつくられた貝。上へ向かって段が四つほど細くなりながら重なり、その下に大きな膨らみがくる。右手には本体から少しずれた面がもう一つ張り出し、下の端に小さな穴があいている。表面はざらつき、ところどころ欠けている。長さは 3.3cm、手のひらに収まる大きさである。所蔵館は題を「テラコッタの貝」、材を「粘土」、文化を「ミノア」、中期または後期青銅器時代と記すが、用途は記していない。貝でよいところに、わざわざ土を焼いて貝の形がつくられている——何のためかは、館の記載からは分からない。"}, {"f": "kai02.jpg", "date": "前100〜700年", "place": "南アメリカ・ペルー南海岸（ナスカ）", "title": "猫をはめ込んだ貝（Shell with Inlaid Feline）", "artist": "作者不詳（ナスカの作り手）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1950.567", "note": "扇形の貝の片側。放射状の筋が縁へ走り、地は濃い橙色をしている。所蔵館はこれをスポンディルス（とげのある二枚貝）の殻とし、外側の面を削り取ると下から明るい橙が現れる、と記す。その橙の上に、白・紫・水色の貝と石をはめて一匹の獣が組んである。丸い目、二重丸の並ぶ四本の脚、先の黒い尾。館はこれをパンパスキャットと呼び、左下の金を瓢箪か果実だとする。殻の下の縁には穴が二つあいている。"}, {"f": "kai03.jpg", "date": "前30〜364年", "place": "アフリカ・ヌビア（いまのスーダン）", "title": "貝の下がる玉の緒（String of beads with shell pendant）", "artist": "作者不詳（ヌビアの作り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/561738", "note": "淡い緑の平たい玉が、一本の長い紐にびっしり通されている。ところどころに褐色や黒の玉が交じる。左下の端に、本物の貝がひとつ下がる。口の側をこちらへ向けており、細長い割れ目の両側に細かい歯が並ぶ——タカラガイの仲間の形である。上端は黒く欠けたように見え、そこへ糸が通る。所蔵館は材を「ファイアンス、貝」、文化を「ヌビア（スーダン）」、メロエ期と記す。人工の玉が何百のなかで、貝はひとつだけである。"}, {"f": "kai04.jpg", "date": "1400年代末〜1500年代初め", "place": "朝鮮半島（朝鮮王朝）", "title": "螺鈿の花形盆（Foliate-Shaped Tray with Mother-of-Pearl Inlay）", "artist": "作者不詳（朝鮮王朝の作り手）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2026.3", "note": "黒漆の盆。縁は花びらのように波打ち、立ち上がりの全面に小さな菱形の貝が隙間なく並ぶ。底には細い蔓と葉と花が、やはり貝を切って貼ることで描かれている。見る角度で青にも緑にも見えるのは、貝の内側の層を薄く剥いで使っているからである。所蔵館は材を「黒漆地に鮑貝を象嵌し、内側に朱漆」とし、この時期の作例は残りが少なく、状態のよい稀な一点だと記す。"}, {"f": "kai05.jpg", "date": "1650年", "place": "オランダ", "title": "貝（The Shell）", "artist": "レンブラント・ファン・レイン", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/29253", "note": "横倒しの円錐形の貝がひとつ、暗がりに置かれている。表面は網目で、光の当たる側だけが白く抜ける。左の端に巻きの渦が見え、右へ細くなる。背景は斜めの線を重ねた闇で、貝は台に影を落とす。左下に「Rembrandt f. 1650」と読める署名——刷り上がりでこう読めるということは、版の上では左右が逆に彫られていたということである。館の解説は、十七世紀に貝が珍しい蒐集品として好まれたことを記す。"}, {"f": "kai06.jpg", "date": "1800年代前半〜半ば", "place": "南太平洋・ソロモン諸島", "title": "グレレオ ── 盾（Grere'o (shield)）", "artist": "作者不詳（ソロモン諸島の作り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/310073", "note": "縦長の楕円の盾。盤の上から下まで小さな四角い貝の片が並べて貼られ、その連なりが線となって図を描く。貝片は線の部分だけに置かれ、あいだは赤褐と黒の地のままである。上のほうには楕円の枠に囲まれた顔——眉と目と口が抜かれ、両脇に耳飾りらしい形が下がる。その下に肩と腕、さらに下の帯には暗い四角のなかに小さな顔が二つ。いちばん下はU字を何重にも重ねた線。所蔵館は材を「繊維、パリナリウムの実の練り物、オウムガイの殻、顔料」と記す。貝は、ここでは光る線になっている。"}, {"f": "kai07.jpg", "date": "1800年代", "place": "南太平洋・アオテアロア（ニュージーランド）", "title": "漁の舟の舳先飾り（Fishing Canoe Prow）", "artist": "作者不詳（マオリの彫り手）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1967.231", "note": "舟の舳先の彫り物。渦を重ねた文様が顔じゅうを覆い、額から鼻へ、頬から顎へと巻いていく。目には青緑に光る貝がはめてあり、黒ずんだ木のなかでそこだけが濡れたように光る。所蔵館は材を「木、ハリオティス（アワビの仲間）の貝の象嵌」と記す。胸のあたりには、彫りではない白い文字で「NEW ZEALAND」と書かれている。いつ誰が書いたのかは、館の記載にはない。"}, {"f": "kai08.jpg", "date": "1800年代", "place": "西アフリカ・ナイジェリア（ヨルバ）", "title": "エシュの踊りの杖（Dance staff for Èṣù (Ògò Èlẹ́gba)）", "artist": "作者不詳（ヨルバの作り手）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2018.34", "note": "二体の像が寄り添って立ち、どちらも先の尖った長い髪型をしている。左の像の髪には小さな顔がいくつも彫られ、右の像には乳房がある。両肩と首から、小さな貝を通した紐が垂れる。前から数えられるのは十本あまりで、像の丈より長い。貝は背の側を落としてあるように見え、輪のように連なる。所蔵館は材を「木、革、タカラガイ、種子、天然繊維」と記し、ヨルバの神エシュの踊りの杖とする。"}, {"f": "kai09.jpg", "date": "いま", "place": "オーストラリア・グレートバリアリーフ（ミカエルマス・ケイ）", "title": "オオシャコガイ（写真）", "artist": "Charles J. Sharp", "museum": "Wikimedia Commons", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Giant_clam_(Tridacna_gigas)_Michaelmas_Cay.jpg", "note": "白い砂の底に、大きな二枚貝がひとつ。二枚の殻の縁は深く波打ち、その全面が小さな生きものに覆われている。覆いの色は白砂と同じ灰白で、ひと回り暗いだけである。開いた隙間からのぞくのは、その殻をつくっている当の動物——外套膜である。縁は灰青色、内側は濃い藍に金褐色の斑が散る。撮影は二〇二三年十一月六日、オーストラリアのグレートバリアリーフ。撮影者の記載はオオシャコガイ（Tridacna gigas）とする。ここまでの八点——六点は殻そのもの、二点は殻を写したもの——を見たあとで、はじめて積んでいる側が見える。"}]}, {"id": "suigyu", "no": "第三十景", "name": "水牛", "yomi": "すいぎゅう", "en": "Water buffalo — the animal that cools itself in mud, and kneaded the paddies of Asia", "rep": "suigyu09.jpg", "lead": "スイギュウは、汗で体を冷やすのがうまくない。だから暑い時間は水に入り、泥に体を沈め、泥を着たまま出てくる。アジアの水田の泥をこね、そこに水を溜めてきたのは、この動物である。", "nature": [["汗をかけないから、泥に入る", "スイギュウ（Bubalus bubalis）はウシ科の家畜で、南アジアと東南アジアが本拠である。姿はウシに似ているが、熱の逃がし方が違う。ウシにくらべて汗腺が少なく、汗で体温を下げる力が弱いとされる。皮膚は黒っぽく毛が薄いので、日を受けると熱がこもりやすい。だから暑い時間は水に入り、泥に体を沈める。泥をかぶることは体を冷やすだけでなく、乾いた泥が日差しをさえぎり、刺す虫を寄せつけにくくする、とも言われる。足も湿地向きで、二つに割れた蹄が大きく開くので、ぬかるみに沈み込みにくい。水に入り、泥をこね、泥を着て出てくる——この動物の一日は、たいてい土と水のあいだで進む。泥から上がったばかりの体は、いま出てきた泥と同じ色をしている。"], ["二つの型 ── 乳のための水牛と、田のための水牛", "家畜の水牛は、ふつう二つの型に分けられる。河川型（かせんがた）は南アジアから西アジア・地中海にかけて広がり、おもに乳を搾るために飼われる。沼沢型（しょうたくがた）は中国南部から東南アジアにかけて広がり、水田を耕す力として飼われてきた。二つは染色体の数まで違い（河川型は五十本、沼沢型は四十八本とされる）、それでも交配した子は生まれる。家畜化の場所と時期には諸説があるが、河川型は南アジアで、沼沢型は中国南部から東南アジアのあたりで、それぞれ別に家畜化されたとする見方が広い。世界の家畜水牛はおよそ二億頭とされ、その大半はアジアにいる。搾られる乳の量は、ウシに次いで多い。イタリア南部のモッツァレラ・ディ・ブーファラも、この動物の乳である。名前は紛らわしい。アフリカスイギュウ（Syncerus caffer）は別の属の別の生きもので、家畜になっていない。北アメリカで「バッファロー」と呼ばれるアメリカバイソン（Bison bison）も、また別である。野生のアジアスイギュウ（Bubalus arnee）は、いま南アジアと東南アジアの限られた場所にわずかに残るだけで、絶滅の危険が高いとされる。"], ["泥をこねて、田をつくる", "水を張った田は、放っておけば水が下へ抜けていく。だから田植えの前に、水と土をいっしょにかき混ぜて泥にし、平らにならす。これを代掻き（しろかき）という。こねられた土は目が詰まって水を通しにくくなり、田に水がとどまる。アジアの広い範囲で、この仕事を長いあいだ担ってきたのが水牛である。犂（すき）や馬鍬（まぐわ）を引かせ、人は後ろから歩く。水牛は土を運ぶ動物ではなく、土の粒の並びを変える動物だった。角も残った。角は熱を加えると柔らかくなり、冷えると形がとどまるので、櫛にも柄にも器にも板にもなる。日本の印鑑の材にある「黒水牛」も、この動物の角である。もっとも、水牛は日本の在来の家畜ではない。八重山諸島の水牛は二十世紀に台湾から持ちこまれたものとされ、本土の田を鋤いてきたのはウシとウマだった。日本では、生きた水牛に会うことより、角でできた道具に触れることのほうが、ずっとありふれている。"]], "invite": "この景の最後の一枚を、まず小さいまま見てみる。灰色の泥の窪みにしか見えないはずである。つぎに、後ろへ広く開いた三日月の角を探し、その根もとの下にある平たい耳を探す。角と耳が見つかるたびに、泥だと思っていた盛り上がりが一頭の背に変わる。泥にひたっているあいだ、水牛の体は泥と同じ灰色になる。牛を探すのではなく、角と耳を探すほうが早い。", "works": [{"f": "suigyu01.jpg", "date": "前2600〜前1900年ごろ", "place": "南アジア・インダス（インダス文明・いまのパキスタンとインド北西部）", "title": "印章 ── 水牛と香炉（？）（Stamp seal: buffalo with incense burner (?)）", "artist": "作者不詳（インダスの作り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/324063", "note": "館の記載＝凍石（ステアタイト）を焼いて釉をかけたもの、文化は「インダス」、時期は成熟ハラッパー期、3.81 × 0.97 cm。指先に載る大きさである。四角い枠のなかに、重い体の獣が横向きに立つ。頭は右にあって低く下がり、そこから角が一本の長い三日月になって背のほうへ倒れる。喉の下には襞が垂れ、腹の下には雄であることを示す形、四本の脚の先は二つに割れている。鼻づらの向く先には、上が格子の編み目、下が粒の並ぶ丸みという二段の器が、細い脚の上に立つ。館の題はこれを「香炉（？）」と呼び、疑問符を付けている。上の帯には印の文字が五つほど並ぶが、インダス文字はいまも読めていない。図は地から盛り上がって見えるけれど、写っているのが印章そのものなのか、押した跡なのかは、館の記載には無い。"}, {"f": "suigyu02.jpg", "date": "前300〜後200年ごろ", "place": "東南アジア・タイ（バンチエン）", "title": "水牛の頭（？）の垂れ飾り（Pendant with Buffalo Head?）", "artist": "作者不詳（バンチエンの作り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/53393", "note": "館の記載＝青銅、タイのバンチエン、後期、幅 4.8〜5.1 cm。題そのものが「水牛の頭（？）」で、疑問符は館が付けたものである。正面を向いた獣の顔から、二本の角が高く立ち上がり、上のほうで内へ向き合って、閉じかけた輪のような三日月をつくる。顔は小さく、丸い目、幅の広い鼻づら、角の付け根の下に耳が張り出す。頭のうしろには横向きの管が渡してあって、紐を通せそうに見えるが、館は用途を書いていない。左右に張り出した耳の板には、小さな穴が一つずつあいている。緑青が全体に回って、濃い緑黒色をしている。写真では現代の細い支柱に立てて撮られている。バンチエンはタイ東北部の先史時代の遺跡で、この一点が、この景でいちばん古い東南アジアの作品になる。"}, {"f": "suigyu03.jpg", "date": "800年代（9世紀）", "place": "東南アジア・インドネシア（ジャワ島・中部ジャワ期）", "title": "水牛の魔物マヒシャに勝った女神ドゥルガー（マヒシャースラマルディニー）（The Goddess Durga Victorious over the Buffalo Demon, Mahisha (Mahishasuramardini)）", "artist": "作者不詳（中部ジャワ期の彫り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/38273", "note": "館の記載＝火山岩（安山岩）、インドネシア・ジャワ、中部ジャワ期、高さ 152.5 cm。人の背丈ほどある石碑である。腕の多い女神が正面を向いて立ち、その素足は、腹ばいに倒れた獣の背を踏んでいる。獣は頭を右へ向け、四肢を折りたたみ、角は根もとから折れて短い株だけが残る。広い鼻づらと大きな耳は、まだそれと分かる。女神の顔は摩耗して失われ、背の後ろに大きな楕円の光背が立つ。首飾り、腕輪、腰の帯が細かく彫られ、右のほうの手には髪の塊のようなものが握られている。獣の首のわきには、小さな人の形がもう一つ、腕を曲げて現れている。水牛の姿をした魔物マヒシャを女神が倒すというこの話は南アジアの神話に出てくるもので、ここでは海をこえたジャワの火山の石に彫られている。"}, {"f": "suigyu04.jpg", "date": "1145年", "place": "中国（南宋）", "title": "人と水牛と仔牛（Man, Buffalo, and Calf）", "artist": "Li You（1145年ごろ活動）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1960.41", "note": "館の記載＝画帖の一葉、絹本着色、南宋。作者「Li You（1145年ごろ活動）」に館じしんが原語表記の李祐を添え、画中の落款も「乙丑歲李祐椿畫」と読んでいる。丸い画面のなか、左に大きな水牛が頭をぐっと下げて立つ。角は左右へ広く開いてから前へ回りこみ、体は丸く重い。その右を仔牛が歩き、こちらの角は頭からうしろへ細く流れる一本の線にしか見えない。右手の木の根もとに子どもが腰かけ、黒い鳥を止まらせた棒を持つ——館はこれを飼っている九官鳥だとする。題は「人と水牛と仔牛」だが、解説の本文では「牧童」が「牝牛（a cow）」を世話していると書いていて、揃っていない。水牛が田を耕すことから「自分の得にならない苦労を引き受ける者」と読まれたことも館は記す。赤い印は三つで、館も三顆と記す。"}, {"f": "suigyu05.jpg", "date": "1500年代半ば〜後半", "place": "日本（室町〜桃山）", "title": "夏の耕作と牧牛（Farming and Herding Buffalo in Summer）", "artist": "狩野秀頼（1500年代半ば〜後半に活動）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/2015.594", "note": "館の記載＝掛軸、紙本墨画淡彩、室町から桃山。霞んだ山が上に連なり、中ほどの左手には段になった田が広がって、畦の上に人影が小さく並ぶ。右手に柳、下に岩。画面の左下、水のなかに獣が二頭いる。大きいほうは背を水の上に出し、首を伸ばして鼻づらを水面に置き、その背には淡い色の人が乗って、細い棒を前へ差し出している。小さいほうも角のある頭を上げ、背から尾までの線を水の上に出している。館はこれを夏の水牛の牧と呼び、こうした情景が国の豊かさの理想と結びつけられてきたこと、秀頼を狩野元信の次男とする見方が近年は多いことを記す。ただし水牛は日本の在来の家畜ではない。ここに描かれた獣を、絵師が実際に見た水牛だと決めることは、この一枚からはできない。"}, {"f": "suigyu06.jpg", "date": "1700〜1800年代", "place": "東南アジア・フィリピン南部（モロ）", "title": "兜（Helmet）", "artist": "作者不詳（モロの作り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/27827", "note": "館の記載＝材は「角、革、毛（すべて水牛）」、文化は「フィリピン、モロ」、地域はフィリピン南部、高さ 28.6 cm、重さ 1151 g。材の欄が言い切っている——これは水牛を写したものではなく、水牛そのものでできた道具である。丸い鉢は、細長い角の板を十数枚、縦に並べて縫い合わせてつくってある。板は黒く、薄いところだけ飴色に透ける。鉢の裾を一本の帯が締め、そこから幅の広い板がぐるりと下がって、首と頬を覆う。縫い目は小さな輪になって表に出ている。てっぺんには小さな突起があり、穴が一つあいている。角は熱を加えると柔らかくなり、冷えると形がとどまる——世界の各地で角が板や器にされてきたのは、この性質による。"}, {"f": "suigyu07.jpg", "date": "1800年代後半", "place": "東南アジア・ミャンマー（ビルマ）", "title": "グウェ ── 水牛の角の楽器（Gweh (Horn)）", "artist": "作者不詳（ビルマの作り手）", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/500803", "note": "館の記載＝材は「水牛の角」、文化は「ビルマ」、国はミャンマー（旧ビルマ）、長さ 26.7 cm、直径 7.6 cm、分類は「気鳴楽器・フリーリード」。館の題そのものは「Horn」で、「Gweh (Horn)」は品名の欄にある。1889年にクロスビー・ブラウン楽器収集として館へ入った。写真に写るのは、湾曲した一本の角だけである。太いほうの端は大きく口を開け、細いほうの端は切り落とされて、そこに小さな切り欠きが見える。表面には長い方向の細い筋が薄く走る。画像は青紫に転んでいて、実物の色は写真からは決められない。前の一点（兜）と同じで、これも水牛を描いたものではなく、水牛の一部である。どう鳴らすものかについて、館は分類の語より詳しくは書いていない。"}, {"f": "suigyu08.jpg", "date": "1915〜1920年ごろ", "place": "東南アジア・フィリピン", "title": "田を鋤く水牛（写真）", "artist": "撮影者不詳（ベイン通信社の配信）", "museum": "Wikimedia Commons（アメリカ議会図書館）", "lic": "パブリックドメイン", "url": "https://commons.wikimedia.org/wiki/File:Carabao_Plowing_rice_field,_Philippines_LOC_14333026510.jpg", "note": "ガラス乾板からの複製。図書館の記載は題が「Carabao Plowing rice field, Philippines」、年代は「1915年ごろから1920年ごろ」、配信元はベイン通信社。題は「通信社が乾板や説明カードに書いた、裏の取れていない情報による」と断ってある。画面の上を大きな白い弧が走るのは、乾板の膜が傷んだ跡である。手前、水を張った田のなかに水牛が一頭。泥に脚が隠れ、腹のあたりまで沈んでいる。首に軛（くびき）が渡り、そこから縄が後ろの犂へつながる。犂は長く曲がった木の柄が一本で、その握りを、笠をかぶった人が持つ。地面は掘り返された泥の塊で埋まり、あいだに水が光る。奥にもう一組、水牛と人がいて、こちらが引いているのは横木に歯の並ぶ枠に見える（犂か馬鍬かは、この一枚では決めない）。題を付けたのはアメリカの通信社で、写っている人の名は記録に無い。"}, {"f": "suigyu09.jpg", "date": "いま", "place": "東南アジア・インドネシア（ジャワ島東部・バルラン国立公園）", "title": "泥にひたる水牛の群れ（写真）", "artist": "Putriayulstr", "museum": "Wikimedia Commons", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Sekelompok_Kerbau_liar_yang_sedang_berkubang_lumpur_di_wilayah_Sabana_Bekol_Taman_Nasional_Baluran,_Banyuputih,_Sitobondo,_Jawa_Timur.jpg", "note": "撮影者の説明はインドネシア語で「東ジャワ州バルラン国立公園ベコルのサバンナで、濃い泥にひたる野生の水牛の群れ」。二〇一九年十二月二十五日。灰色の泥の窪みに、水牛が六頭あまり身を沈めている。背と頭だけが泥の上に出て、体は泥とまったく同じ灰色をしているので、まず角と耳を見つけないと、どこまでが泥でどこからが牛なのかが分からない。角は平たく、後ろへ広く開いた三日月である。一頭は目を閉じ、鼻づらだけを泥の上に置いている。奥は乾いた枯れ草の原と、地平の木立。泥の上を、長い尾の猿が一匹歩いていく。この景の最初の一枚——館が前2600〜前1900年ごろとするインダスの印章に彫られた獣を、館は buffalo と呼ぶ。四千年ちかい時をへだてて、同じ名の動物が、やはり泥のなかにいる。"}]}, {"id": "kujaku", "no": "第三十一景", "name": "孔雀", "yomi": "くじゃく", "en": "Peafowl — the train is not the tail, and its blue is not a pigment", "rep": "kujaku05.jpg", "lead": "扇のようにひらくあの羽は、尾ではない。腰のあたりから伸びる上尾筒（じょうびとう）という飾り羽で、本当の尾羽は、その後ろで扇を支えている短い二十枚のほうである。眼状斑の青と緑も塗られた色ではなく、羽の内側の構造が光を返して出す色 ── だから墨で描いても、白黒で撮っても、そこだけは残らない。", "nature": [["尾ではない。支えているほうが尾である", "クジャクの雄が扇のように立てる長い羽は、尾羽ではない。尾のつけ根を上から覆う羽が伸びたもので、鳥の体の呼び名では上尾筒（じょうびとう）という。英語でも tail とは呼ばず、train（引きずるもの）と呼び分ける。本当の尾羽は二十枚とされ、短く、地味な褐色をしている。求愛のとき、雄はまずこの尾羽を立てて扇にひらき、その前へ長い飾り羽を重ねる ── 立てているのは、目立たないほうである。この景の九枚目は後ろから撮った一枚で、中央に短い羽の扇（数えられるだけで十六本ほど）が立ち、その外へ飾り羽の長い軸が放射状に出ているのが、そのまま見える。飾り羽は毎年抜けて生えかわり、若い雄では短く、眼状斑の数も少ないとされる。扇をひらくのは雄だけで、雌にはこの羽がない。"], ["眼の色は、塗られていない", "眼状斑（がんじょうはん）の青や緑は、絵の具のように塗られた色ではない。羽の細かい枝 ── 小羽枝（しょううし）── の内側で、メラニンの棒が規則正しい格子に並んでおり、その並びの間隔に合う波長の光だけが強く返ってくる。物のかたちが出す色、構造色である。同じ一枚の羽のなかでも格子の間隔は場所ごとに違い、そのぶん青・緑・黄褐と色が変わる。見る角度を変えれば色も変わる。逆にいえば、色素をなぞる道具では写しとれない。この景の四枚目は墨だけで描かれた孔雀、二枚目は白黒で撮られた孔雀で、どちらもかたちだけが残り、色のほうが落ちている。六枚目の孔雀も色を失っているが、そちらは銀の顔料が変色したため（館の記載）で、理由が違う。逆に八枚目の写真では、逆光で羽枝が金色に透けているのに、眼状斑だけが青と緑のまま残っている。"], ["三つの種と、渡っていった像", "クジャクと呼ばれる鳥は一種ではない。インドクジャク（Pavo cristatus）はインド・スリランカからネパール、パキスタンにかけての南アジアの鳥で、首は青く、冠羽は柄の細い羽が扇に並ぶ。マクジャク（Pavo muticus）はミャンマー・タイ・ラオス・カンボジア・ベトナムからジャワ島まで、それに中国南部（雲南）にも分布し、首は緑の鱗のように見え、冠羽は房のように立つ。生息地が減って絶滅危惧種とされる。三つめのコンゴクジャク（Afropavo congensis）はアフリカのコンゴ盆地にいて、学界に記載されたのは一九三六年 ── 一九一三年に頭飾りから羽を一枚手に入れた研究者が、二十三年後、博物館の剥製の棚でその正体に行き当たった、と伝えられる。この景に並ぶ作品のうち、メソポタミア・トルコ・イランのものは、野生の孔雀が歩いていない土地でつくられている。ただし生きた孔雀も古代のうちに西へ運ばれて飼われていたとされるので、像だけが先に渡った、とは書けない。"]], "invite": "孔雀が羽をひろげている写真を、扇の縁のほうから内へ向かって見てみる。いちばん外の何本かには眼状斑がなく、細い軸と羽枝だけが長く伸びている。インドクジャクでは、その先が黒い二股になって終わる。眼が並ぶのは、その内側だけである。", "works": [{"f": "kujaku01.jpg", "date": "1〜200年", "place": "メソポタミア・セレウキア（パルティア朝）", "title": "孔雀の指輪（Peacock Ring）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1933.191", "note": "館の記載＝金と玉髄（ぎょくずい）、セレウキア、パルティア朝（前247〜後224年）、1〜200年、1.8×2.3×1cm。題は「孔雀の指輪」。館はさらに、これが印章指輪であること、腕のいい職人が楕円の石に孔雀を彫ったことを記す。金の甲に淡い桃色の石がはめられ、そこに鳥が一羽。翼を背の上へ高く立て、首を左下へ長く折り、尾は右上へ払われる。翼には細かい線が並ぶが、眼状斑にあたるものは見あたらない。彫りは石の面より沈んでいる。つまりこの鳥を孔雀と決めているのは、目に見えているものではなく、館の題と記載のほうである。指の腹ほどの大きさしかない。"}, {"f": "kujaku02.jpg", "date": "11〜12世紀", "place": "南アジア・ネパール（カトマンズ盆地）", "title": "孔雀に乗るクマーラ（Kumara Riding a Peacock）", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/38333", "note": "館の記載＝ネパール・カトマンズ盆地、タクリ期、11〜12世紀、金銅（鍍金した銅合金）。冠と首飾りをつけた子どもの姿の神が、鳥の背にまたがる。鳥の首と冠羽は子の脚のあいだから立ち上がり、体は鱗のように打ち出され、二本の脚で蓮の台に立つ。背後には飾り羽が平たい扇にひらき、一枚ずつに放射状の筋と、きのこのような形の眼状斑が浮き彫りにされている。館の写真は白黒で、鍍金の金も、孔雀の色も、この一枚には写っていない。"}, {"f": "kujaku03.jpg", "date": "15世紀", "place": "東南アジア・ベトナム", "title": "孔雀と花の文様の大皿（Dish with Peacock and Floral Motif）", "artist": "作者不詳（ベトナムの作り手）", "museum": "シカゴ美術館", "lic": "CC0", "url": "https://www.artic.edu/artworks/156487", "note": "館の記載＝ベトナム、15世紀、施釉炻器にコバルトの染付、径33.2cm。大ぶりの皿の見込みに、鳥が一羽。岩の上に立ち、翼を上げ、長い首をS字に曲げ、開いた嘴を左の花房のほうへ差し出している（拡大しても、何かをくわえてはいない）。頭からは細い冠羽が立つ。体の後ろから伸びる飾り羽は一本ずつが丸い眼で終わり、その眼のまわりに毛のような細い線が散る ── 十ばかりが数えられる。まわりには牡丹らしい花と、種の見えるざくろのような実。縁には雲の帯が回る。ベトナムはマクジャクの分布域にあたるが、この鳥が生きた孔雀を見て描かれたのかどうかは、この一枚からは決められない。"}, {"f": "kujaku04.jpg", "date": "1400年代末〜1500年代初め", "place": "中国（明）", "title": "孔雀一双（A Pair of Peafowl）", "artist": "林良（Lin Liang・中国、1416〜1480年）", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1964.242", "note": "館の記載＝林良、明（1368〜1644年）、絹本墨画の掛幅。館は作者の没年を1480年としながら制作年を1500年代初めまで取っており、記載どうしが少しずれている。館の解説は「派手な尾で見分けられる孔雀と、その右にいる雌」とし、雌が頭を下げているのは雄への敬意に見える、と書く。画面では、雄が竹と岩のあいだを頭から下へ降りていき、飾り羽だけが上へ長く流れる。羽の一枚ごとに、濃い輪とその内側の心臓形の斑が墨で置かれ、羽枝は細い斜めの線で刷かれている。色は一切ない ── 眼状斑を、墨の濃さの違いだけで描いた一枚である。"}, {"f": "kujaku05.jpg", "date": "1600年ごろ", "place": "トルコ（オスマン朝）", "title": "孔雀のかたちの書（\"Calligraphic Composition in Shape of Peacock\"）──『ベッリーニ・アルバム』の一葉", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/451978", "note": "館の記載＝トルコ、1600年ごろ、紙に墨・不透明水彩・金。『ベッリーニ・アルバム』の一葉。淡い青の地に孔雀が横向きに立ち、飾り羽が円くひらく。冠羽は三本、先が丸い。扇はいちばん外に涙形の羽先が並び（一つずつに点が入り、赤と黄が交互になる）、そのすぐ内側を、アラビア文字の帯が円をなして一周する。さらに内側には金と灰青の眼状斑が点々と置かれる。文字を読むことは当方にはできないので、何が書いてあるかは書けない。書けるのは、眼が並ぶはずのところに字が並んでいる、ということだけである。"}, {"f": "kujaku06.jpg", "date": "1800年代", "place": "イラン（ガージャール朝）", "title": "花と孔雀と肖像の円章のある壁掛け（Wall cover with flora, peacocks, and portrait medallions）", "artist": "作者不詳", "museum": "クリーブランド美術館", "lic": "CC0", "url": "https://clevelandart.org/art/1916.1483", "note": "館の記載＝イラン、ガージャール朝（1779〜1925年）、絹のタフタに手描きと型押し。館の解説は、中国製の輸出絹を壁布にするヨーロッパの流行がこの絹を生んだらしいこと、19世紀のイランに流れこんだヨーロッパの版画が文様のもとらしいこと、カシャーンの宮殿か大邸宅の壁を覆っていたかもしれないこと、そして枠の輪郭も孔雀ももとは銀で光っていて、輪郭は「いまはたいてい濃い黄色」、孔雀は「変色している」ことを記す。黄色の地に花の株が規則正しく並び、その合間に、暗い灰褐色の細長い形が同じ間隔で置かれている ── これが孔雀である。株のつなぎ目には、ガージャール朝の装いをした女性の顔が円くはめられている。銀は硫黄と結びついて黒くなる。この布は、地も鳥も、銀を失ったあとの姿である。"}, {"f": "kujaku07.jpg", "date": "1800年代", "place": "インド", "title": "ターウース（マユーリー）── Taūs (mayuri)", "artist": "作者不詳", "museum": "メトロポリタン美術館", "lic": "パブリックドメイン", "url": "https://www.metmuseum.org/art/collection/search/500709", "note": "館の記載＝インド、19世紀、木・羊皮紙・金属・羽、弓で弾く有棹の弦楽器（館の分類）。胴が孔雀の体につくられている。青い首が長く立ち上がり、金の線が網目に走る。頭の上には扇形の冠羽。胴の下には青い脚が二本。そして胴の後ろには、本物の孔雀の飾り羽が何本も差してある ── 拡大すると、赤褐色の中心を青緑の輪が囲み、そのまわりに緑と青の羽枝がほどけている眼が、三つ四つ見える。ターウースはペルシア語、マユーリーはサンスクリットで、どちらも孔雀を指す語である。描かれた孔雀ではなく、孔雀そのものが一部になっている一点。"}, {"f": "kujaku08.jpg", "date": "いま", "place": "インドネシア・東ジャワ（バルラン国立公園）", "title": "マクジャク（写真）", "artist": "Panji Gusti Akbar", "museum": "Wikimedia Commons", "lic": "CC BY-SA 4.0", "url": "https://commons.wikimedia.org/wiki/File:Javan_Green_Peafowl_in_Baluran_National_Park.jpg", "note": "撮影者の記載＝ジャワ島固有のマクジャク（Pavo muticus muticus）が、明け方の集まり場で雌に飾り羽を見せているところ。撮影は二〇一八年十一月、インドネシア東ジャワのバルラン国立公園。逆光で、扇の羽枝は金色に透けているのに、眼状斑だけが青と緑のまま残っている（なぜそう見えるのかまでは、この一枚からは決められない）。首は緑の鱗のように見え、顔には青と黄橙の裸出した皮膚、頭には房のような冠羽 ── 首が青く冠羽が扇形のインドクジャクとは、別の種である。扇のいちばん外の何本かには眼がなく、軸と羽枝だけが伸びる。飾り羽の下からは、淡い褐色の羽がのぞく。"}, {"f": "kujaku09.jpg", "date": "いま", "place": "アメリカ合衆国・フィラデルフィア（動物園。被写体はインドクジャク）", "title": "孔雀の扇 ── 後ろから（写真）", "artist": "Julie Ramsey (Ram-Man)", "museum": "Wikimedia Commons", "lic": "CC BY-SA 2.5", "url": "https://commons.wikimedia.org/wiki/File:Peacock_Fan_Feathers_Rear_View_1545px.jpg", "note": "撮影者の記載＝孔雀の扇を後ろから撮った一枚。二〇〇六年七月、アメリカのフィラデルフィア動物園。中央に、短くて地味な羽が扇のかたちに立っている（この一枚では灰色に見える）── これが本当の尾羽で、十六本ほどが数えられる（クジャクの尾羽は二十枚とされ、重なったぶんは数えられない）。その外へ、飾り羽の長い軸が放射状に伸び、途中から眼状斑の裏側が並ぶ。いちばん外の何本かには眼がなく、先が黒い二股になって終わる。羽の裏はどれも灰色で、あの色は前を向いている側にしかない。右手前には褐色の雌が一羽、扇のほうを向かずに歩いている。"}]}];